/**
 * XoHub Solutions — Main JavaScript
 * Version: 5.2.0
 * Description: Sticky header, mobile menu, search popup, Hero animations,
 *              mouse parallax, XoHubSolutions animated counters, announcement rotator, 
 *              Trusted Partners client cards, Our Services section, and Top Stats.
 * All vanilla ES2024+ with accessibility-first approach.
 * Unique XoHubSolutions naming convention to prevent conflicts.
 * Fixed: Counter animation, hover clipping, CTA visibility, responsive layouts.
 */

(() => {
    'use strict';

    // ============================================================
    // CACHE DOM REFERENCES
    // ============================================================
    const header = document.getElementById('XoHubSolutions-MainHeader');
    const hamburger = document.getElementById('XoHubSolutions-Hamburger');
    const mobileMenu = document.getElementById('mobile-menu');
    const overlay = document.getElementById('mobile-overlay');
    const closeBtn = document.getElementById('mobile-close');
    const searchBtn = document.getElementById('XoHubSolutions-SearchToggle');

    // Hero elements
    const heroContent = document.querySelector('.hero__content');
    const heroVisual = document.querySelector('.hero__visual');
    const floatingCards = document.querySelectorAll('.floating-card');
    const orbitContainer = document.querySelector('.orbit-container');
    const heroBadge = document.querySelector('.hero__badge');
    const heroTitle = document.querySelector('.hero__title');
    const heroDescription = document.querySelector('.hero__description');
    const heroCTA = document.querySelector('.hero__cta-group');
    const heroTrust = document.querySelector('.hero__trust');

    // ============================================================
    // 1. ENHANCED STICKY HEADER — Top Bar hide/show with glassmorphism
    // ============================================================
    const topBar = document.getElementById('XoHubSolutions-TopBar');
    let lastScrollY = 0;
    let ticking = false;
    let isScrollingDown = false;
    
    // Store initial topBar height once DOM is ready
    let topBarHeight = 42; // fallback value
    if (topBar) {
        // Wait for next frame to ensure CSS is applied
        requestAnimationFrame(() => {
            topBarHeight = topBar.offsetHeight;
            console.log('🎯 Top Bar Height:', topBarHeight);
        });
    }

    const handleScroll = () => {
        const scrollY = window.scrollY;
        
        // Determine scroll direction
        isScrollingDown = scrollY > lastScrollY;
        lastScrollY = scrollY;

        // Debug logging
        console.log('📊 Scroll Y:', scrollY, 'Threshold:', topBarHeight, 'Scrolled?:', scrollY > topBarHeight);

        // Sticky behavior with Top Bar hide/show
        if (scrollY > topBarHeight) {
            // Scrolled past Top Bar - make nav sticky with glassmorphism
            header.classList.add('scrolled');
            
            // Hide Top Bar using CSS class
            if (topBar) {
                topBar.classList.add('hidden');
                console.log('✅ Top Bar hidden, classes:', topBar.className);
            }
        } else {
            // At top - show Top Bar, remove glassmorphism
            header.classList.remove('scrolled');
            
            // Show Top Bar using CSS class
            if (topBar) {
                topBar.classList.remove('hidden');
                console.log('👁️ Top Bar visible, classes:', topBar.className);
            }
        }
    };

    window.addEventListener('scroll', () => {
        if (!ticking) {
            window.requestAnimationFrame(() => {
                handleScroll();
                ticking = false;
            });
            ticking = true;
        }
    });

    // Run once on load to set initial state
    handleScroll();

    // ============================================================
    // 2. MOBILE MENU — Enhanced with scroll lock and improved UX
    // ============================================================
    const openMenu = () => {
        hamburger.classList.add('active');
        mobileMenu.classList.add('open');
        overlay.classList.add('active');
        hamburger.setAttribute('aria-expanded', 'true');
        document.body.classList.add('mobile-menu-open');
        
        // Trap focus within mobile menu
        const firstFocusable = mobileMenu.querySelector('a, button');
        if (firstFocusable) {
            setTimeout(() => firstFocusable.focus(), 100);
        }
    };

    const closeMenu = () => {
        hamburger.classList.remove('active');
        mobileMenu.classList.remove('open');
        overlay.classList.remove('active');
        hamburger.setAttribute('aria-expanded', 'false');
        document.body.classList.remove('mobile-menu-open');
        
        // Return focus to hamburger
        hamburger.focus();
    };

    if (hamburger) {
        hamburger.addEventListener('click', () => {
            if (mobileMenu.classList.contains('open')) {
                closeMenu();
            } else {
                openMenu();
            }
        });
    }

    if (closeBtn) {
        closeBtn.addEventListener('click', closeMenu);
    }

    if (overlay) {
        overlay.addEventListener('click', closeMenu);
    }

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && mobileMenu.classList.contains('open')) {
            closeMenu();
        }
    });

    // ============================================================
    // 3. MOBILE DROPDOWN ACCORDION — Enhanced for mega menus
    // ============================================================
    const mobileToggles = document.querySelectorAll('.mobile-dropdown-toggle');

    mobileToggles.forEach((toggle) => {
        toggle.addEventListener('click', (e) => {
            e.preventDefault();

            const parentLi = toggle.closest('li');
            const dropdown = parentLi.querySelector('.mobile-dropdown, .mobile-mega-dropdown');

            if (!dropdown) return;

            const isOpen = dropdown.classList.contains('open');
            
            // Toggle current dropdown
            dropdown.classList.toggle('open');
            toggle.classList.toggle('active');
            toggle.setAttribute('aria-expanded', !isOpen);

            // Close other open dropdowns (accordion behavior)
            mobileToggles.forEach((otherToggle) => {
                if (otherToggle !== toggle) {
                    const otherLi = otherToggle.closest('li');
                    const otherDropdown = otherLi.querySelector('.mobile-dropdown, .mobile-mega-dropdown');
                    if (otherDropdown && otherDropdown.classList.contains('open')) {
                        otherDropdown.classList.remove('open');
                        otherToggle.classList.remove('active');
                        otherToggle.setAttribute('aria-expanded', 'false');
                    }
                }
            });
        });
    });

    // ============================================================
    // 3.5. ACTIVE PAGE INDICATOR — Auto-detect current page
    // ============================================================
    const setActivePage = () => {
        const currentPath = window.location.pathname;
        const currentPage = currentPath.split('/').pop() || 'index.html';
        
        // Set active state for main nav links
        const navLinks = document.querySelectorAll('.XoHubSolutions-NavLink');
        navLinks.forEach(link => {
            const href = link.getAttribute('href');
            if (href && href.includes(currentPage)) {
                link.classList.add('active');
            }
        });
        
        // Set active state for dropdown and mega menu links
        const dropdownLinks = document.querySelectorAll('.XoHubSolutions-DropdownLink, .XoHubSolutions-MegaLink');
        dropdownLinks.forEach(link => {
            const href = link.getAttribute('href');
            if (href && href.includes(currentPage)) {
                link.classList.add('active');
            }
        });
    };
    
    setActivePage();

    // ============================================================
    // 3.6. KEYBOARD NAVIGATION — Enhanced accessibility
    // ============================================================
    const setupKeyboardNav = () => {
        const navLinks = document.querySelectorAll('.XoHubSolutions-NavLink');
        
        navLinks.forEach((link, index) => {
            link.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowRight') {
                    e.preventDefault();
                    const nextLink = navLinks[index + 1] || navLinks[0];
                    nextLink.focus();
                } else if (e.key === 'ArrowLeft') {
                    e.preventDefault();
                    const prevLink = navLinks[index - 1] || navLinks[navLinks.length - 1];
                    prevLink.focus();
                } else if (e.key === 'Enter' || e.key === ' ') {
                    // For dropdowns, open on Enter/Space
                    const dropdown = link.closest('.XoHubSolutions-Dropdown');
                    if (dropdown) {
                        const menu = dropdown.querySelector('.XoHubSolutions-DropdownMenu, .XoHubSolutions-MegaMenu');
                        if (menu) {
                            e.preventDefault();
                            // Toggle visibility
                            const isVisible = menu.style.visibility === 'visible';
                            menu.style.visibility = isVisible ? 'hidden' : 'visible';
                            menu.style.opacity = isVisible ? '0' : '1';
                            menu.style.pointerEvents = isVisible ? 'none' : 'all';
                            link.setAttribute('aria-expanded', !isVisible);
                        }
                    }
                } else if (e.key === 'Escape') {
                    // Close any open dropdowns
                    const dropdown = link.closest('.XoHubSolutions-Dropdown');
                    if (dropdown) {
                        const menu = dropdown.querySelector('.XoHubSolutions-DropdownMenu, .XoHubSolutions-MegaMenu');
                        if (menu) {
                            menu.style.visibility = 'hidden';
                            menu.style.opacity = '0';
                            menu.style.pointerEvents = 'none';
                            link.setAttribute('aria-expanded', 'false');
                            link.focus();
                        }
                    }
                }
            });
        });
    };
    
    setupKeyboardNav();

    // ============================================================
    // 4. SEARCH POPUP / MODAL (Vercel/Stripe style)
    // ============================================================
    if (searchBtn) {
        const searchPopupId = 'xohub-search-popup';
        if (!document.getElementById(searchPopupId)) {
            const popupContainer = document.createElement('div');
            popupContainer.id = searchPopupId;
            popupContainer.setAttribute('role', 'dialog');
            popupContainer.setAttribute('aria-modal', 'true');
            popupContainer.setAttribute('aria-label', 'Search');
            popupContainer.style.display = 'none';

            popupContainer.innerHTML = `
                <div class="search-popup-overlay" id="search-overlay"></div>
                <div class="search-popup-content">
                    <button class="search-popup-close" id="search-close" aria-label="Close search">
                        <i class="fas fa-times"></i>
                    </button>
                    <div class="search-popup-inner">
                        <div class="search-icon-big">
                            <i class="fas fa-search"></i>
                        </div>
                        <input 
                            type="text" 
                            class="search-popup-input" 
                            id="search-input" 
                            placeholder="Search for services, products, articles..." 
                            autocomplete="off"
                            aria-label="Search query"
                        />
                        <div class="search-hint">
                            Press <kbd>Esc</kbd> to close
                        </div>
                    </div>
                </div>
            `;

            document.body.appendChild(popupContainer);

            const styleId = 'xohub-search-popup-styles';
            if (!document.getElementById(styleId)) {
                const style = document.createElement('style');
                style.id = styleId;
                style.textContent = `
                    #xohub-search-popup {
                        position: fixed;
                        top: 0;
                        left: 0;
                        width: 100%;
                        height: 100%;
                        z-index: 9999;
                        display: none;
                        align-items: flex-start;
                        justify-content: center;
                        background: rgba(26, 26, 46, 0.85);
                        backdrop-filter: blur(12px);
                        -webkit-backdrop-filter: blur(12px);
                        animation: searchFadeIn 0.25s ease;
                    }

                    #xohub-search-popup.active {
                        display: flex;
                    }

                    @keyframes searchFadeIn {
                        from { opacity: 0; transform: scale(0.98); }
                        to { opacity: 1; transform: scale(1); }
                    }

                    .search-popup-overlay {
                        position: absolute;
                        top: 0;
                        left: 0;
                        width: 100%;
                        height: 100%;
                        cursor: default;
                    }

                    .search-popup-content {
                        position: relative;
                        width: 100%;
                        max-width: 680px;
                        margin: 15vh 24px 0;
                        padding: 40px 32px 32px;
                        background: var(--color-white);
                        border-radius: 20px;
                        box-shadow: 0 32px 80px rgba(0, 0, 0, 0.25);
                        animation: searchSlideUp 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
                        z-index: 10;
                    }

                    @keyframes searchSlideUp {
                        from { opacity: 0; transform: translateY(30px) scale(0.96); }
                        to { opacity: 1; transform: translateY(0) scale(1); }
                    }

                    .search-popup-close {
                        position: absolute;
                        top: 16px;
                        right: 20px;
                        background: transparent;
                        border: none;
                        font-size: 1.5rem;
                        color: var(--color-charcoal);
                        cursor: pointer;
                        padding: 8px;
                        border-radius: 50%;
                        transition: all 0.2s ease;
                        line-height: 1;
                    }

                    .search-popup-close:hover {
                        background: var(--color-off-white);
                        color: var(--color-purple);
                        transform: rotate(90deg);
                    }

                    .search-popup-inner {
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        gap: 16px;
                    }

                    .search-icon-big {
                        font-size: 2.4rem;
                        color: var(--color-lime);
                        margin-bottom: 4px;
                    }

                    .search-popup-input {
                        width: 100%;
                        padding: 16px 0;
                        font-family: var(--font-primary);
                        font-size: 1.8rem;
                        font-weight: var(--font-weight-medium);
                        color: var(--color-charcoal);
                        background: transparent;
                        border: none;
                        border-bottom: 3px solid var(--color-gray-light);
                        outline: none;
                        transition: border-color 0.25s ease;
                        text-align: center;
                        letter-spacing: -0.02em;
                    }

                    .search-popup-input::placeholder {
                        color: var(--color-gray-mid);
                        font-weight: var(--font-weight-regular);
                        font-size: 1.2rem;
                        opacity: 0.6;
                    }

                    .search-popup-input:focus {
                        border-bottom-color: var(--color-purple);
                    }

                    .search-hint {
                        font-size: 0.75rem;
                        color: var(--color-gray-mid);
                        margin-top: 8px;
                    }

                    .search-hint kbd {
                        background: var(--color-off-white);
                        padding: 2px 10px;
                        border-radius: 4px;
                        border: 1px solid var(--color-gray-light);
                        font-size: 0.7rem;
                        font-family: var(--font-primary);
                        font-weight: var(--font-weight-medium);
                    }

                    @media (max-width: 768px) {
                        .search-popup-content {
                            margin: 12vh 16px 0;
                            padding: 32px 20px 24px;
                        }
                        .search-popup-input {
                            font-size: 1.4rem;
                            padding: 12px 0;
                        }
                        .search-popup-input::placeholder {
                            font-size: 1rem;
                        }
                        .search-icon-big {
                            font-size: 1.8rem;
                        }
                    }

                    @media (max-width: 425px) {
                        .search-popup-content {
                            margin: 8vh 12px 0;
                            padding: 24px 16px 20px;
                            border-radius: 16px;
                        }
                        .search-popup-input {
                            font-size: 1.1rem;
                        }
                        .search-popup-input::placeholder {
                            font-size: 0.85rem;
                        }
                        .search-popup-close {
                            top: 12px;
                            right: 14px;
                            font-size: 1.2rem;
                        }
                    }
                `;
                document.head.appendChild(style);
            }

            const popup = document.getElementById(searchPopupId);
            const overlayClose = document.getElementById('search-overlay');
            const closePopupBtn = document.getElementById('search-close');
            const searchInput = document.getElementById('search-input');

            const openSearchPopup = () => {
                popup.style.display = 'flex';
                void popup.offsetWidth;
                popup.classList.add('active');
                document.body.style.overflow = 'hidden';
                setTimeout(() => searchInput.focus(), 150);
            };

            const closeSearchPopup = () => {
                popup.classList.remove('active');
                setTimeout(() => {
                    popup.style.display = 'none';
                    document.body.style.overflow = '';
                    searchInput.value = '';
                }, 250);
                searchBtn.focus();
            };

            searchBtn.addEventListener('click', (e) => {
                e.preventDefault();
                openSearchPopup();
            });

            if (closePopupBtn) {
                closePopupBtn.addEventListener('click', closeSearchPopup);
            }

            if (overlayClose) {
                overlayClose.addEventListener('click', closeSearchPopup);
            }

            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && popup.classList.contains('active')) {
                    closeSearchPopup();
                }
            });

            searchInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && searchInput.value.trim() !== '') {
                    console.log('🔍 Searching for:', searchInput.value);
                }
            });
        }
    }

    // ============================================================
    // 5. HERO — SCROLL-TRIGGERED ANIMATIONS (Intersection Observer)
    // ============================================================
    const heroElements = [
        { el: heroBadge, delay: 0 },
        { el: heroTitle, delay: 100 },
        { el: heroDescription, delay: 200 },
        { el: heroCTA, delay: 300 },
        { el: heroTrust, delay: 400 },
        { el: heroVisual, delay: 100 }
    ];

    // Set initial opacity for animation
    heroElements.forEach(({ el }) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(30px)';
            el.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Also set floating cards for animation
    floatingCards.forEach((card) => {
        card.style.opacity = '0';
        card.style.transform = 'translateY(20px) scale(0.95)';
        card.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
    });

    // Create Intersection Observer for Hero
    const heroObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate main hero elements with staggered delay
                heroElements.forEach(({ el, delay }) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, delay);
                    }
                });

                // Animate floating cards with staggered delay
                floatingCards.forEach((card, index) => {
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0) scale(1)';
                    }, 500 + (index * 100));
                });

                // Stop observing once triggered
                heroObserver.disconnect();
            }
        });
    }, {
        threshold: 0.15,
        rootMargin: '0px 0px -50px 0px'
    });

    // Observe the hero section
    const heroSection = document.getElementById('hero');
    if (heroSection) {
        heroObserver.observe(heroSection);
    }

    // ============================================================
    // 6. HERO — MOUSE PARALLAX (3D effect on orbit container)
    // ============================================================
    if (orbitContainer && window.innerWidth > 992) {
        let mouseX = 0;
        let mouseY = 0;
        let targetX = 0;
        let targetY = 0;
        let parallaxAnimationId = null;

        const handleMouseMove = (e) => {
            const rect = orbitContainer.getBoundingClientRect();
            const centerX = rect.left + rect.width / 2;
            const centerY = rect.top + rect.height / 2;

            // Normalize mouse position relative to center (-1 to 1)
            mouseX = (e.clientX - centerX) / (rect.width / 2);
            mouseY = (e.clientY - centerY) / (rect.height / 2);

            // Clamp values
            mouseX = Math.max(-1, Math.min(1, mouseX));
            mouseY = Math.max(-1, Math.min(1, mouseY));
        };

        const animateParallax = () => {
            // Smooth interpolation (easing)
            targetX += (mouseX - targetX) * 0.08;
            targetY += (mouseY - targetY) * 0.08;

            // Apply transform with subtle rotation and translation
            const rotateX = targetY * 6;
            const rotateY = targetX * 6;
            const translateX = targetX * 8;
            const translateY = targetY * 8;

            orbitContainer.style.transform = `
                perspective(800px)
                rotateX(${rotateX}deg)
                rotateY(${rotateY}deg)
                translateX(${translateX}px)
                translateY(${translateY}px)
            `;

            // Also apply subtle parallax to floating cards
            floatingCards.forEach((card, index) => {
                const factor = 0.3 + (index * 0.1);
                const cardX = targetX * -6 * factor;
                const cardY = targetY * 6 * factor;
                card.style.transform = `translate(${cardX}px, ${cardY}px)`;
            });

            parallaxAnimationId = requestAnimationFrame(animateParallax);
        };

        const heroVisualParent = heroVisual;
        if (heroVisualParent) {
            heroVisualParent.addEventListener('mousemove', handleMouseMove);
            // Start animation loop
            animateParallax();

            // Reset on mouse leave
            heroVisualParent.addEventListener('mouseleave', () => {
                mouseX = 0;
                mouseY = 0;
                setTimeout(() => {
                    targetX = 0;
                    targetY = 0;
                }, 50);
            });

            // Cleanup on window resize to avoid memory leaks
            window.addEventListener('resize', () => {
                if (window.innerWidth <= 992 && parallaxAnimationId) {
                    cancelAnimationFrame(parallaxAnimationId);
                    parallaxAnimationId = null;
                    orbitContainer.style.transform = '';
                    floatingCards.forEach((card) => {
                        card.style.transform = '';
                    });
                }
            });
        }
    }

    // ============================================================
    // 7. HERO — CARD INTERACTION (Enhanced hover effects)
    // ============================================================
    floatingCards.forEach((card) => {
        card.addEventListener('mouseenter', function () {
            this.style.transform = 'translateY(-8px) scale(1.04)';
            this.style.boxShadow = '0 32px 80px rgba(124, 58, 237, 0.15)';
            this.style.borderColor = 'var(--color-purple-light)';
        });

        card.addEventListener('mouseleave', function () {
            this.style.transform = '';
            this.style.boxShadow = '';
            this.style.borderColor = '';
        });
    });

    // ============================================================
    // 8. STATISTICS — COUNT-UP ANIMATION (XoHubSolutions Impact Section)
    // ============================================================
    const XoHubSolutionsCounters = document.querySelectorAll('.XoHubSolutions-AnimatedCounter');
    let XoHubSolutionsCountersAnimated = false;

    const XoHubSolutionsAnimateCountUp = (element, target, duration = 2000) => {
        const startTime = performance.now();
        const startValue = 0;

        const updateCount = (currentTime) => {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);

            // Ease-out cubic for smooth deceleration
            const eased = 1 - Math.pow(1 - progress, 3);
            const currentValue = Math.floor(eased * target);

            element.textContent = currentValue;

            if (progress < 1) {
                requestAnimationFrame(updateCount);
            } else {
                element.textContent = target;
            }
        };

        requestAnimationFrame(updateCount);
    };

    // Create Intersection Observer for XoHubSolutions Impact Section
    const XoHubSolutionsImpactObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting && !XoHubSolutionsCountersAnimated) {
                XoHubSolutionsCountersAnimated = true;

                XoHubSolutionsCounters.forEach((counterEl) => {
                    const target = parseInt(counterEl.getAttribute('data-count'), 10);
                    if (isNaN(target)) return;

                    // Reset to 0 before animating
                    counterEl.textContent = '0';

                    // Animate to target
                    XoHubSolutionsAnimateCountUp(counterEl, target);
                });

                // Disconnect after triggering once
                XoHubSolutionsImpactObserver.disconnect();
            }
        });
    }, {
        threshold: 0.2,
        rootMargin: '0px 0px -100px 0px'
    });

    // Observe the XoHubSolutions Impact Section
    const XoHubSolutionsImpactSection = document.querySelector('.XoHubSolutions-ImpactSection');
    if (XoHubSolutionsImpactSection && XoHubSolutionsCounters.length > 0) {
        XoHubSolutionsImpactObserver.observe(XoHubSolutionsImpactSection);
    }

    // ============================================================
    // 9. TRUST SECTION — SCROLL-TRIGGERED FADE-UP (Cards)
    // ============================================================
    const trustCards = document.querySelectorAll('.stat-card, .feature-card');
    const trustBadges = document.querySelectorAll('.trusted-by__badge, .stats__badge, .features__badge');
    const trustTitles = document.querySelectorAll('.trusted-by__title, .stats__title, .features__title');
    const trustSubtitles = document.querySelectorAll('.trusted-by__subtitle, .stats__subtitle, .features__subtitle');

    // Set initial state for trust section elements
    const trustElements = [
        ...trustBadges,
        ...trustTitles,
        ...trustSubtitles,
        ...trustCards
    ];

    trustElements.forEach((el, index) => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(24px)';
        el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 30}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 30}ms`;
    });

    // Observer for trust section
    const trustObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                trustElements.forEach((el) => {
                    el.style.opacity = '1';
                    el.style.transform = 'translateY(0)';
                });
                trustObserver.disconnect();
            }
        });
    }, {
        threshold: 0.1,
        rootMargin: '0px 0px -50px 0px'
    });

    const trustSection = document.getElementById('trust-section');
    if (trustSection) {
        trustObserver.observe(trustSection);
    }

    // ============================================================
    // 10. LOGO ITEM — Enhanced hover with tooltip effect
    // ============================================================
    const logoItems = document.querySelectorAll('.logo-item');
    logoItems.forEach((item) => {
        const label = item.getAttribute('aria-label') || 'Partner';
        item.setAttribute('title', label);
    });

    // ============================================================
    // 11. INITIAL ARIA SETUP
    // ============================================================
    if (hamburger) {
        hamburger.setAttribute('aria-expanded', 'false');
    }

    console.log('🚀 XoHub Solutions — Full website initialized (Phases 1, 2, & 3).');

    // ============================================================
    // 12. TOP BAR — ANNOUNCEMENT TEXT ROTATOR (FIXED)
    // ============================================================
    const initTextRotator = () => {
        // Check for reduced motion preference
        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (prefersReducedMotion) {
            // If user prefers reduced motion, keep the first message only
            const topBarText = document.querySelector('.XoHubSolutions-TopBarText');
            if (topBarText) {
                // Keep existing content as-is
                return;
            }
            return;
        }

        // Define the messages
        const messages = [
            { text: 'We help businesses grow with innovative digital solutions.', highlight: 'grow' },
            { text: 'Custom Web Development, Mobile Apps & AI Solutions.', highlight: 'Web Development' },
            { text: 'Serving startups, SMEs and enterprises worldwide.', highlight: 'startups' },
            { text: 'Free consultation for your next digital project.', highlight: 'Free consultation' },
            { text: 'Your trusted partner for digital transformation.', highlight: 'digital transformation' }
        ];

        // Find the top bar text element
        const topBarText = document.querySelector('.XoHubSolutions-TopBarText');
        if (!topBarText) return;

        // Build message HTML with highlight
        const buildMessageHTML = (text, highlight) => {
            // Escape any HTML in the text
            const escapedText = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const highlightEscaped = highlight.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            // Replace the highlight word/phrase with a wrapped version (case-insensitive)
            const regex = new RegExp(highlightEscaped.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
            const result = escapedText.replace(regex, `<span class="XoHubSolutions-HighlightGreen">${highlightEscaped}</span>`);
            return result;
        };

        // Create the rotator structure
        const createRotator = () => {
            // Clear the current content
            topBarText.innerHTML = '';

            // Create the rotator container
            const rotator = document.createElement('span');
            rotator.className = 'XoHubSolutions-TextRotator';
            rotator.setAttribute('role', 'marquee');
            rotator.setAttribute('aria-label', 'Announcement rotator');

            // Create two items
            const item1 = document.createElement('span');
            item1.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorCurrent';
            item1.innerHTML = buildMessageHTML(messages[0].text, messages[0].highlight);

            const item2 = document.createElement('span');
            item2.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorSlideIn';
            item2.innerHTML = buildMessageHTML(messages[1].text, messages[1].highlight);

            rotator.appendChild(item1);
            rotator.appendChild(item2);
            topBarText.appendChild(rotator);

            return { rotator };
        };

        const { rotator } = createRotator();
        let currentIndex = 1;
        let isAnimating = false;
        let rotationInterval = null;

        // Function to rotate to the next message
        const rotateMessage = () => {
            if (isAnimating) return;
            isAnimating = true;

            const currentItem = rotator.querySelector('.XoHubSolutions-RotatorItem.XoHubSolutions-RotatorCurrent');
            const nextItem = rotator.querySelector('.XoHubSolutions-RotatorItem.XoHubSolutions-RotatorSlideIn');

            if (!currentItem || !nextItem) {
                isAnimating = false;
                return;
            }

            // Determine the next message index
            const nextIndex = (currentIndex + 1) % messages.length;

            // Update the next item's content to the new message
            nextItem.innerHTML = buildMessageHTML(messages[nextIndex].text, messages[nextIndex].highlight);

            // Trigger animation
            nextItem.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorSlideIn';
            void nextItem.offsetWidth; // Force reflow
            nextItem.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorSlideIn XoHubSolutions-RotatorActive';
            currentItem.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorSlideOut';

            // Cleanup after transition
            const cleanup = () => {
                const activeItem = rotator.querySelector('.XoHubSolutions-RotatorItem.XoHubSolutions-RotatorSlideIn.XoHubSolutions-RotatorActive');
                if (activeItem) {
                    activeItem.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorCurrent';
                    currentIndex = nextIndex;
                }

                const oldItem = rotator.querySelector('.XoHubSolutions-RotatorItem.XoHubSolutions-RotatorSlideOut');
                if (oldItem) {
                    oldItem.remove();
                }

                const newNextIndex = (currentIndex + 1) % messages.length;
                const newItem = document.createElement('span');
                newItem.className = 'XoHubSolutions-RotatorItem XoHubSolutions-RotatorSlideIn';
                newItem.innerHTML = buildMessageHTML(messages[newNextIndex].text, messages[newNextIndex].highlight);
                rotator.appendChild(newItem);

                isAnimating = false;
            };

            const onTransitionEnd = (e) => {
                if (e.target === currentItem && e.propertyName === 'transform') {
                    currentItem.removeEventListener('transitionend', onTransitionEnd);
                    cleanup();
                }
            };

            const fallbackTimer = setTimeout(() => {
                currentItem.removeEventListener('transitionend', onTransitionEnd);
                if (isAnimating) {
                    cleanup();
                }
            }, 800);

            currentItem.addEventListener('transitionend', onTransitionEnd);

            // Wrap cleanup to clear the fallback timer
            const originalCleanup = cleanup;
            cleanup = () => {
                clearTimeout(fallbackTimer);
                originalCleanup();
            };
        };

        // Start the rotation loop
        const startRotation = () => {
            if (rotationInterval) {
                clearInterval(rotationInterval);
            }
            rotationInterval = setInterval(rotateMessage, 4500);
        };

        startRotation();

        // Pause rotation when the user hovers over the top bar
        let pauseTimer = null;
        const topBar = document.getElementById('top-bar');

        const pauseRotation = () => {
            if (rotationInterval) {
                clearInterval(rotationInterval);
                rotationInterval = null;
            }
        };

        const resumeRotation = () => {
            clearTimeout(pauseTimer);
            pauseTimer = setTimeout(() => {
                startRotation();
            }, 1000);
        };

        if (topBar) {
            topBar.addEventListener('mouseenter', pauseRotation);
            topBar.addEventListener('mouseleave', resumeRotation);

            // Handle visibility change (pause when tab is hidden)
            document.addEventListener('visibilitychange', () => {
                if (document.hidden) {
                    pauseRotation();
                } else {
                    resumeRotation();
                }
            });
        }

        // Cleanup function
        const cleanupRotator = () => {
            if (rotationInterval) {
                clearInterval(rotationInterval);
                rotationInterval = null;
            }
            clearTimeout(pauseTimer);
            if (topBar) {
                topBar.removeEventListener('mouseenter', pauseRotation);
                topBar.removeEventListener('mouseleave', resumeRotation);
            }
        };

        // Store cleanup function
        window.__cleanupRotator = cleanupRotator;

        console.log('Announcement rotator initialized with', messages.length, 'messages.');
    };

    // Initialize the rotator after the DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initTextRotator);
    } else {
        initTextRotator();
    }
})();

