const initDevelopmentProcessAnimations = () => {
    const processSteps = document.querySelectorAll('.process-step');
    const processLineFill = document.querySelector('.process-timeline__line-fill');
    const dpBadge = document.querySelector('.development-process__badge');
    const dpTitle = document.querySelector('.development-process__title');
    const dpSubtitle = document.querySelector('.development-process__subtitle');

    // Set initial state for header elements
    const headerElements = [dpBadge, dpTitle, dpSubtitle];
    headerElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for process steps
    processSteps.forEach((step, index) => {
        const card = step.querySelector('.process-step__card');
        if (card) {
            card.style.opacity = '0';
            card.style.transform = 'translateY(30px)';
            card.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 120}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 120}ms`;
        }
        // Hide connector dots initially
        const connector = step.querySelector('.process-step__connector');
        if (connector) {
            connector.style.transition = 'all 0.6s ease';
        }
    });

    // Create observer
    const dpObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate header elements
                headerElements.forEach((el) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 100);
                    }
                });

                // Animate process steps with staggered delay
                processSteps.forEach((step, index) => {
                    const card = step.querySelector('.process-step__card');
                    if (card) {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 120));
                    }

                    // Add active class with delay to trigger connector animation
                    setTimeout(() => {
                        step.classList.add('active');
                    }, 400 + (index * 120));
                });

                // Animate the timeline fill line (only on desktop)
                if (processLineFill) {
                    setTimeout(() => {
                        processLineFill.classList.add('animated');
                    }, 500);
                }

                dpObserver.disconnect();
            }
        });
    }, {
        threshold: 0.15,
        rootMargin: '0px 0px -50px 0px'
    });

    const dpSection = document.getElementById('development-process');
    if (dpSection) {
        dpObserver.observe(dpSection);
    }
};

// Initialize development process animations
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDevelopmentProcessAnimations);
} else {
    initDevelopmentProcessAnimations();
}

