// 17. TECHNOLOGIES — SCROLL-TRIGGERED ANIMATIONS
// ============================================================
const initTechnologiesAnimations = () => {
    const techCategories = document.querySelectorAll('.tech-category');
    const techBadges = document.querySelectorAll('.tech-badge');
    const techStats = document.querySelectorAll('.tech-stat__count');
    const techBadge = document.querySelector('.technologies-section__badge');
    const techTitle = document.querySelector('.technologies-section__title');
    const techSubtitle = document.querySelector('.technologies-section__subtitle');

    // Set initial state for header elements
    const headerElements = [techBadge, techTitle, techSubtitle];
    headerElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for category cards
    techCategories.forEach((category, index) => {
        category.style.opacity = '0';
        category.style.transform = 'translateY(30px)';
        category.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 100}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 100}ms`;
    });

    // Set initial state for badges (staggered within categories)
    techBadges.forEach((badge, index) => {
        badge.style.opacity = '0';
        badge.style.transform = 'scale(0.9)';
        badge.style.transition = `opacity 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 20)}ms, transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 20)}ms`;
    });

    // Set initial state for stats
    let statsAnimated = false;

    const animateCount = (element, target, duration = 2000) => {
        const startTime = performance.now();
        const startValue = 0;

        const updateCount = (currentTime) => {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            const currentValue = Math.floor(eased * target);
            element.textContent = currentValue;

            if (progress < 1) {
                requestAnimationFrame(updateCount);
            } else {
                element.textContent = target;
            }
        };

        requestAnimationFrame(updateCount);
    };

    // Create observer
    const techObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate header elements
                headerElements.forEach((el) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 100);
                    }
                });

                // Animate category cards
                techCategories.forEach((category, index) => {
                    setTimeout(() => {
                        category.style.opacity = '1';
                        category.style.transform = 'translateY(0)';
                    }, 200 + (index * 100));
                });

                // Animate badges with stagger
                techBadges.forEach((badge, index) => {
                    setTimeout(() => {
                        badge.style.opacity = '1';
                        badge.style.transform = 'scale(1)';
                    }, 400 + (index * 20));
                });

                // Animate stats counters
                if (!statsAnimated) {
                    statsAnimated = true;
                    techStats.forEach((statEl) => {
                        const target = parseInt(statEl.getAttribute('data-count'), 10);
                        if (isNaN(target)) return;
                        statEl.textContent = '0';
                        animateCount(statEl, target);
                    });
                }

                techObserver.disconnect();
            }
        });
    }, {
        threshold: 0.12,
        rootMargin: '0px 0px -50px 0px'
    });

    const techSection = document.getElementById('technologies');
    if (techSection) {
        techObserver.observe(techSection);
    }
};

// Initialize technologies animations
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initTechnologiesAnimations);
} else {
    initTechnologiesAnimations();
}

