// 21. CTA — SCROLL-TRIGGERED ANIMATIONS
// ============================================================
const initCtaAnimations = () => {
    const ctaContent = document.querySelector('.cta-section__content');
    const ctaCard = document.querySelector('.cta-card');
    const ctaBadge = document.querySelector('.cta-section__badge');
    const ctaTitle = document.querySelector('.cta-section__title');
    const ctaDescription = document.querySelector('.cta-section__description');
    const ctaBenefits = document.querySelector('.cta-section__benefits');
    const ctaButtons = document.querySelector('.cta-section__buttons');

    // Set initial state for all CTA elements
    const ctaElements = [
        ctaBadge,
        ctaTitle,
        ctaDescription,
        ctaBenefits,
        ctaButtons,
        ctaCard
    ];

    ctaElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(30px)';
            el.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set individual delays for staggered animation
    const ctaElementsWithDelay = [
        { el: ctaBadge, delay: 100 },
        { el: ctaTitle, delay: 150 },
        { el: ctaDescription, delay: 200 },
        { el: ctaBenefits, delay: 250 },
        { el: ctaButtons, delay: 300 },
        { el: ctaCard, delay: 350 }
    ];

    // Create observer
    const ctaObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                ctaElementsWithDelay.forEach(({ el, delay }) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, delay);
                    }
                });
                ctaObserver.disconnect();
            }
        });
    }, {
        threshold: 0.15,
        rootMargin: '0px 0px -50px 0px'
    });

    const ctaSection = document.getElementById('cta');
    if (ctaSection) {
        ctaObserver.observe(ctaSection);
    }
};

// Initialize CTA animations
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initCtaAnimations);
} else {
    initCtaAnimations();
}

// ============================================================
// 22. FOOTER — NEWSLETTER & BACK TO TOP
// ============================================================
const initFooterInteractions = () => {
    // ----- Newsletter Form -----
    const newsletterForm = document.getElementById('newsletter-form');
    const emailInput = document.getElementById('newsletter-email');
    const errorEl = document.getElementById('newsletter-error');
    const successEl = document.getElementById('newsletter-success');

    if (newsletterForm && emailInput) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();

            // Reset messages
            errorEl.classList.remove('visible');
            successEl.classList.remove('visible');

            const email = emailInput.value.trim();

            // Simple email validation
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!email || !emailRegex.test(email)) {
                errorEl.textContent = 'Please enter a valid email address.';
                errorEl.classList.add('visible');
                return;
            }

            // Simulate success
            successEl.textContent = 'Thank you for subscribing!';
            successEl.classList.add('visible');
            emailInput.value = '';

            // Hide success after 5 seconds
            setTimeout(() => {
                successEl.classList.remove('visible');
            }, 5000);

            console.log('📧 Newsletter subscription:', email);
        });

        // Clear error on input
        emailInput.addEventListener('input', () => {
            errorEl.classList.remove('visible');
        });
    }

    // ----- Back to Top Button -----
    const backToTopBtn = document.getElementById('back-to-top');

    if (backToTopBtn) {
        // Show/hide button based on scroll position
        const toggleBackToTop = () => {
            const scrollY = window.scrollY;
            if (scrollY > 400) {
                backToTopBtn.classList.add('visible');
            } else {
                backToTopBtn.classList.remove('visible');
            }
        };

        // Initial check
        toggleBackToTop();

        // Throttled scroll listener
        let scrollTicking = false;
        window.addEventListener('scroll', () => {
            if (!scrollTicking) {
                window.requestAnimationFrame(() => {
                    toggleBackToTop();
                    scrollTicking = false;
                });
                scrollTicking = true;
            }
        });

        // Click handler
        backToTopBtn.addEventListener('click', () => {
            window.scrollTo({
                top: 0,
                behavior: 'smooth'
            });
        });

        // Keyboard support
        backToTopBtn.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                window.scrollTo({
                    top: 0,
                    behavior: 'smooth'
                });
            }
        });
    }

    // ----- Footer Scroll Animations -----
    const footerColumns = document.querySelectorAll('.footer__column');
    const footerNewsletter = document.querySelector('.footer__newsletter');
    const footerBottom = document.querySelector('.footer__bottom');

    // Set initial state
    const footerElements = [...footerColumns, footerNewsletter, footerBottom];
    footerElements.forEach((el, index) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 50}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 50}ms`;
        }
    });

    // Observer for footer animations
    const footerObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                footerElements.forEach((el) => {
                    if (el) {
                        el.style.opacity = '1';
                        el.style.transform = 'translateY(0)';
                    }
                });
                footerObserver.disconnect();
            }
        });
    }, {
        threshold: 0.1,
        rootMargin: '0px 0px -50px 0px'
    });

    const footerSection = document.querySelector('.main-footer');
    if (footerSection) {
        footerObserver.observe(footerSection);
    }

    console.log('🚀 Footer interactions initialized.');
};

// Initialize footer interactions
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFooterInteractions);
} else {
    initFooterInteractions();
}

