const initMissionVisionAnimations = () => {
    const mvCards = document.querySelectorAll('.mv-card');
    const mvBadge = document.querySelector('.mission-vision__badge');
    const mvTitle = document.querySelector('.mission-vision__title');
    const mvSubtitle = document.querySelector('.mission-vision__subtitle');

    // Set initial state for header elements
    const headerElements = [mvBadge, mvTitle, mvSubtitle];
    headerElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for cards
    mvCards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.transform = 'translateY(30px)';
        card.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 150}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 150}ms`;
    });

    // Create observer
    const mvObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate header elements
                headerElements.forEach((el) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 100);
                    }
                });

                // Animate cards with staggered delay
                mvCards.forEach((card, index) => {
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    }, 250 + (index * 150));
                });

                mvObserver.disconnect();
            }
        });
    }, {
        threshold: 0.15,
        rootMargin: '0px 0px -50px 0px'
    });

    const mvSection = document.getElementById('mission-vision');
    if (mvSection) {
        mvObserver.observe(mvSection);
    }
};

// Initialize Mission & Vision animations
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMissionVisionAnimations);
} else {
    initMissionVisionAnimations();
}

