// ============================================================
// 28. WHY CHOOSE — SCROLL-TRIGGERED ANIMATIONS & COUNTERS
// ============================================================
const initWhyChooseAnimations = () => {
    const whyCards = document.querySelectorAll('.why-card');
    const whyBadge = document.querySelector('.why-choose__badge');
    const whyTitle = document.querySelector('.why-choose__title');
    const whySubtitle = document.querySelector('.why-choose__subtitle');
    const whyVisual = document.querySelector('.why-choose__visual');
    const miniStats = document.querySelectorAll('.mini-stat__count');

    // Set initial state for header elements
    const headerElements = [whyBadge, whyTitle, whySubtitle];
    headerElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for visual
    if (whyVisual) {
        whyVisual.style.opacity = '0';
        whyVisual.style.transform = 'scale(0.95)';
        whyVisual.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
    }

    // Set initial state for cards
    whyCards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.transform = 'translateX(-15px)';
        card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms`;
    });

    // Set initial state for mini stats
    let statsAnimated = false;

    const animateCount = (element, target, duration = 1800) => {
        const startTime = performance.now();
        const startValue = 0;

        const updateCount = (currentTime) => {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            const currentValue = Math.floor(eased * target);
            element.textContent = currentValue;

            if (progress < 1) {
                requestAnimationFrame(updateCount);
            } else {
                element.textContent = target;
            }
        };

        requestAnimationFrame(updateCount);
    };

    // Create observer
    const whyObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate header elements
                headerElements.forEach((el) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 100);
                    }
                });

                // Animate visual
                if (whyVisual) {
                    setTimeout(() => {
                        whyVisual.style.opacity = '1';
                        whyVisual.style.transform = 'scale(1)';
                    }, 150);
                }

                // Animate cards with staggered delay
                whyCards.forEach((card, index) => {
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateX(0)';
                    }, 250 + (index * 60));
                });

                // Animate mini stats counters
                if (!statsAnimated) {
                    statsAnimated = true;
                    miniStats.forEach((statEl) => {
                        const target = parseInt(statEl.getAttribute('data-count'), 10);
                        if (isNaN(target)) return;
                        statEl.textContent = '0';
                        animateCount(statEl, target);
                    });
                }

                whyObserver.disconnect();
            }
        });
    }, {
        threshold: 0.12,
        rootMargin: '0px 0px -50px 0px'
    });

    const whySection = document.getElementById('why-choose');
    if (whySection) {
        whyObserver.observe(whySection);
    }
};

// Initialize Why Choose animations
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initWhyChooseAnimations);
} else {
    initWhyChooseAnimations();
}

