// 36. OPEN POSITIONS — FILTER & ANIMATIONS
// ============================================================
const initOpenPositions = () => {
    const jobCards = document.querySelectorAll('.job-card');
    const jobSearch = document.getElementById('job-search');
    const filterSelects = document.querySelectorAll('.filter-select');
    const filterClearBtn = document.querySelector('.btn-filter-clear');
    const filterSearchBtn = document.querySelector('.btn-filter-search');
    const jobsCount = document.querySelector('.jobs-count');

    // Store all job cards data for filtering
    const jobsData = [];

    jobCards.forEach((card) => {
        jobsData.push({
            element: card,
            department: card.dataset.department || '',
            type: card.dataset.type || '',
            level: card.dataset.level || '',
            location: card.dataset.location || '',
            title: card.querySelector('.job-card__title')?.textContent?.toLowerCase() || '',
            description: card.querySelector('.job-card__description')?.textContent?.toLowerCase() || ''
        });
    });

    // Filter function
    const filterJobs = () => {
        const searchTerm = jobSearch ? jobSearch.value.toLowerCase().trim() : '';
        const department = filterSelects[0] ? filterSelects[0].value : '';
        const type = filterSelects[1] ? filterSelects[1].value : '';
        const level = filterSelects[2] ? filterSelects[2].value : '';
        const location = filterSelects[3] ? filterSelects[3].value : '';

        let visibleCount = 0;

        jobsData.forEach((job) => {
            const matchesSearch = !searchTerm ||
                job.title.includes(searchTerm) ||
                job.description.includes(searchTerm);

            const matchesDepartment = !department || job.department === department;
            const matchesType = !type || job.type === type;
            const matchesLevel = !level || job.level === level;
            const matchesLocation = !location || job.location === location;

            const isVisible = matchesSearch && matchesDepartment && matchesType &&
                matchesLevel && matchesLocation;

            job.element.style.display = isVisible ? '' : 'none';
            if (isVisible) visibleCount++;
        });

        if (jobsCount) {
            jobsCount.textContent = visibleCount;
        }
    };

    // Event listeners for filters
    if (jobSearch) {
        jobSearch.addEventListener('input', filterJobs);
    }

    filterSelects.forEach((select) => {
        select.addEventListener('change', filterJobs);
    });

    // Clear filters
    if (filterClearBtn) {
        filterClearBtn.addEventListener('click', () => {
            if (jobSearch) jobSearch.value = '';
            filterSelects.forEach((select) => {
                select.value = '';
            });
            filterJobs();
        });
    }

    // Filter button - triggers filter (already handled by change events, but useful for UX)
    if (filterSearchBtn) {
        filterSearchBtn.addEventListener('click', (e) => {
            e.preventDefault();
            filterJobs();
        });
    }

    // Initial filter
    filterJobs();

    // ============================================================
    // SCROLL-TRIGGERED ANIMATIONS FOR JOB CARDS
    // ============================================================
    const opBadge = document.querySelector('.open-positions__badge');
    const opTitle = document.querySelector('.open-positions__title');
    const opSubtitle = document.querySelector('.open-positions__subtitle');
    const filtersBar = document.querySelector('.open-positions__filters');
    const countEl = document.querySelector('.open-positions__count');
    const loadMoreBtn = document.querySelector('.btn-load-more');
    const banner = document.querySelector('.open-positions__banner');

    // Set initial state for header elements
    const headerElements = [opBadge, opTitle, opSubtitle];
    headerElements.forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for filters and count
    [filtersBar, countEl].forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(15px)';
            el.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Set initial state for job cards
    jobCards.forEach((card, index) => {
        card.style.opacity = '0';
        card.style.transform = 'translateY(25px)';
        card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms`;
    });

    // Set initial state for load more and banner
    [loadMoreBtn, banner].forEach((el) => {
        if (el) {
            el.style.opacity = '0';
            el.style.transform = 'translateY(20px)';
            el.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }
    });

    // Create observer
    const opObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                // Animate header elements
                headerElements.forEach((el) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 100);
                    }
                });

                // Animate filters and count
                [filtersBar, countEl].forEach((el, index) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 200 + (index * 60));
                    }
                });

                // Animate job cards with staggered delay
                jobCards.forEach((card, index) => {
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    }, 300 + (index * 40));
                });

                // Animate load more and banner
                [loadMoreBtn, banner].forEach((el, index) => {
                    if (el) {
                        setTimeout(() => {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }, 400 + (index * 80));
                    }
                });

                opObserver.disconnect();
            }
        });
    }, {
        threshold: 0.10,
        rootMargin: '0px 0px -50px 0px'
    });

    const opSection = document.getElementById('open-positions');
    if (opSection) {
        opObserver.observe(opSection);
    }

    console.log('💼 Open Positions initialized with', jobCards.length, 'jobs.');
};

