  (function () {
    'use strict';

    // --- Create Floating Particles ---
    const particlesContainer = document.getElementById('bgParticles');
    if (particlesContainer) {
      const particleCount = 35;
      for (let i = 0; i < particleCount; i++) {
        const particle = document.createElement('div');
        const isGreen = Math.random() > 0.5;
        const size = Math.random() * 5 + 2;
        const left = Math.random() * 100;
        const duration = Math.random() * 20 + 14;
        const delay = Math.random() * 18;

        particle.classList.add('particle');
        particle.classList.add(isGreen ? 'particle--green' : 'particle--purple');
        particle.style.width = size + 'px';
        particle.style.height = size + 'px';
        particle.style.left = left + '%';
        particle.style.bottom = -(size + Math.random() * 20) + 'px';
        particle.style.animationDuration = duration + 's';
        particle.style.animationDelay = delay + 's';

        particlesContainer.appendChild(particle);
      }
    }

    // --- Counter Animation for Trust Numbers ---
    const trustNumbers = document.querySelectorAll('.trust-number[data-target]');
    let countersAnimated = false;

    function animateCounter(el) {
      const target = parseInt(el.getAttribute('data-target'), 10);
      const suffix = el.getAttribute('data-suffix') || '';
      const duration = 1800;
      const startTime = performance.now();
      const startVal = 0;

      function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);
        // Ease-out cubic
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.round(startVal + (target - startVal) * eased);
        el.textContent = current + suffix;

        if (progress < 1) {
          requestAnimationFrame(update);
        } else {
          el.textContent = target + suffix;
        }
      }

      requestAnimationFrame(update);
    }

    function handleCounters() {
      if (countersAnimated) return;
      const indicatorsSection = document.getElementById('trust-indicators');
      if (!indicatorsSection) return;

      const rect = indicatorsSection.getBoundingClientRect();
      const windowHeight = window.innerHeight;

      if (rect.top < windowHeight - 80 && rect.bottom > 0) {
        countersAnimated = true;
        trustNumbers.forEach(function (el) {
          animateCounter(el);
        });
      }
    }

    // Check on scroll
    let scrollTicking = false;
    window.addEventListener('scroll', function () {
      if (!scrollTicking) {
        requestAnimationFrame(function () {
          handleCounters();
          scrollTicking = false;
        });
        scrollTicking = true;
      }
    }, { passive: true });

    // Check on load
    window.addEventListener('load', function () {
      handleCounters();
    });

    // Also check after a short delay for safety
    setTimeout(handleCounters, 600);
  })();
// <!-- ==================== END JAVASCRIPT ==================== -->

