(function () {
  'use strict';

  // --- Create Floating Particles ---
  const particlesContainer = document.getElementById('filterParticles');
  if (particlesContainer) {
    const particleCount = 22;
    for (let i = 0; i < particleCount; i++) {
      const particle = document.createElement('div');
      const isGreen = Math.random() > 0.5;
      const size = Math.random() * 3.8 + 1.4;
      const left = Math.random() * 100;
      const duration = Math.random() * 20 + 14;
      const delay = Math.random() * 18;

      particle.classList.add('filter-particle');
      particle.classList.add(isGreen ? 'filter-particle--green' : 'filter-particle--purple');
      particle.style.width = size + 'px';
      particle.style.height = size + 'px';
      particle.style.left = left + '%';
      particle.style.bottom = -(size + Math.random() * 20) + 'px';
      particle.style.animationDuration = duration + 's';
      particle.style.animationDelay = delay + 's';

      particlesContainer.appendChild(particle);
    }
  }

  // --- Filtering Logic (Future‑ready for Laravel) ---
  const filterChips = document.querySelectorAll('.filter-chip');
  const projectCards = document.querySelectorAll('.project-card');
  const activeCountEl = document.getElementById('filterActiveCount');

  if (!filterChips.length || !projectCards.length) return;

  // ⚡️ Category mapping – replace with API data later
  const projectCategoryMap = [
    ['web-development', 'enterprise-systems', 'cloud-solutions'],          // Healthcare
    ['ai-solutions', 'business-automation', 'saas-platforms'],            // AI Support
    ['e-commerce', 'web-development'],                                    // E-Commerce
    ['web-development', 'enterprise-systems', 'saas-platforms'],          // School
    ['enterprise-systems', 'web-development', 'business-automation'],     // Construction
    ['business-automation', 'enterprise-systems', 'saas-platforms']       // Business Automation
  ];

  /**
   * Filter projects by category slug.
   * @param {string} category - Category slug or 'all'
   */
  function filterProjects(category) {
    let visibleCount = 0;

    projectCards.forEach((card, index) => {
      const categories = projectCategoryMap[index] || [];
      const isVisible = category === 'all' || categories.includes(category);

      card.style.display = isVisible ? '' : 'none';
      if (isVisible) visibleCount++;
    });

    // Update active count text
    if (activeCountEl) {
      const strong = activeCountEl.querySelector('strong');
      if (strong) strong.textContent = visibleCount;
      else activeCountEl.innerHTML = `Showing <strong>${visibleCount}</strong> projects`;
    }
  }

  /**
   * Set active chip state and trigger filter.
   * @param {HTMLElement} chip - The clicked chip element
   */
  function setActiveChip(chip) {
    filterChips.forEach(c => {
      c.classList.remove('is-active');
      c.setAttribute('aria-pressed', 'false');
    });

    chip.classList.add('is-active');
    chip.setAttribute('aria-pressed', 'true');

    const category = chip.getAttribute('data-filter');
    filterProjects(category);
  }

  // Bind click events
  filterChips.forEach(chip => {
    chip.addEventListener('click', function () {
      setActiveChip(this);
    });
  });

  // Initial filter (show all)
  filterProjects('all');
})();
/* ==================================================
END: Project Categories Filter JavaScript
================================================== */

