(function () {
  'use strict';

  // --- Create Floating Particles ---
  const particlesContainer = document.getElementById('storiesParticles');
  if (particlesContainer) {
    const particleCount = 22;
    for (let i = 0; i < particleCount; i++) {
      const particle = document.createElement('div');
      const isGreen = Math.random() > 0.5;
      const size = Math.random() * 4 + 1.5;
      const left = Math.random() * 100;
      const duration = Math.random() * 22 + 14;
      const delay = Math.random() * 18;

      particle.classList.add('stories-particle');
      particle.classList.add(isGreen ? 'stories-particle--green' : 'stories-particle--purple');
      particle.style.width = size + 'px';
      particle.style.height = size + 'px';
      particle.style.left = left + '%';
      particle.style.bottom = -(size + Math.random() * 20) + 'px';
      particle.style.animationDuration = duration + 's';
      particle.style.animationDelay = delay + 's';

      particlesContainer.appendChild(particle);
    }
  }

  // --- Carousel Functionality ---
  const track = document.getElementById('carouselTrack');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const dotsContainer = document.getElementById('carouselDots');

  if (!track || !prevBtn || !nextBtn || !dotsContainer) return;

  const cards = track.querySelectorAll('.story-card');
  if (cards.length === 0) return;

  let currentIndex = 0;
  let visibleCards = 3; // default desktop
  let totalPages = 1;

  function getVisibleCards() {
    const width = window.innerWidth;
    if (width <= 767) return 1;
    if (width <= 1199) return 2;
    return 3;
  }

  function getCardWidth() {
    const firstCard = cards[0];
    return firstCard.offsetWidth + parseFloat(getComputedStyle(track).gap || 24);
  }

  function updateCarousel() {
    visibleCards = getVisibleCards();
    totalPages = Math.ceil(cards.length / visibleCards);
    const cardWidth = getCardWidth();
    const maxIndex = Math.max(0, cards.length - visibleCards);

    // Clamp currentIndex
    if (currentIndex > maxIndex) currentIndex = maxIndex;

    const translateX = -currentIndex * cardWidth;
    track.style.transform = `translateX(${translateX}px)`;

    // Update dots
    dotsContainer.innerHTML = '';
    for (let i = 0; i < totalPages; i++) {
      const dot = document.createElement('button');
      dot.classList.add('carousel-dot');
      dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
      dot.addEventListener('click', () => {
        currentIndex = i * visibleCards;
        updateCarousel();
      });
      if (i === Math.floor(currentIndex / visibleCards)) {
        dot.classList.add('active');
      }
      dotsContainer.appendChild(dot);
    }
  }

  function goNext() {
    const maxIndex = Math.max(0, cards.length - visibleCards);
    currentIndex += visibleCards;
    if (currentIndex > maxIndex) currentIndex = 0; // wrap
    updateCarousel();
  }

  function goPrev() {
    currentIndex -= visibleCards;
    if (currentIndex < 0) {
      const maxIndex = Math.max(0, cards.length - visibleCards);
      currentIndex = maxIndex - (maxIndex % visibleCards); // go to last full page
    }
    updateCarousel();
  }

  nextBtn.addEventListener('click', goNext);
  prevBtn.addEventListener('click', goPrev);

  // Touch swipe support
  let touchStartX = 0;
  let touchEndX = 0;
  const viewport = document.getElementById('carouselViewport');
  viewport.addEventListener('touchstart', (e) => {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });

  viewport.addEventListener('touchend', (e) => {
    touchEndX = e.changedTouches[0].screenX;
    const swipeDistance = touchStartX - touchEndX;
    if (Math.abs(swipeDistance) > 50) {
      if (swipeDistance > 0) goNext();
      else goPrev();
    }
  });

  // Recalculate on resize
  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(updateCarousel, 150);
  });

  // Initialize
  updateCarousel();
})();
/* ==================================================
END: Client Success Stories JavaScript
================================================== */

