(function () {
  'use strict';

  // --- Create Floating Particles ---
  const particlesContainer = document.getElementById('faqParticles');
  if (particlesContainer) {
    const particleCount = 20;
    for (let i = 0; i < particleCount; i++) {
      const particle = document.createElement('div');
      const isGreen = Math.random() > 0.5;
      const size = Math.random() * 4 + 1.5;
      const left = Math.random() * 100;
      const duration = Math.random() * 22 + 14;
      const delay = Math.random() * 18;

      particle.classList.add('faq-particle');
      particle.classList.add(isGreen ? 'faq-particle--green' : 'faq-particle--purple');
      particle.style.width = size + 'px';
      particle.style.height = size + 'px';
      particle.style.left = left + '%';
      particle.style.bottom = -(size + Math.random() * 20) + 'px';
      particle.style.animationDuration = duration + 's';
      particle.style.animationDelay = delay + 's';

      particlesContainer.appendChild(particle);
    }
  }

  // --- Accordion Logic ---
  const accordionItems = document.querySelectorAll('.faq-item');

  function closeAllExcept(exceptItem) {
    accordionItems.forEach(item => {
      if (item !== exceptItem && item.classList.contains('active')) {
        const btn = item.querySelector('.faq-question');
        const answer = item.querySelector('.faq-answer-wrapper');
        item.classList.remove('active');
        btn.setAttribute('aria-expanded', 'false');
        answer.setAttribute('hidden', '');
        answer.style.maxHeight = '0';
      }
    });
  }

  function toggleItem(item) {
    const isActive = item.classList.contains('active');
    const btn = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer-wrapper');

    closeAllExcept(item);

    if (isActive) {
      // close current
      item.classList.remove('active');
      btn.setAttribute('aria-expanded', 'false');
      answer.setAttribute('hidden', '');
      answer.style.maxHeight = '0';
    } else {
      // open
      item.classList.add('active');
      btn.setAttribute('aria-expanded', 'true');
      answer.removeAttribute('hidden');
      // Set max-height based on content height
      const answerContent = answer.querySelector('.faq-answer');
      answer.style.maxHeight = answerContent.scrollHeight + 40 + 'px'; // padding
    }
  }

  accordionItems.forEach(item => {
    const btn = item.querySelector('.faq-question');
    btn.addEventListener('click', () => toggleItem(item));

    // Allow keyboard activation
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        toggleItem(item);
      }
    });
  });

})();
