    // ============================================================
    // 44. INTERACTIVE PORTFOLIO GALLERY — LOAD MORE
    // ============================================================
    const initPortfolioGallery = () => {
        const grid = document.getElementById('gallery-grid');
        const loadMoreBtn = document.getElementById('load-more-btn');
        const loadingSpinner = document.getElementById('loading-spinner');
        const loadMoreEnd = document.getElementById('load-more-end');
        const emptyState = document.getElementById('gallery-empty');
        const resetBtn = document.getElementById('empty-reset-btn');

        // Get all gallery cards
        const allCards = grid ? grid.querySelectorAll('.gallery-card') : [];
        const visibleCards = grid ? grid.querySelectorAll('.gallery-card:not(.gallery-card--hidden)') : [];
        const hiddenCards = grid ? grid.querySelectorAll('.gallery-card.gallery-card--hidden') : [];

        let cardsPerLoad = 3;
        let currentlyVisible = visibleCards.length;
        let totalCards = allCards.length;

        // Update results count if needed
        const updateResultsCount = () => {
            // This could update a results counter if we add one
        };

        // Function to load more cards
        const loadMoreCards = () => {
            // Get next batch of hidden cards
            const hiddenArray = Array.from(hiddenCards).filter(card => card.style.display === 'none');

            if (hiddenArray.length === 0) {
                // No more cards to load
                loadMoreBtn.style.display = 'none';
                loadMoreEnd.classList.add('visible');
                return;
            }

            // Show loading state
            loadMoreBtn.classList.add('loading');
            loadingSpinner.classList.add('visible');

            // Simulate AJAX delay (future Laravel integration)
            setTimeout(() => {
                const batch = hiddenArray.slice(0, cardsPerLoad);

                batch.forEach((card, index) => {
                    // Show the card with animation
                    card.style.display = '';
                    card.classList.add('fade-in');

                    // Remove hidden class after animation
                    setTimeout(() => {
                        card.classList.remove('gallery-card--hidden');
                    }, 500);
                });

                // Update counts
                currentlyVisible += batch.length;

                // Hide loading state
                loadMoreBtn.classList.remove('loading');
                loadingSpinner.classList.remove('visible');

                // Check if all cards are now visible
                const remainingHidden = document.querySelectorAll('.gallery-card.gallery-card--hidden');
                if (remainingHidden.length === 0) {
                    loadMoreBtn.style.display = 'none';
                    loadMoreEnd.classList.add('visible');
                }

                updateResultsCount();

                console.log(`📂 Loaded ${batch.length} more projects. Total: ${currentlyVisible}`);
            }, 800); // Simulated network delay
        };

        // Event listener for Load More button
        if (loadMoreBtn) {
            loadMoreBtn.addEventListener('click', loadMoreCards);
        }

        // Reset button for empty state
        if (resetBtn) {
            resetBtn.addEventListener('click', function() {
                // Show all cards
                document.querySelectorAll('.gallery-card').forEach((card) => {
                    card.style.display = '';
                    card.classList.remove('gallery-card--hidden');
                });
                emptyState.classList.remove('visible');
                emptyState.style.display = 'none';

                // Update button state
                loadMoreBtn.style.display = 'inline-flex';
                loadMoreEnd.classList.remove('visible');

                // Reset to initial state
                currentlyVisible = document.querySelectorAll('.gallery-card:not(.gallery-card--hidden)').length;
                updateResultsCount();
            });
        }

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const pgBadge = document.querySelector('.portfolio-gallery__badge');
        const pgTitle = document.querySelector('.portfolio-gallery__title');
        const pgSubtitle = document.querySelector('.portfolio-gallery__subtitle');
        const pgGrid = document.querySelector('.portfolio-gallery__grid');

        // Set initial state for header elements
        const headerElements = [pgBadge, pgTitle, pgSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for gallery cards
        const initialVisibleCards = document.querySelectorAll('.gallery-card:not(.gallery-card--hidden)');
        initialVisibleCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(25px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms`;
        });

        // Set initial state for load more
        if (loadMoreBtn) {
            loadMoreBtn.style.opacity = '0';
            loadMoreBtn.style.transform = 'translateY(15px)';
            loadMoreBtn.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Create observer
        const pgObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate gallery cards with staggered delay
                    initialVisibleCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 200 + (index * 40));
                    });

                    // Animate load more
                    if (loadMoreBtn) {
                        setTimeout(() => {
                            loadMoreBtn.style.opacity = '1';
                            loadMoreBtn.style.transform = 'translateY(0)';
                        }, 300 + (initialVisibleCards.length * 40));
                    }

                    pgObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const pgSection = document.getElementById('portfolio-gallery');
        if (pgSection) {
            pgObserver.observe(pgSection);
        }

        console.log('📂 Interactive Portfolio Gallery initialized with', totalCards, 'projects.');
    };

    // Initialize Portfolio Gallery
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initPortfolioGallery);
    } else {
        initPortfolioGallery();
    }

