    // ============================================================
    // 46. BUSINESS IMPACT — COUNTER & SCROLL ANIMATIONS
    // ============================================================
    const initBusinessImpact = () => {
        const metricNumbers = document.querySelectorAll('.metric-number');
        const impactCards = document.querySelectorAll('.impact-card');
        const biBadge = document.querySelector('.business-impact__badge');
        const biTitle = document.querySelector('.business-impact__title');
        const biSubtitle = document.querySelector('.business-impact__subtitle');
        const biMetrics = document.querySelector('.business-impact__metrics');
        const biStrip = document.querySelector('.business-impact__strip');

        // Set initial state for header elements
        const headerElements = [biBadge, biTitle, biSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for impact cards
        impactCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(30px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms`;
        });

        // Set initial state for metrics and strip
        [biMetrics, biStrip].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 100)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 100)}ms`;
            }
        });

        let statsAnimated = false;

        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const currentValue = Math.floor(eased * target);
                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    element.textContent = target;
                }
            };

            requestAnimationFrame(updateCount);
        };

        // Create observer
        const biObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate impact cards with staggered delay
                    impactCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 200 + (index * 60));
                    });

                    // Animate metrics and strip
                    [biMetrics, biStrip].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 350 + (index * 100));
                        }
                    });

                    // Animate counters
                    if (!statsAnimated) {
                        statsAnimated = true;
                        metricNumbers.forEach((statEl) => {
                            const target = parseFloat(statEl.getAttribute('data-count'));
                            if (isNaN(target)) return;
                            statEl.textContent = '0';
                            animateCount(statEl, target);
                        });
                    }

                    biObserver.disconnect();
                }
            });
        }, {
            threshold: 0.12,
            rootMargin: '0px 0px -50px 0px'
        });

        const biSection = document.getElementById('business-impact');
        if (biSection) {
            biObserver.observe(biSection);
        }

        console.log('💼 Business Impact section initialized.');
    };

    // Initialize Business Impact
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBusinessImpact);
    } else {
        initBusinessImpact();
    }

