    // ============================================================
    // 52. ADVANCED SEARCH & SMART FILTERS
    // ============================================================
    const initBlogSearch = () => {
        const searchInput = document.getElementById('blog-search-input');
        const searchClear = document.getElementById('search-clear');
        const searchLoading = document.getElementById('search-loading');
        const searchSubmit = document.querySelector('.search-bar-submit');
        const filterToggle = document.getElementById('filter-toggle');
        const filterPanel = document.getElementById('filter-panel');
        const filterApply = document.getElementById('filter-apply');
        const filterReset = document.getElementById('filter-reset');
        const chipsContainer = document.getElementById('chips-container');
        const chipsClearAll = document.getElementById('chips-clear-all');
        const filterChips = document.getElementById('filter-chips');
        const filterCount = document.getElementById('filter-count');
        const summaryQuery = document.getElementById('summary-query');
        const summaryCount = document.getElementById('summary-count');
        const searchResults = document.getElementById('search-results');
        const emptyState = document.getElementById('search-empty');
        const emptyBrowseBtn = document.getElementById('empty-browse-btn');
        const loadMoreBtn = document.getElementById('load-more-results');
        const suggestionChips = document.querySelectorAll('.suggestion-chip');

        // Track active filters
        let activeFilters = {};
        let currentSearchTerm = '';
        let currentResultsCount = 4;

        // ----- Search Input Handlers -----
        if (searchInput) {
            searchInput.addEventListener('input', function() {
                const value = this.value.trim();
                currentSearchTerm = value;

                // Show/hide clear button
                if (searchClear) {
                    if (value.length > 0) {
                        searchClear.classList.add('visible');
                    } else {
                        searchClear.classList.remove('visible');
                    }
                }

                // Update summary query
                if (summaryQuery) {
                    if (value) {
                        summaryQuery.innerHTML = `Results for: "<strong>${value}</strong>"`;
                    } else {
                        summaryQuery.innerHTML = '';
                    }
                }

                // Show loading indicator (simulated)
                if (searchLoading && value.length > 2) {
                    searchLoading.classList.add('visible');
                    setTimeout(() => {
                        searchLoading.classList.remove('visible');
                    }, 800);
                }
            });

            // Clear button
            if (searchClear) {
                searchClear.addEventListener('click', function() {
                    if (searchInput) {
                        searchInput.value = '';
                        searchInput.focus();
                        this.classList.remove('visible');
                        currentSearchTerm = '';
                        if (summaryQuery) {
                            summaryQuery.innerHTML = '';
                        }
                        // Trigger search update
                        performSearch();
                    }
                });
            }

            // Enter key submit
            searchInput.addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    performSearch();
                }
            });
        }

        // ----- Search Submit -----
        if (searchSubmit) {
            searchSubmit.addEventListener('click', function(e) {
                e.preventDefault();
                performSearch();
            });
        }

        // ----- Quick Suggestions -----
        suggestionChips.forEach((chip) => {
            chip.addEventListener('click', function() {
                const term = this.dataset.term;
                if (searchInput) {
                    searchInput.value = term;
                    currentSearchTerm = term;
                    if (searchClear) {
                        searchClear.classList.add('visible');
                    }
                    if (summaryQuery) {
                        summaryQuery.innerHTML = `Results for: "<strong>${term}</strong>"`;
                    }
                    performSearch();
                }
            });
        });

        // ----- Voice Search (UI placeholder) -----
        const voiceBtn = document.querySelector('.search-bar-voice');
        if (voiceBtn) {
            voiceBtn.addEventListener('click', function() {
                if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
                    // Placeholder for future voice search implementation
                    console.log('🎤 Voice search activated');
                    this.style.color = 'var(--color-lime)';
                    setTimeout(() => {
                        this.style.color = '';
                    }, 2000);
                } else {
                    alert('Voice search is not supported in your browser.');
                }
            });
        }

        // ----- Filter Toggle (Mobile) -----
        if (filterToggle && filterPanel) {
            filterToggle.addEventListener('click', function() {
                const isHidden = filterPanel.classList.contains('hidden');
                if (isHidden) {
                    filterPanel.classList.remove('hidden');
                    this.classList.add('active');
                    this.setAttribute('aria-expanded', 'true');
                    this.innerHTML = `
                        <i class="fas fa-sliders-h" aria-hidden="true"></i>
                        Close Filters
                        <span class="filter-count" id="filter-count">${Object.keys(activeFilters).length}</span>
                    `;
                } else {
                    filterPanel.classList.add('hidden');
                    this.classList.remove('active');
                    this.setAttribute('aria-expanded', 'false');
                    this.innerHTML = `
                        <i class="fas fa-sliders-h" aria-hidden="true"></i>
                        Filters
                        <span class="filter-count" id="filter-count">${Object.keys(activeFilters).length}</span>
                    `;
                }
            });
        }

        // ----- Apply Filters -----
        if (filterApply) {
            filterApply.addEventListener('click', function() {
                applyFilters();
            });
        }

        // ----- Reset Filters -----
        if (filterReset) {
            filterReset.addEventListener('click', function() {
                resetFilters();
            });
        }

        // ----- Clear All Chips -----
        if (chipsClearAll) {
            chipsClearAll.addEventListener('click', function() {
                resetFilters();
            });
        }

        // ----- Empty Browse Button -----
        if (emptyBrowseBtn) {
            emptyBrowseBtn.addEventListener('click', function() {
                resetFilters();
                if (searchInput) {
                    searchInput.value = '';
                    currentSearchTerm = '';
                    if (searchClear) {
                        searchClear.classList.remove('visible');
                    }
                    if (summaryQuery) {
                        summaryQuery.innerHTML = '';
                    }
                }
                performSearch();
            });
        }

        // ----- Load More -----
        if (loadMoreBtn) {
            loadMoreBtn.addEventListener('click', function() {
                // Simulate loading more results
                this.innerHTML = 'Loading... <i class="fas fa-spinner fa-spin"></i>';
                this.disabled = true;

                setTimeout(() => {
                    currentResultsCount += 2;
                    // Show more result cards (simulated)
                    const cards = document.querySelectorAll('.result-card');
                    cards.forEach((card, index) => {
                        if (index < currentResultsCount) {
                            card.style.display = '';
                        } else {
                            card.style.display = 'none';
                        }
                    });

                    if (summaryCount) {
                        summaryCount.textContent = currentResultsCount;
                    }

                    this.innerHTML = 'Load More Results <i class="fas fa-arrow-down"></i>';
                    this.disabled = false;

                    if (currentResultsCount >= cards.length) {
                        this.style.display = 'none';
                    }
                }, 800);
            });
        }

        // ----- Core Functions -----
        const performSearch = () => {
            const searchTerm = searchInput ? searchInput.value.trim() : '';
            const filterCount = Object.keys(activeFilters).length;

            if (summaryCount) {
                // Simulate result count
                const baseCount = 48;
                const adjustedCount = Math.max(4, baseCount - (filterCount * 2) - (searchTerm.length > 0 ? 4 : 0));
                summaryCount.textContent = adjustedCount;
            }

            // Update filter chips
            updateFilterChips();

            // Show/hide empty state
            const hasResults = true; // Placeholder
            if (searchTerm && filterCount > 3) {
                // Simulate no results
                if (searchTerm === 'nonexistent') {
                    showEmptyState(true);
                } else {
                    showEmptyState(false);
                }
            } else {
                showEmptyState(false);
            }

            console.log('🔍 Search performed:', { searchTerm, filters: activeFilters });
        };

        const applyFilters = () => {
            const category = document.getElementById('filter-category')?.value || '';
            const technology = document.getElementById('filter-technology')?.value || '';
            const difficulty = document.getElementById('filter-difficulty')?.value || '';
            const reading = document.getElementById('filter-reading')?.value || '';
            const type = document.getElementById('filter-type')?.value || '';
            const sort = document.getElementById('filter-sort')?.value || 'newest';
            const date = document.getElementById('filter-date')?.value || '';

            // Build active filters object
            activeFilters = {};
            if (category) activeFilters.category = category;
            if (technology) activeFilters.technology = technology;
            if (difficulty) activeFilters.difficulty = difficulty;
            if (reading) activeFilters.reading = reading;
            if (type) activeFilters.type = type;
            if (date) activeFilters.date = date;

            // Update sort display
            const sortLabels = {
                'newest': 'Newest',
                'oldest': 'Oldest',
                'popular': 'Most Popular',
                'most-viewed': 'Most Viewed',
                'trending': 'Trending',
                'editors-pick': 'Editor\'s Pick',
                'a-z': 'A–Z'
            };
            const sortLabel = document.querySelector('.summary-right strong');
            if (sortLabel) {
                sortLabel.textContent = sortLabels[sort] || 'Newest';
            }

            // Update filter count
            const filterCountEl = document.getElementById('filter-count');
            if (filterCountEl) {
                const count = Object.keys(activeFilters).length;
                filterCountEl.textContent = count;
            }

            // Update filter toggle on mobile
            if (filterToggle) {
                const count = Object.keys(activeFilters).length;
                filterToggle.innerHTML = `
                    <i class="fas fa-sliders-h" aria-hidden="true"></i>
                    Filters
                    <span class="filter-count" id="filter-count">${count}</span>
                `;
            }

            // Close filter panel on mobile
            if (window.innerWidth <= 576 && filterPanel && filterToggle) {
                filterPanel.classList.add('hidden');
                filterToggle.classList.remove('active');
                filterToggle.setAttribute('aria-expanded', 'false');
                const count = Object.keys(activeFilters).length;
                filterToggle.innerHTML = `
                    <i class="fas fa-sliders-h" aria-hidden="true"></i>
                    Filters
                    <span class="filter-count" id="filter-count">${count}</span>
                `;
            }

            performSearch();
        };

        const resetFilters = () => {
            // Reset all select elements
            const selects = document.querySelectorAll('.filter-select');
            selects.forEach((select) => {
                select.value = '';
            });

            // Reset sort to default
            const sortSelect = document.getElementById('filter-sort');
            if (sortSelect) sortSelect.value = 'newest';

            // Clear active filters
            activeFilters = {};

            // Update filter count
            const filterCountEl = document.getElementById('filter-count');
            if (filterCountEl) {
                filterCountEl.textContent = '0';
            }

            // Update filter toggle on mobile
            if (filterToggle) {
                filterToggle.innerHTML = `
                    <i class="fas fa-sliders-h" aria-hidden="true"></i>
                    Filters
                    <span class="filter-count" id="filter-count">0</span>
                `;
            }

            // Reset sort display
            const sortLabel = document.querySelector('.summary-right strong');
            if (sortLabel) {
                sortLabel.textContent = 'Newest';
            }

            updateFilterChips();
            performSearch();
        };

        const updateFilterChips = () => {
            if (!chipsContainer || !filterChips) return;

            const keys = Object.keys(activeFilters);
            if (keys.length === 0) {
                filterChips.style.display = 'none';
                return;
            }

            filterChips.style.display = 'flex';

            // Build chips
            const chipLabels = {
                'category': 'Category',
                'technology': 'Technology',
                'difficulty': 'Difficulty',
                'reading': 'Reading Time',
                'type': 'Content Type',
                'date': 'Date'
            };

            const chipValues = {
                'category': document.getElementById('filter-category')?.value || '',
                'technology': document.getElementById('filter-technology')?.value || '',
                'difficulty': document.getElementById('filter-difficulty')?.value || '',
                'reading': document.getElementById('filter-reading')?.value || '',
                'type': document.getElementById('filter-type')?.value || '',
                'date': document.getElementById('filter-date')?.value || ''
            };

            let chipsHTML = '';
            keys.forEach((key) => {
                const label = chipLabels[key] || key;
                const value = chipValues[key] || '';
                if (value) {
                    chipsHTML += `
                        <span class="filter-chip" data-filter-key="${key}">
                            ${label}: ${value}
                            <button class="chip-remove" data-filter-key="${key}" aria-label="Remove filter">
                                <i class="fas fa-times" aria-hidden="true"></i>
                            </button>
                        </span>
                    `;
                }
            });

            chipsContainer.innerHTML = chipsHTML;

            // Add remove handlers
            document.querySelectorAll('.chip-remove').forEach((btn) => {
                btn.addEventListener('click', function() {
                    const key = this.dataset.filterKey;
                    if (key && activeFilters[key]) {
                        delete activeFilters[key];
                        // Reset the corresponding select
                        const selectMap = {
                            'category': 'filter-category',
                            'technology': 'filter-technology',
                            'difficulty': 'filter-difficulty',
                            'reading': 'filter-reading',
                            'type': 'filter-type',
                            'date': 'filter-date'
                        };
                        const selectId = selectMap[key];
                        if (selectId) {
                            const select = document.getElementById(selectId);
                            if (select) select.value = '';
                        }
                        // Update filter count
                        const filterCountEl = document.getElementById('filter-count');
                        if (filterCountEl) {
                            filterCountEl.textContent = Object.keys(activeFilters).length;
                        }
                        // Update toggle
                        if (filterToggle) {
                            const count = Object.keys(activeFilters).length;
                            filterToggle.innerHTML = `
                                <i class="fas fa-sliders-h" aria-hidden="true"></i>
                                Filters
                                <span class="filter-count" id="filter-count">${count}</span>
                            `;
                        }
                        updateFilterChips();
                        performSearch();
                    }
                });
            });
        };

        const showEmptyState = (show) => {
            if (emptyState && searchResults) {
                if (show) {
                    emptyState.style.display = 'block';
                    emptyState.classList.add('visible');
                    searchResults.style.display = 'none';
                } else {
                    emptyState.style.display = 'none';
                    emptyState.classList.remove('visible');
                    searchResults.style.display = 'grid';
                }
            }
        };

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const bsBadge = document.querySelector('.blog-search__badge');
        const bsTitle = document.querySelector('.blog-search__title');
        const bsSubtitle = document.querySelector('.blog-search__subtitle');
        const bsSearchBar = document.querySelector('.blog-search__bar');
        const bsSuggestions = document.querySelector('.blog-search__suggestions');
        const bsControls = document.querySelector('.blog-search__controls');
        const bsSummary = document.querySelector('.blog-search__summary');
        const bsResults = document.querySelector('.blog-search__results');
        const bsLoadMore = document.querySelector('.blog-search__load-more');

        // Set initial state for header elements
        const headerElements = [bsBadge, bsTitle, bsSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for search bar, suggestions, controls
        [bsSearchBar, bsSuggestions, bsControls, bsSummary, bsResults, bsLoadMore].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for result cards
        const resultCards = document.querySelectorAll('.result-card');
        resultCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(25px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 40)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 40)}ms`;
        });

        // Create observer
        const bsObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate search components with staggered delay
                    [bsSearchBar, bsSuggestions, bsControls, bsSummary, bsResults, bsLoadMore].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    // Animate result cards with staggered delay
                    resultCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 40));
                    });

                    bsObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const bsSection = document.getElementById('blog-search');
        if (bsSection) {
            bsObserver.observe(bsSection);
        }

        console.log('🔍 Advanced Search & Smart Filters initialized.');
    };

    // Initialize Blog Search
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBlogSearch);
    } else {
        initBlogSearch();
    }

/* ==================================================
END: Advanced Search & Smart Filters JavaScript
================================================== */

