    // ============================================================
    // 53. LATEST ARTICLES GRID — LOAD MORE & INTERACTIONS
    // ============================================================
    const initBlogFeed = () => {
        const feedGrid = document.getElementById('feed-grid');
        const loadMoreBtn = document.getElementById('load-more-feed-btn');
        const loadingSpinner = document.getElementById('feed-loading');
        const pagination = document.getElementById('feed-pagination');
        const emptyState = document.getElementById('feed-empty');
        const emptyBrowseBtn = document.getElementById('empty-feed-browse-btn');
        const bookmarkBtns = document.querySelectorAll('.overlay-bookmark');
        const shareBtns = document.querySelectorAll('.overlay-share');

        // Initial visible cards (first 6)
        const allCards = feedGrid ? feedGrid.querySelectorAll('.feed-card') : [];
        let visibleCount = 6;
        let isLoading = false;

        // Initially hide cards beyond the first 6
        allCards.forEach((card, index) => {
            if (index >= visibleCount) {
                card.style.display = 'none';
            }
        });

        // ----- Load More Functionality -----
        if (loadMoreBtn && loadingSpinner) {
            loadMoreBtn.addEventListener('click', function() {
                if (isLoading) return;
                isLoading = true;

                // Show loading spinner
                this.style.display = 'none';
                loadingSpinner.classList.add('visible');

                // Simulate AJAX delay
                setTimeout(() => {
                    const hiddenCards = [];
                    allCards.forEach((card) => {
                        if (card.style.display === 'none' || card.style.display === '') {
                            hiddenCards.push(card);
                        }
                    });

                    // Show next 3 cards
                    const batch = hiddenCards.slice(0, 3);
                    batch.forEach((card, index) => {
                        card.style.display = '';
                        card.style.opacity = '0';
                        card.style.transform = 'translateY(20px)';
                        card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 80}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 80}ms`;

                        // Trigger animation
                        requestAnimationFrame(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        });
                    });

                    visibleCount += batch.length;

                    // Hide loading spinner
                    loadingSpinner.classList.remove('visible');
                    this.style.display = 'inline-flex';

                    // If no more hidden cards, hide load more button
                    const remainingHidden = document.querySelectorAll('.feed-card[style*="display: none"]');
                    if (remainingHidden.length === 0) {
                        this.style.display = 'none';
                        // Show pagination instead
                        if (pagination) {
                            pagination.style.display = 'flex';
                        }
                    }

                    isLoading = false;
                }, 800);
            });
        }

        // ----- Pagination (placeholder UI) -----
        if (pagination) {
            const pageBtns = pagination.querySelectorAll('.page-btn:not(.page-btn--prev):not(.page-btn--next)');

            pageBtns.forEach((btn) => {
                btn.addEventListener('click', function() {
                    // Remove active from all
                    pageBtns.forEach((b) => b.classList.remove('page-btn--active'));
                    this.classList.add('page-btn--active');

                    // Smooth scroll to grid
                    if (feedGrid) {
                        feedGrid.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                });
            });

            // Previous/Next buttons
            const prevBtn = pagination.querySelector('.page-btn--prev');
            const nextBtn = pagination.querySelector('.page-btn--next');

            if (prevBtn) {
                prevBtn.addEventListener('click', function() {
                    const active = pagination.querySelector('.page-btn--active');
                    const prev = active ? active.previousElementSibling : null;
                    if (prev && !prev.classList.contains('page-ellipsis') && !prev.classList.contains('page-btn--prev')) {
                        active.classList.remove('page-btn--active');
                        prev.classList.add('page-btn--active');
                        if (feedGrid) {
                            feedGrid.scrollIntoView({ behavior: 'smooth', block: 'start' });
                        }
                    }
                });
            }

            if (nextBtn) {
                nextBtn.addEventListener('click', function() {
                    const active = pagination.querySelector('.page-btn--active');
                    const next = active ? active.nextElementSibling : null;
                    if (next && !next.classList.contains('page-ellipsis') && !next.classList.contains('page-btn--next')) {
                        active.classList.remove('page-btn--active');
                        next.classList.add('page-btn--active');
                        if (feedGrid) {
                            feedGrid.scrollIntoView({ behavior: 'smooth', block: 'start' });
                        }
                    }
                });
            }
        }

        // ----- Bookmark Toggle -----
        bookmarkBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                const icon = this.querySelector('i');
                if (icon) {
                    if (icon.classList.contains('far')) {
                        icon.classList.remove('far');
                        icon.classList.add('fas');
                        this.classList.add('active');
                    } else {
                        icon.classList.remove('fas');
                        icon.classList.add('far');
                        this.classList.remove('active');
                    }
                }
            });
        });

        // ----- Share Button -----
        shareBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                // Find the article title
                const card = this.closest('.feed-card');
                const title = card?.querySelector('.feed-card__title')?.textContent || 'XoHub Solutions Article';

                if (navigator.share) {
                    navigator.share({
                        title: title,
                        url: window.location.href
                    }).catch(() => {});
                } else {
                    // Fallback: copy link
                    const url = window.location.href;
                    navigator.clipboard?.writeText(url).then(() => {
                        const originalHTML = this.innerHTML;
                        this.innerHTML = '<i class="fas fa-check" aria-hidden="true"></i>';
                        this.style.background = 'var(--color-lime)';
                        this.style.color = 'var(--color-charcoal)';
                        this.style.borderColor = 'var(--color-lime)';
                        setTimeout(() => {
                            this.innerHTML = originalHTML;
                            this.style.background = '';
                            this.style.color = '';
                            this.style.borderColor = '';
                        }, 2000);
                    }).catch(() => {});
                }
            });
        });

        // ----- Empty Browse Button -----
        if (emptyBrowseBtn) {
            emptyBrowseBtn.addEventListener('click', function() {
                // Show all cards (reset)
                allCards.forEach((card) => {
                    card.style.display = '';
                    card.style.opacity = '1';
                    card.style.transform = 'translateY(0)';
                });
                visibleCount = allCards.length;

                // Hide empty state
                emptyState.classList.remove('visible');
                emptyState.style.display = 'none';

                // Show load more if needed
                if (loadMoreBtn) {
                    loadMoreBtn.style.display = 'none';
                }
                if (pagination) {
                    pagination.style.display = 'flex';
                }

                // Scroll to grid
                if (feedGrid) {
                    feedGrid.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            });
        }

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const bfBadge = document.querySelector('.blog-feed__badge');
        const bfTitle = document.querySelector('.blog-feed__title');
        const bfSubtitle = document.querySelector('.blog-feed__subtitle');

        // Set initial state for header elements
        const headerElements = [bfBadge, bfTitle, bfSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for visible cards
        const initialCards = document.querySelectorAll('.feed-card:not([style*="display: none"])');
        initialCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(25px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms`;
        });

        // Set initial state for load more
        if (loadMoreBtn) {
            loadMoreBtn.style.opacity = '0';
            loadMoreBtn.style.transform = 'translateY(15px)';
            loadMoreBtn.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Set initial state for pagination
        if (pagination) {
            pagination.style.opacity = '0';
            pagination.style.transform = 'translateY(15px)';
            pagination.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Create observer
        const bfObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate visible cards with staggered delay
                    initialCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 200 + (index * 40));
                    });

                    // Animate load more and pagination
                    [loadMoreBtn, pagination].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 300 + (index * 60));
                        }
                    });

                    bfObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const bfSection = document.getElementById('blog-feed');
        if (bfSection) {
            bfObserver.observe(bfSection);
        }

        console.log('📰 Latest Articles Feed initialized with', allCards.length, 'articles.');
    };

    // Initialize Blog Feed
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBlogFeed);
    } else {
        initBlogFeed();
    }

/* ==================================================
END: Latest Articles Grid JavaScript
================================================== */

