    // ============================================================
    // 54. LEARNING COLLECTIONS — SCROLL ANIMATIONS & INTERACTIONS
    // ============================================================
    const initLearningCollections = () => {
        const collectionCards = document.querySelectorAll('.collection-card');
        const featuredPath = document.querySelector('.featured-path');
        const progressFill = document.querySelector('.progress-fill');
        const highlightStats = document.querySelectorAll('.highlight-stat .stat-number');
        const lcBadge = document.querySelector('.learning-collections__badge');
        const lcTitle = document.querySelector('.learning-collections__title');
        const lcSubtitle = document.querySelector('.learning-collections__subtitle');
        const viewAllBtn = document.querySelector('.btn-view-collections');

        // ----- Progress Bar Animation -----
        if (progressFill) {
            // Animate progress bar when featured path comes into view
            const progressObserver = new IntersectionObserver((entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        setTimeout(() => {
                            progressFill.style.width = '35%';
                        }, 500);
                        progressObserver.disconnect();
                    }
                });
            }, { threshold: 0.3 });

            const featuredPathEl = document.querySelector('.featured-path');
            if (featuredPathEl) {
                progressObserver.observe(featuredPathEl);
            }
        }

        // ----- Set initial state for header elements -----
        const headerElements = [lcBadge, lcTitle, lcSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // ----- Set initial state for featured path -----
        if (featuredPath) {
            featuredPath.style.opacity = '0';
            featuredPath.style.transform = 'translateY(30px)';
            featuredPath.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // ----- Set initial state for collection cards -----
        collectionCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(25px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 40}ms`;
        });

        // ----- Set initial state for highlights and view all -----
        const highlights = document.querySelector('.learning-collections__highlights');
        if (highlights) {
            highlights.style.opacity = '0';
            highlights.style.transform = 'translateY(20px)';
            highlights.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        if (viewAllBtn) {
            viewAllBtn.style.opacity = '0';
            viewAllBtn.style.transform = 'translateY(15px)';
            viewAllBtn.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // ----- Counter Animation -----
        let statsAnimated = false;

        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const currentValue = Math.floor(eased * target);
                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    element.textContent = target;
                }
            };

            requestAnimationFrame(updateCount);
        };

        // ----- Create observer -----
        const lcObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate featured path
                    if (featuredPath) {
                        setTimeout(() => {
                            featuredPath.style.opacity = '1';
                            featuredPath.style.transform = 'translateY(0)';
                        }, 200);
                    }

                    // Animate collection cards with staggered delay
                    collectionCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 40));
                    });

                    // Animate highlights
                    if (highlights) {
                        setTimeout(() => {
                            highlights.style.opacity = '1';
                            highlights.style.transform = 'translateY(0)';
                        }, 350);
                    }

                    // Animate view all button
                    if (viewAllBtn) {
                        setTimeout(() => {
                            viewAllBtn.style.opacity = '1';
                            viewAllBtn.style.transform = 'translateY(0)';
                        }, 400);
                    }

                    // Animate stat counters
                    if (!statsAnimated) {
                        statsAnimated = true;
                        highlightStats.forEach((statEl) => {
                            const target = parseInt(statEl.getAttribute('data-count'), 10);
                            if (isNaN(target)) return;
                            statEl.textContent = '0';
                            animateCount(statEl, target);
                        });
                    }

                    lcObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const lcSection = document.getElementById('learning-collections');
        if (lcSection) {
            lcObserver.observe(lcSection);
        }

        console.log('📚 Learning Collections initialized with', collectionCards.length, 'collections.');
    };

    // Initialize Learning Collections
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initLearningCollections);
    } else {
        initLearningCollections();
    }

/* ==================================================
END: Featured Learning Collections JavaScript
================================================== */

