    // ============================================================
    // 55. TRENDING CONTENT — CAROUSEL & INTERACTIONS
    // ============================================================
    const initTrendingContent = () => {
        const track = document.getElementById('carousel-track');
        const prevBtn = document.getElementById('carousel-prev');
        const nextBtn = document.getElementById('carousel-next');
        const indicators = document.querySelectorAll('.indicator-dot');
        const topicItems = document.querySelectorAll('.topic-item');

        let currentIndex = 0;
        let totalSlides = 0;
        let slidesPerView = 3;
        let autoPlayInterval = null;

        // ----- Calculate Slides Per View -----
        const getSlidesPerView = () => {
            if (window.innerWidth <= 576) return 1;
            if (window.innerWidth <= 992) return 2;
            return 3;
        };

        // ----- Update Carousel -----
        const updateCarousel = () => {
            if (!track) return;

            slidesPerView = getSlidesPerView();
            const cards = track.querySelectorAll('.carousel-card');
            totalSlides = cards.length;

            // Update card widths
            const gap = 20;
            const cardWidth = (track.parentElement.offsetWidth - (slidesPerView - 1) * gap) / slidesPerView;

            cards.forEach((card) => {
                card.style.minWidth = `${cardWidth}px`;
            });

            // Clamp current index
            const maxIndex = Math.max(0, totalSlides - slidesPerView);
            if (currentIndex > maxIndex) {
                currentIndex = maxIndex;
            }

            // Update transform
            const offset = currentIndex * (cardWidth + gap);
            track.style.transform = `translateX(-${offset}px)`;

            // Update indicators
            const maxIndicatorIndex = Math.max(0, totalSlides - slidesPerView);
            indicators.forEach((dot, index) => {
                dot.classList.toggle('active', index === currentIndex);
                dot.style.display = index <= maxIndicatorIndex ? 'block' : 'none';
            });

            // Update buttons
            if (prevBtn) prevBtn.disabled = currentIndex === 0;
            if (nextBtn) nextBtn.disabled = currentIndex >= maxIndex;
        };

        // ----- Slide Controls -----
        if (prevBtn) {
            prevBtn.addEventListener('click', function() {
                if (currentIndex > 0) {
                    currentIndex--;
                    updateCarousel();
                    resetAutoPlay();
                }
            });
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', function() {
                const maxIndex = Math.max(0, totalSlides - slidesPerView);
                if (currentIndex < maxIndex) {
                    currentIndex++;
                    updateCarousel();
                    resetAutoPlay();
                }
            });
        }

        // ----- Indicator Controls -----
        indicators.forEach((dot, index) => {
            dot.addEventListener('click', function() {
                const maxIndex = Math.max(0, totalSlides - slidesPerView);
                if (index <= maxIndex) {
                    currentIndex = index;
                    updateCarousel();
                    resetAutoPlay();
                }
            });
        });

        // ----- Auto Play -----
        const startAutoPlay = () => {
            if (autoPlayInterval) clearInterval(autoPlayInterval);
            autoPlayInterval = setInterval(() => {
                const maxIndex = Math.max(0, totalSlides - slidesPerView);
                if (currentIndex < maxIndex) {
                    currentIndex++;
                    updateCarousel();
                } else {
                    currentIndex = 0;
                    updateCarousel();
                }
            }, 6000);
        };

        const resetAutoPlay = () => {
            if (autoPlayInterval) {
                clearInterval(autoPlayInterval);
                startAutoPlay();
            }
        };

        // Pause on hover
        const carouselWrapper = document.querySelector('.carousel-track-wrapper');
        if (carouselWrapper) {
            carouselWrapper.addEventListener('mouseenter', () => {
                if (autoPlayInterval) {
                    clearInterval(autoPlayInterval);
                }
            });
            carouselWrapper.addEventListener('mouseleave', startAutoPlay);
        }

        // ----- Topic Item Interaction -----
        topicItems.forEach((item) => {
            item.addEventListener('click', function() {
                const topic = this.textContent.trim();
                console.log('🔍 Topic clicked:', topic);
                // Future: Filter articles by topic
                this.style.color = 'var(--color-lime-dark)';
                setTimeout(() => {
                    this.style.color = '';
                }, 1000);
            });
        });

        // ----- Window Resize -----
        let resizeTimeout;
        window.addEventListener('resize', () => {
            clearTimeout(resizeTimeout);
            resizeTimeout = setTimeout(updateCarousel, 200);
        });

        // ----- Initialize -----
        setTimeout(() => {
            updateCarousel();
            startAutoPlay();
        }, 100);

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const tcBadge = document.querySelector('.trending-content__badge');
        const tcTitle = document.querySelector('.trending-content__title');
        const tcSubtitle = document.querySelector('.trending-content__subtitle');
        const tcFeatured = document.querySelector('.trending-featured');
        const tcColumns = document.querySelector('.trending-content__columns');
        const tcTopics = document.querySelector('.trending-content__topics');
        const tcCarousel = document.querySelector('.trending-content__carousel');
        const tcMetrics = document.querySelector('.trending-content__metrics');
        const tcViewAll = document.querySelector('.trending-content__view-all');

        // Set initial state for header elements
        const headerElements = [tcBadge, tcTitle, tcSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        [tcFeatured, tcColumns, tcTopics, tcCarousel, tcMetrics, tcViewAll].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for trending items
        const trendingItems = document.querySelectorAll('.trending-item');
        trendingItems.forEach((item, index) => {
            item.style.opacity = '0';
            item.style.transform = 'translateX(-10px)';
            item.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${150 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${150 + (index * 30)}ms`;
        });

        // Create observer
        const tcObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate sections with staggered delay
                    [tcFeatured, tcColumns, tcTopics, tcCarousel, tcMetrics, tcViewAll].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    // Animate trending items with staggered delay
                    trendingItems.forEach((item, index) => {
                        setTimeout(() => {
                            item.style.opacity = '1';
                            item.style.transform = 'translateX(0)';
                        }, 350 + (index * 30));
                    });

                    tcObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const tcSection = document.getElementById('trending-content');
        if (tcSection) {
            tcObserver.observe(tcSection);
        }

        console.log('🔥 Trending Content section initialized.');
    };

    // Initialize Trending Content
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initTrendingContent);
    } else {
        initTrendingContent();
    }

