    // ============================================================
    // 56. COMMUNITY SUBSCRIPTION — FORM HANDLING & ANIMATIONS
    // ============================================================
    const initCommunitySubscription = () => {
        const form = document.getElementById('subscription-form');
        const subscribeBtn = document.getElementById('subscribe-btn');
        const successMsg = document.getElementById('form-success');
        const errorMsg = document.getElementById('form-error');
        const nameInput = document.getElementById('subscriber-name');
        const emailInput = document.getElementById('subscriber-email');
        const consentCheckbox = document.getElementById('privacy-consent');

        // ----- Form Submission -----
        if (form) {
            form.addEventListener('submit', function(e) {
                e.preventDefault();

                // Reset messages
                successMsg.style.display = 'none';
                errorMsg.style.display = 'none';

                // Validate required fields
                const name = nameInput ? nameInput.value.trim() : '';
                const email = emailInput ? emailInput.value.trim() : '';
                const consent = consentCheckbox ? consentCheckbox.checked : false;

                if (!name) {
                    showError('Please enter your full name.');
                    if (nameInput) nameInput.focus();
                    return;
                }

                if (!email || !isValidEmail(email)) {
                    showError('Please enter a valid email address.');
                    if (emailInput) emailInput.focus();
                    return;
                }

                if (!consent) {
                    showError('Please agree to our privacy policy to continue.');
                    if (consentCheckbox) consentCheckbox.focus();
                    return;
                }

                // Show loading state
                subscribeBtn.classList.add('loading');
                subscribeBtn.disabled = true;

                // Simulate API call
                setTimeout(() => {
                    // Get selected preferences
                    const preferences = [];
                    document.querySelectorAll('.preference-checkbox:checked').forEach((cb) => {
                        preferences.push(cb.value);
                    });

                    // Log subscription data (future Laravel integration)
                    console.log('📧 Subscription Data:', {
                        name: name,
                        email: email,
                        company: document.getElementById('subscriber-company')?.value || '',
                        role: document.getElementById('subscriber-role')?.value || '',
                        preferences: preferences,
                        consent: consent
                    });

                    // Show success
                    subscribeBtn.classList.remove('loading');
                    subscribeBtn.disabled = false;
                    subscribeBtn.classList.add('success');
                    subscribeBtn.querySelector('.btn-text').textContent = '✓ Subscribed!';

                    successMsg.style.display = 'flex';
                    successMsg.querySelector('span').textContent =
                        'Thank you for subscribing! Check your email to confirm your subscription.';

                    // Reset form after success
                    if (nameInput) nameInput.value = '';
                    if (emailInput) emailInput.value = '';
                    document.getElementById('subscriber-company').value = '';
                    document.getElementById('subscriber-role').value = '';
                    document.querySelectorAll('.preference-checkbox:checked').forEach((cb) => {
                        cb.checked = false;
                    });
                    if (consentCheckbox) consentCheckbox.checked = false;

                    // Reset button after 5 seconds
                    setTimeout(() => {
                        subscribeBtn.classList.remove('success');
                        subscribeBtn.querySelector('.btn-text').textContent = 'Subscribe Now';
                    }, 5000);
                }, 1500);
            });
        }

        // ----- Helper Functions -----
        const isValidEmail = (email) => {
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
        };

        const showError = (message) => {
            errorMsg.style.display = 'flex';
            errorMsg.querySelector('span').textContent = message;
        };

        // ----- Real-time Validation -----
        if (emailInput) {
            emailInput.addEventListener('blur', function() {
                const email = this.value.trim();
                if (email && !isValidEmail(email)) {
                    this.style.borderColor = '#F87171';
                    this.style.boxShadow = '0 0 0 4px rgba(248, 113, 113, 0.1)';
                } else {
                    this.style.borderColor = '';
                    this.style.boxShadow = '';
                }
            });

            emailInput.addEventListener('input', function() {
                this.style.borderColor = '';
                this.style.boxShadow = '';
                errorMsg.style.display = 'none';
            });
        }

        if (nameInput) {
            nameInput.addEventListener('input', function() {
                errorMsg.style.display = 'none';
            });
        }

        if (consentCheckbox) {
            consentCheckbox.addEventListener('change', function() {
                errorMsg.style.display = 'none';
            });
        }

        // ----- Preference Checkbox Animation -----
        document.querySelectorAll('.preference-item').forEach((item) => {
            item.addEventListener('mouseenter', function() {
                this.style.background = 'rgba(124, 58, 237, 0.04)';
            });
            item.addEventListener('mouseleave', function() {
                this.style.background = '';
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const csBadge = document.querySelector('.community-subscription__badge');
        const csTitle = document.querySelector('.community-subscription__title');
        const csSubtitle = document.querySelector('.community-subscription__subtitle');
        const csForm = document.querySelector('.subscription-form');
        const csSidebar = document.querySelector('.subscription-sidebar');
        const csBenefits = document.querySelector('.community-benefits');
        const csTrust = document.querySelector('.trust-indicators');
        const csSocial = document.querySelector('.social-community');

        // Set initial state for header elements
        const headerElements = [csBadge, csTitle, csSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for main sections
        [csForm, csSidebar].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 80)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 80)}ms`;
            }
        });

        // Set initial state for sidebar components
        [csBenefits, csTrust, csSocial].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 60)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 60)}ms`;
            }
        });

        // Set initial state for benefit items
        const benefitItems = document.querySelectorAll('.benefit-item');
        benefitItems.forEach((item, index) => {
            item.style.opacity = '0';
            item.style.transform = 'translateX(-10px)';
            item.style.transition = `opacity 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 20)}ms, transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 20)}ms`;
        });

        // Create observer
        const csObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate main sections
                    [csForm, csSidebar].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 80));
                        }
                    });

                    // Animate sidebar components
                    [csBenefits, csTrust, csSocial].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 250 + (index * 60));
                        }
                    });

                    // Animate benefit items with staggered delay
                    benefitItems.forEach((item, index) => {
                        setTimeout(() => {
                            item.style.opacity = '1';
                            item.style.transform = 'translateX(0)';
                        }, 350 + (index * 20));
                    });

                    csObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const csSection = document.getElementById('community-subscription');
        if (csSection) {
            csObserver.observe(csSection);
        }

        console.log('📬 Community Subscription Hub initialized.');
    };

    // Initialize Community Subscription
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCommunitySubscription);
    } else {
        initCommunitySubscription();
    }

