    // ============================================================
    // 57. MEET AUTHORS — SCROLL ANIMATIONS & INTERACTIONS
    // ============================================================
    const initMeetAuthors = () => {
        const authorCards = document.querySelectorAll('.author-card');
        const featuredAuthor = document.querySelector('.featured-author');
        const statNumbers = document.querySelectorAll('.stat-card .stat-number');
        const contributionBadges = document.querySelectorAll('.contribution-badge');
        const maBadge = document.querySelector('.meet-authors__badge');
        const maTitle = document.querySelector('.meet-authors__title');
        const maSubtitle = document.querySelector('.meet-authors__subtitle');
        const viewAllBtn = document.querySelector('.btn-view-authors');

        // Set initial state for header elements
        const headerElements = [maBadge, maTitle, maSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for featured author
        if (featuredAuthor) {
            featuredAuthor.style.opacity = '0';
            featuredAuthor.style.transform = 'translateY(30px)';
            featuredAuthor.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Set initial state for author cards
        authorCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(25px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${index * 60}ms`;
        });

        // Set initial state for stats
        const statsContainer = document.querySelector('.meet-authors__stats');
        if (statsContainer) {
            statsContainer.style.opacity = '0';
            statsContainer.style.transform = 'translateY(20px)';
            statsContainer.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Set initial state for contributions
        const contributionsContainer = document.querySelector('.meet-authors__contributions');
        if (contributionsContainer) {
            contributionsContainer.style.opacity = '0';
            contributionsContainer.style.transform = 'translateY(20px)';
            contributionsContainer.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Set initial state for view all button
        if (viewAllBtn) {
            viewAllBtn.style.opacity = '0';
            viewAllBtn.style.transform = 'translateY(15px)';
            viewAllBtn.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // ----- Counter Animation -----
        let statsAnimated = false;

        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const currentValue = Math.floor(eased * target);
                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    element.textContent = target;
                }
            };

            requestAnimationFrame(updateCount);
        };

        // ----- Contribution Badge Click -----
        contributionBadges.forEach((badge) => {
            badge.addEventListener('click', function() {
                const text = this.textContent.trim();
                console.log('🔍 Filter by contribution:', text);
                this.style.color = 'var(--color-lime-dark)';
                this.style.borderColor = 'var(--color-lime)';
                setTimeout(() => {
                    this.style.color = '';
                    this.style.borderColor = '';
                }, 1000);
            });
        });

        // ----- Create observer -----
        const maObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate featured author
                    if (featuredAuthor) {
                        setTimeout(() => {
                            featuredAuthor.style.opacity = '1';
                            featuredAuthor.style.transform = 'translateY(0)';
                        }, 200);
                    }

                    // Animate author cards with staggered delay
                    authorCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 250 + (index * 60));
                    });

                    // Animate stats
                    if (statsContainer) {
                        setTimeout(() => {
                            statsContainer.style.opacity = '1';
                            statsContainer.style.transform = 'translateY(0)';
                        }, 300);
                    }

                    // Animate contributions
                    if (contributionsContainer) {
                        setTimeout(() => {
                            contributionsContainer.style.opacity = '1';
                            contributionsContainer.style.transform = 'translateY(0)';
                        }, 350);
                    }

                    // Animate view all button
                    if (viewAllBtn) {
                        setTimeout(() => {
                            viewAllBtn.style.opacity = '1';
                            viewAllBtn.style.transform = 'translateY(0)';
                        }, 400);
                    }

                    // Animate stat counters
                    if (!statsAnimated) {
                        statsAnimated = true;
                        statNumbers.forEach((statEl) => {
                            const target = parseInt(statEl.getAttribute('data-count'), 10);
                            if (isNaN(target)) return;
                            statEl.textContent = '0';
                            animateCount(statEl, target);
                        });
                    }

                    maObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const maSection = document.getElementById('meet-authors');
        if (maSection) {
            maObserver.observe(maSection);
        }

        console.log('✍️ Meet Our Authors section initialized with', authorCards.length, 'authors.');
    };

    // Initialize Meet Authors
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initMeetAuthors);
    } else {
        initMeetAuthors();
    }

