    // ============================================================
    // 59. DOCUMENTATION HERO — ANIMATIONS & INTERACTIONS
    // ============================================================
    const initDocsHero = () => {
        const dhContent = document.querySelector('.docs-hero__content');
        const dhVisual = document.querySelector('.docs-hero__visual');
        const dhBadge = document.querySelector('.docs-hero__badge');
        const dhTitle = document.querySelector('.docs-hero__title');
        const dhDescription = document.querySelector('.docs-hero__description');
        const dhButtons = document.querySelector('.docs-hero__buttons');
        const dhSearch = document.querySelector('.docs-hero__search');
        const dhQuickLinks = document.querySelector('.docs-hero__quick-links');
        const dhStats = document.querySelector('.docs-hero__stats');
        const mockup = document.querySelector('.docs-visual__mockup');
        const resources = document.querySelectorAll('.docs-visual__resource');
        const statNumbers = document.querySelectorAll('.docs-hero__stats .stat-number');

        // Set initial state for content elements
        const contentElements = [
            dhBadge,
            dhTitle,
            dhDescription,
            dhButtons,
            dhSearch,
            dhQuickLinks,
            dhStats
        ];

        contentElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for visual elements
        if (mockup) {
            mockup.style.opacity = '0';
            mockup.style.transform = 'scale(0.95)';
            mockup.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        resources.forEach((resource, index) => {
            resource.style.opacity = '0';
            resource.style.transform = 'translateY(20px) scale(0.9)';
            resource.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 60)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 60)}ms`;
        });

        // ----- Search Functionality -----
        const searchInput = document.getElementById('docs-search');
        const searchClear = document.getElementById('docs-search-clear');
        const searchSubmit = document.querySelector('.search-submit');
        const searchVoice = document.querySelector('.search-voice');
        const searchRecent = document.getElementById('search-recent');

        if (searchInput) {
            searchInput.addEventListener('input', function() {
                const value = this.value.trim();
                if (searchClear) {
                    if (value.length > 0) {
                        searchClear.classList.add('visible');
                    } else {
                        searchClear.classList.remove('visible');
                    }
                }
                if (searchRecent) {
                    if (value.length > 2) {
                        searchRecent.style.display = 'flex';
                    } else {
                        searchRecent.style.display = 'none';
                    }
                }
            });

            // Clear button
            if (searchClear) {
                searchClear.addEventListener('click', function() {
                    if (searchInput) {
                        searchInput.value = '';
                        searchInput.focus();
                        this.classList.remove('visible');
                        if (searchRecent) {
                            searchRecent.style.display = 'none';
                        }
                    }
                });
            }

            // Enter key
            searchInput.addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    const query = this.value.trim();
                    if (query) {
                        console.log('🔍 Docs search:', query);
                    }
                }
            });
        }

        // Search submit
        if (searchSubmit) {
            searchSubmit.addEventListener('click', function(e) {
                e.preventDefault();
                if (searchInput) {
                    const query = searchInput.value.trim();
                    if (query) {
                        console.log('🔍 Docs search:', query);
                    }
                }
            });
        }

        // Voice search
        if (searchVoice) {
            searchVoice.addEventListener('click', function() {
                if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
                    console.log('🎤 Voice search activated');
                    this.style.color = 'var(--color-lime)';
                    setTimeout(() => {
                        this.style.color = '';
                    }, 2000);
                } else {
                    alert('Voice search is not supported in your browser.');
                }
            });
        }

        // Recent chips
        const recentChips = document.querySelectorAll('.recent-chip');
        recentChips.forEach((chip) => {
            chip.addEventListener('click', function() {
                const term = this.textContent.trim();
                if (searchInput) {
                    searchInput.value = term;
                    if (searchClear) {
                        searchClear.classList.add('visible');
                    }
                    if (searchRecent) {
                        searchRecent.style.display = 'flex';
                    }
                    console.log('🔍 Recent search:', term);
                }
            });
        });

        // Quick chips
        const quickChips = document.querySelectorAll('.quick-chip');
        quickChips.forEach((chip) => {
            chip.addEventListener('click', function() {
                const term = this.textContent.trim();
                console.log('🔍 Quick access:', term);
                this.style.borderColor = 'var(--color-lime)';
                this.style.color = 'var(--color-lime-dark)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.color = '';
                }, 800);
            });
        });

        // ----- Counter Animation -----
        let statsAnimated = false;

        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);

                // Handle decimal values (e.g., 99.9)
                let currentValue;
                if (target % 1 !== 0) {
                    currentValue = (eased * target).toFixed(1);
                } else {
                    currentValue = Math.floor(eased * target);
                }

                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    if (target % 1 !== 0) {
                        element.textContent = target.toFixed(1);
                    } else {
                        element.textContent = target;
                    }
                }
            };

            requestAnimationFrame(updateCount);
        };

        // ----- Create observer -----
        const dhObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate content elements with staggered delay
                    contentElements.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100 + (index * 50));
                        }
                    });

                    // Animate mockup
                    if (mockup) {
                        setTimeout(() => {
                            mockup.style.opacity = '1';
                            mockup.style.transform = 'scale(1)';
                        }, 200);
                    }

                    // Animate resources
                    resources.forEach((resource, index) => {
                        setTimeout(() => {
                            resource.style.opacity = '1';
                            resource.style.transform = 'translateY(0) scale(1)';
                        }, 350 + (index * 60));
                    });

                    // Animate stat counters
                    if (!statsAnimated) {
                        statsAnimated = true;
                        statNumbers.forEach((statEl) => {
                            const target = parseFloat(statEl.getAttribute('data-count'));
                            if (isNaN(target)) return;
                            if (target % 1 === 0) {
                                statEl.textContent = '0';
                            } else {
                                statEl.textContent = '0.0';
                            }
                            animateCount(statEl, target);
                        });
                    }

                    dhObserver.disconnect();
                }
            });
        }, {
            threshold: 0.15,
            rootMargin: '0px 0px -50px 0px'
        });

        const dhSection = document.getElementById('docs-hero');
        if (dhSection) {
            dhObserver.observe(dhSection);
        }

        console.log('📚 Documentation Hero initialized.');
    };

    // Initialize Documentation Hero
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDocsHero);
    } else {
        initDocsHero();
    }

/* ==================================================
END: Documentation Hero Banner JavaScript
================================================== */

