    // ============================================================
    // 66. DOWNLOADS CENTER — INTERACTIONS & ANIMATIONS
    // ============================================================
    const initDownloadsCenter = () => {
        // ----- SDK Download Buttons -----
        const sdkDownloadBtns = document.querySelectorAll('.sdk-btn--download');

        sdkDownloadBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                const card = this.closest('.sdk-card');
                const name = card?.querySelector('.sdk-card__name')?.textContent || 'SDK';
                console.log('📦 Downloading SDK:', name);

                this.innerHTML = '<i class="fas fa-check"></i>';
                this.style.borderColor = 'var(--color-lime)';
                this.style.color = 'var(--color-lime-dark)';
                this.style.background = 'rgba(192, 227, 74, 0.08)';

                setTimeout(() => {
                    this.innerHTML = '<i class="fas fa-download"></i>';
                    this.style.borderColor = '';
                    this.style.color = '';
                    this.style.background = '';
                }, 2000);
            });
        });

        // ----- SDK Documentation Buttons -----
        const sdkDocsBtns = document.querySelectorAll('.sdk-btn--docs');

        sdkDocsBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                const card = this.closest('.sdk-card');
                const name = card?.querySelector('.sdk-card__name')?.textContent || 'SDK';
                console.log('📖 SDK Documentation:', name);
            });
        });

        // ----- SDK Release Notes Buttons -----
        const sdkNotesBtns = document.querySelectorAll('.sdk-btn--notes');

        sdkNotesBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                const card = this.closest('.sdk-card');
                const name = card?.querySelector('.sdk-card__name')?.textContent || 'SDK';
                console.log('📋 Release Notes for:', name);

                this.innerHTML = '<i class="fas fa-check"></i>';
                setTimeout(() => {
                    this.innerHTML = '<i class="fas fa-history"></i>';
                }, 1500);
            });
        });

        // ----- Library Item Download Buttons -----
        const libraryBtns = document.querySelectorAll('.library-item__btn');

        libraryBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                const item = this.closest('.library-item');
                const name = item?.querySelector('.library-item__name')?.textContent || 'Resource';
                console.log('📥 Downloading:', name);

                this.innerHTML = '<i class="fas fa-check"></i>';
                this.style.borderColor = 'var(--color-lime)';
                this.style.color = 'var(--color-lime-dark)';

                setTimeout(() => {
                    this.innerHTML = '<i class="fas fa-download"></i>';
                    this.style.borderColor = '';
                    this.style.color = '';
                }, 2000);
            });
        });

        // ----- Toolkit Items -----
        const toolkitItems = document.querySelectorAll('.toolkit-item');

        toolkitItems.forEach((item) => {
            item.addEventListener('click', function(e) {
                e.preventDefault();
                const label = this.querySelector('.toolkit-item__label')?.textContent || '';
                console.log('🔧 Toolkit item clicked:', label);

                this.style.borderColor = 'var(--color-lime)';
                this.style.background = 'rgba(192, 227, 74, 0.06)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.background = '';
                }, 800);
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const dcBadge = document.querySelector('.downloads-center__badge');
        const dcTitle = document.querySelector('.downloads-center__title');
        const dcSubtitle = document.querySelector('.downloads-center__subtitle');
        const dcFeatured = document.querySelector('.featured-resource');
        const dcSdks = document.querySelector('.downloads-center__sdks');
        const dcLibrary = document.querySelector('.downloads-center__library');
        const dcToolkit = document.querySelector('.downloads-center__toolkit');
        const dcMetrics = document.querySelector('.downloads-center__metrics');
        const dcQuickActions = document.querySelector('.downloads-center__quick-actions');
        const dcViewAll = document.querySelector('.btn-view-resources');

        // Set initial state for header elements
        const headerElements = [dcBadge, dcTitle, dcSubtitle];
        headerElements.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        [dcFeatured, dcSdks, dcLibrary, dcToolkit, dcMetrics, dcQuickActions].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        if (dcViewAll) {
            dcViewAll.style.opacity = '0';
            dcViewAll.style.transform = 'translateY(15px)';
            dcViewAll.style.transition = 'opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // Set initial state for SDK cards
        const sdkCards = document.querySelectorAll('.sdk-card');
        sdkCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateX(-15px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${150 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${150 + (index * 30)}ms`;
        });

        // Set initial state for library items
        const libraryItems = document.querySelectorAll('.library-item');
        libraryItems.forEach((item, index) => {
            item.style.opacity = '0';
            item.style.transform = 'translateY(15px)';
            item.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${180 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${180 + (index * 30)}ms`;
        });

        // ----- Counter Animation -----
        const statNumbers = document.querySelectorAll('.metric-stat .stat-number');
        let statsAnimated = false;

        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const currentValue = Math.floor(eased * target);
                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    element.textContent = target;
                }
            };

            requestAnimationFrame(updateCount);
        };

        // ----- Create observer -----
        const dcObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElements.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate sections with staggered delay
                    [dcFeatured, dcSdks, dcLibrary, dcToolkit, dcMetrics, dcQuickActions].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    // Animate SDK cards with staggered delay
                    sdkCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateX(0)';
                        }, 300 + (index * 30));
                    });

                    // Animate library items with staggered delay
                    libraryItems.forEach((item, index) => {
                        setTimeout(() => {
                            item.style.opacity = '1';
                            item.style.transform = 'translateY(0)';
                        }, 350 + (index * 30));
                    });

                    // Animate view all button
                    if (dcViewAll) {
                        setTimeout(() => {
                            dcViewAll.style.opacity = '1';
                            dcViewAll.style.transform = 'translateY(0)';
                        }, 400);
                    }

                    // Animate stat counters
                    if (!statsAnimated) {
                        statsAnimated = true;
                        statNumbers.forEach((statEl) => {
                            const target = parseInt(statEl.getAttribute('data-count'), 10);
                            if (isNaN(target)) return;
                            statEl.textContent = '0';
                            animateCount(statEl, target);
                        });
                    }

                    dcObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const dcSection = document.getElementById('downloads-center');
        if (dcSection) {
            dcObserver.observe(dcSection);
        }

        console.log('📦 Downloads Center & SDK Library initialized.');
    };

    // Initialize Downloads Center
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDownloadsCenter);
    } else {
        initDownloadsCenter();
    }

/* ==================================================
END: Downloads Center, SDK Library & Developer Resources JavaScript
================================================== */

