        const searchBtn = document.querySelector('.support-search__btn');

        if (searchBtn && searchInput) {
            const performSearch = () => {
                const query = searchInput.value.trim();
                if (query.length > 2) {
                    console.log('🔍 Searching support for:', query);
                    // Future AJAX search integration
                } else {
                    console.log('🔍 Please enter at least 3 characters.');
                }
            };

            searchBtn.addEventListener('click', function(e) {
                e.preventDefault();
                performSearch();
            });

            searchInput.addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    performSearch();
                }
            });
        }

        // ----- Recent Search Tags (for demo) -----
        const recentTags = document.querySelectorAll('.support-search__recent-tag');
        recentTags.forEach((tag) => {
            tag.addEventListener('click', function() {
                if (searchInput) {
                    searchInput.value = this.textContent.trim();
                    // Optionally trigger search
                    console.log('🔍 Quick search:', this.textContent.trim());
                }
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const shBadge = document.querySelector('.support-hub__badge');
        const shTitle = document.querySelector('.support-hub__title');
        const shSubtitle = document.querySelector('.support-hub__subtitle');
        const shSearch = document.querySelector('.support-hub__search');
        const shFaq = document.querySelector('.support-hub__faq');
        const shTrouble = document.querySelector('.support-hub__troubleshooting');
        const shDiagnostics = document.querySelector('.support-hub__diagnostics');
        const shOptions = document.querySelector('.support-hub__options');
        const shCommunity = document.querySelector('.support-hub__community');
        const shMetrics = document.querySelector('.support-hub__metrics');
