            card.style.transform = 'scale(0.95)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${280 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${280 + (index * 30)}ms`;
