            opt.style.transform = 'translateY(15px)';
            opt.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 25)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${300 + (index * 25)}ms`;
