    // ============================================================
    // 71. SMART CONTACT FORM — MULTI-STEP, VALIDATION, INTERACTIONS
    // ============================================================
    const initContactForm = () => {
        const form = document.getElementById('project-inquiry-form');
        if (!form) return;

        const sections = form.querySelectorAll('.form-section');
        const progressFill = form.querySelector('.form-progress__fill');
        const progressLabel = form.querySelector('.form-progress__label');
        const nextBtns = form.querySelectorAll('.btn-form-next');
        const prevBtns = form.querySelectorAll('.btn-form-prev');
        const submitBtn = form.querySelector('.btn-submit-form');
        const successMsg = form.querySelector('.form-success');
        const errorGlobal = form.querySelector('.form-error-global');
        const fileInput = form.querySelector('.file-upload-input');
        const fileList = form.querySelector('.file-upload-list');
        const fileArea = form.querySelector('.file-upload-area');

        let currentSection = 0;
        let totalSections = sections.length;

        // ----- Utility: Show Section -----
        function showSection(index) {
            sections.forEach((section, i) => {
                section.classList.toggle('form-section--active', i === index);
            });
            updateProgress(index);
            updateReviewData();
            window.scrollTo({ top: form.offsetTop - 100, behavior: 'smooth' });
        }

        // ----- Update Progress -----
        function updateProgress(index) {
            const progress = ((index + 1) / totalSections) * 100;
            if (progressFill) progressFill.style.width = progress + '%';
            if (progressLabel) progressLabel.textContent = Math.round(progress) + '% Complete';
        }

        // ----- Update Review Summary -----
        function updateReviewData() {
            const fields = {
                'review-name': 'full_name',
                'review-email': 'email',
                'review-service': 'service',
                'review-project': 'project_title',
                'review-budget': 'budget',
                'review-timeline': 'timeline'
            };

            Object.entries(fields).forEach(([reviewId, fieldName]) => {
                const el = document.getElementById(reviewId);
                if (!el) return;
                let value = '—';

                if (fieldName === 'budget' || fieldName === 'timeline' || fieldName === 'comm_pref') {
                    const checked = form.querySelector(`input[name="${fieldName}"]:checked`);
                    if (checked) value = checked.value;
                } else {
                    const input = form.querySelector(`[name="${fieldName}"]`);
                    if (input) value = input.value || '—';
                }

                el.textContent = value;
            });
        }

        // ----- Validate Section -----
        function validateSection(index) {
            const section = sections[index];
            const inputs = section.querySelectorAll('input[required], select[required], textarea[required]');
            let valid = true;

            inputs.forEach((input) => {
                const errorEl = input.closest('.form-group')?.querySelector('.form-error') ||
                                input.closest('.form-group')?.querySelector('.form-error-radio');
                let isValid = true;

                if (input.type === 'radio') {
                    const group = input.closest('.form-radio-group');
                    if (group) {
                        const checked = group.querySelector('input[type="radio"]:checked');
                        isValid = !!checked;
                        const error = group.closest('.form-group')?.querySelector('.form-error');
                        if (error) {
                            error.classList.toggle('visible', !isValid);
                        }
                    }
                } else if (input.type === 'checkbox' && input.name === 'consent') {
                    isValid = input.checked;
                    const error = input.closest('.form-group')?.querySelector('.form-error');
                    if (error) error.classList.toggle('visible', !isValid);
                } else if (input.type === 'email') {
                    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                    isValid = emailRegex.test(input.value.trim());
                    if (errorEl) errorEl.classList.toggle('visible', !isValid);
                    input.classList.toggle('error', !isValid);
                } else {
                    isValid = input.value.trim().length > 0;
                    if (errorEl) errorEl.classList.toggle('visible', !isValid);
                    input.classList.toggle('error', !isValid);
                }

                if (!isValid) valid = false;
            });

            return valid;
        }

        // ----- Next Button -----
        nextBtns.forEach((btn) => {
            btn.addEventListener('click', function() {
                const nextIndex = parseInt(this.dataset.next, 10) - 1;
                if (validateSection(currentSection)) {
                    currentSection = nextIndex;
                    showSection(currentSection);
                } else {
                    if (errorGlobal) {
                        errorGlobal.style.display = 'flex';
                        errorGlobal.querySelector('.error-text').textContent = 'Please fill in all required fields before proceeding.';
                    }
                    const firstError = sections[currentSection].querySelector('.form-error.visible');
                    if (firstError) {
                        firstError.closest('.form-group')?.querySelector('input, select, textarea')?.focus();
                    }
                    setTimeout(() => {
                        if (errorGlobal) errorGlobal.style.display = 'none';
                    }, 4000);
                }
            });
        });

        // ----- Prev Button -----
        prevBtns.forEach((btn) => {
            btn.addEventListener('click', function() {
                const prevIndex = parseInt(this.dataset.prev, 10) - 1;
                currentSection = prevIndex;
                showSection(currentSection);
            });
        });

        // ----- Real-time validation on input -----
        form.querySelectorAll('input, select, textarea').forEach((input) => {
            input.addEventListener('blur', function() {
                const errorEl = this.closest('.form-group')?.querySelector('.form-error');
                if (this.hasAttribute('required') && !this.value.trim()) {
                    this.classList.add('error');
                    if (errorEl) errorEl.classList.add('visible');
                } else if (this.type === 'email' && this.value.trim()) {
                    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                    if (!emailRegex.test(this.value.trim())) {
                        this.classList.add('error');
                        if (errorEl) errorEl.classList.add('visible');
                    } else {
                        this.classList.remove('error');
                        if (errorEl) errorEl.classList.remove('visible');
                    }
                } else {
                    this.classList.remove('error');
                    if (errorEl) errorEl.classList.remove('visible');
                }
            });

            // Character counter for textarea
            if (input.tagName === 'TEXTAREA' && input.hasAttribute('maxlength')) {
                input.addEventListener('input', function() {
                    const count = this.value.length;
                    const max = parseInt(this.getAttribute('maxlength'), 10);
                    const counter = this.closest('.form-group')?.querySelector('.char-count');
                    if (counter) counter.textContent = count;
                    if (count > max) {
                        this.value = this.value.slice(0, max);
                        if (counter) counter.textContent = max;
                    }
                });
            }
        });

        // ----- File Upload -----
        if (fileInput && fileArea) {
            fileArea.addEventListener('click', () => fileInput.click());

            fileInput.addEventListener('change', function() {
                const files = this.files;
                if (fileList) fileList.innerHTML = '';
                if (files.length === 0) return;

                Array.from(files).forEach((file, index) => {
                    const item = document.createElement('div');
                    item.className = 'file-upload-item';
                    item.innerHTML = `
                        <span class="file-upload-item__name"><i class="fas fa-file"></i> ${file.name} (${(file.size / 1024).toFixed(1)} KB)</span>
                        <button type="button" class="file-upload-item__remove" data-index="${index}">&times;</button>
                    `;
                    fileList.appendChild(item);

                    const removeBtn = item.querySelector('.file-upload-item__remove');
                    removeBtn.addEventListener('click', function() {
                        const dt = new DataTransfer();
                        const remaining = Array.from(fileInput.files).filter((_, i) => i !== index);
                        remaining.forEach(f => dt.items.add(f));
                        fileInput.files = dt.files;
                        item.remove();
                    });
                });
            });

            // Drag and drop
            ['dragover', 'dragenter'].forEach(event => {
                fileArea.addEventListener(event, (e) => {
                    e.preventDefault();
                    fileArea.classList.add('dragover');
                });
            });

            ['dragleave', 'dragend', 'drop'].forEach(event => {
                fileArea.addEventListener(event, (e) => {
                    e.preventDefault();
                    fileArea.classList.remove('dragover');
                });
            });

            fileArea.addEventListener('drop', function(e) {
                e.preventDefault();
                const files = e.dataTransfer.files;
                if (files.length > 0) {
                    fileInput.files = files;
                    fileInput.dispatchEvent(new Event('change'));
                }
            });
        }

        // ----- Form Submit -----
        form.addEventListener('submit', function(e) {
            e.preventDefault();

            // Validate all sections
            let allValid = true;
            for (let i = 0; i < totalSections; i++) {
                if (!validateSection(i)) allValid = false;
            }

            if (!allValid) {
                currentSection = 0;
                showSection(0);
                if (errorGlobal) {
                    errorGlobal.style.display = 'flex';
                    errorGlobal.querySelector('.error-text').textContent = 'Please fill in all required fields across all sections.';
                    setTimeout(() => {
                        if (errorGlobal) errorGlobal.style.display = 'none';
                    }, 4000);
                }
                return;
            }

            // Submit loading state
            if (submitBtn) {
                submitBtn.classList.add('loading');
                submitBtn.disabled = true;
            }

            // Simulate API call
            setTimeout(() => {
                if (submitBtn) {
                    submitBtn.classList.remove('loading');
                    submitBtn.classList.add('success');
                }

                // Hide form, show success
                form.style.display = 'none';
                if (successMsg) successMsg.style.display = 'block';

                // Log form data
                const formData = new FormData(form);
                console.log('📝 Form submitted:', Object.fromEntries(formData));

                // Reset button after a delay
                setTimeout(() => {
                    if (submitBtn) {
                        submitBtn.classList.remove('success');
                        submitBtn.disabled = false;
                    }
                }, 3000);

            }, 2500);
        });

        // ----- Reset Form (Success) -----
        const resetBtn = document.querySelector('.btn-success-reset');
        if (resetBtn) {
            resetBtn.addEventListener('click', function(e) {
                e.preventDefault();
                if (successMsg) successMsg.style.display = 'none';
                form.style.display = 'block';
                form.reset();
                if (fileList) fileList.innerHTML = '';
                currentSection = 0;
                showSection(0);
                if (submitBtn) {
                    submitBtn.classList.remove('loading', 'success');
                    submitBtn.disabled = false;
                }
                if (errorGlobal) errorGlobal.style.display = 'none';
                console.log('🔄 Form reset');
            });
        }

        // ----- Init -----
        showSection(0);
        console.log('📋 Smart Contact Form initialized.');
    };

    // Initialize Contact Form
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initContactForm);
    } else {
        initContactForm();
    }

/* ==================================================
END: Smart Contact Form & Project Inquiry JavaScript
================================================== */

