    // ============================================================
    // 72. OFFICE LOCATION — MAP INTERACTIONS & ANIMATIONS
    // ============================================================
    const initOfficeLocation = () => {
        // ----- Map Controls (UI only - placeholder for real map integration) -----
        const zoomInBtn = document.querySelector('.map-control--zoom-in');
        const zoomOutBtn = document.querySelector('.map-control--zoom-out');
        const fullscreenBtn = document.querySelector('.map-control--fullscreen');
        const routeBtn = document.querySelector('.map-control--route');

        if (zoomInBtn) {
            zoomInBtn.addEventListener('click', function() {
                console.log('🔍 Map zoom in');
                // Future: integrate with Google Maps API
                this.style.transform = 'scale(0.9)';
                setTimeout(() => { this.style.transform = ''; }, 200);
            });
        }

        if (zoomOutBtn) {
            zoomOutBtn.addEventListener('click', function() {
                console.log('🔍 Map zoom out');
                this.style.transform = 'scale(0.9)';
                setTimeout(() => { this.style.transform = ''; }, 200);
            });
        }

        if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', function() {
                console.log('🖥️ Map fullscreen toggle');
                const container = this.closest('.map-container');
                if (container) {
                    if (!document.fullscreenElement) {
                        container.requestFullscreen?.() || container.webkitRequestFullscreen?.();
                    } else {
                        document.exitFullscreen?.() || document.webkitExitFullscreen?.();
                    }
                }
            });
        }

        if (routeBtn) {
            routeBtn.addEventListener('click', function() {
                console.log('🗺️ Get directions');
                // Future: open Google Maps directions
                this.style.transform = 'scale(0.9)';
                setTimeout(() => { this.style.transform = ''; }, 200);
            });
        }

        // ----- Map Pin Animation (already CSS animated) -----

        // ----- Direction Button -----
        const directionsBtn = document.querySelector('.btn-directions');
        if (directionsBtn) {
            directionsBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('🗺️ Get directions clicked');
                // Future: open Google Maps with coordinates
            });
        }

        // ----- Schedule Visit Button -----
        const scheduleBtn = document.querySelector('.btn-schedule-visit');
        if (scheduleBtn) {
            scheduleBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📅 Schedule a visit clicked');
                // Future: open booking modal
            });
        }

        // ----- Region Badges (click tracking) -----
        const regionBadges = document.querySelectorAll('.region-badge');
        regionBadges.forEach((badge) => {
            badge.addEventListener('click', function() {
                const region = this.textContent.trim();
                console.log('🌍 Region selected:', region);
                this.style.borderColor = 'var(--color-lime)';
                this.style.background = 'rgba(192, 227, 74, 0.06)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.background = '';
                }, 800);
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const olBadge = document.querySelector('.office-location__badge');
        const olTitle = document.querySelector('.office-location__title');
        const olSubtitle = document.querySelector('.office-location__subtitle');
        const olLayout = document.querySelector('.office-location__layout');
        const olGlobal = document.querySelector('.office-location__global');
        const olRegions = document.querySelector('.office-location__regions');
        const olHighlights = document.querySelector('.office-location__highlights');

        // Set initial state for header elements
        const headerElementsOL = [olBadge, olTitle, olSubtitle];
        headerElementsOL.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        const sectionsOL = [olLayout, olGlobal, olRegions, olHighlights];
        sectionsOL.forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for office card
        const officeCard = document.querySelector('.office-card');
        if (officeCard) {
            officeCard.style.opacity = '0';
            officeCard.style.transform = 'translateX(-20px)';
            officeCard.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 200ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 200ms';
        }

        // Set initial state for map container
        const mapContainer = document.querySelector('.map-container');
        if (mapContainer) {
            mapContainer.style.opacity = '0';
            mapContainer.style.transform = 'scale(0.96)';
            mapContainer.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 250ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 250ms';
        }

        // Set initial state for global cards
        const globalCards = document.querySelectorAll('.global-card');
        globalCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(15px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 40)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 40)}ms`;
        });

        // Set initial state for region badges
        const regionBadgesItems = document.querySelectorAll('.region-badge');
        regionBadgesItems.forEach((badge, index) => {
            badge.style.opacity = '0';
            badge.style.transform = 'scale(0.9)';
            badge.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 25)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 25)}ms`;
        });

        // Set initial state for highlight cards
        const highlightCards = document.querySelectorAll('.highlight-card');
        highlightCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(12px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 25)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 25)}ms`;
        });

        // ----- Observer -----
        const olObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElementsOL.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate sections
                    sectionsOL.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    // Animate office card
                    if (officeCard) {
                        setTimeout(() => {
                            officeCard.style.opacity = '1';
                            officeCard.style.transform = 'translateX(0)';
                        }, 250);
                    }

                    // Animate map container
                    if (mapContainer) {
                        setTimeout(() => {
                            mapContainer.style.opacity = '1';
                            mapContainer.style.transform = 'scale(1)';
                        }, 300);
                    }

                    // Animate global cards
                    globalCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 40));
                    });

                    // Animate region badges
                    regionBadgesItems.forEach((badge, index) => {
                        setTimeout(() => {
                            badge.style.opacity = '1';
                            badge.style.transform = 'scale(1)';
                        }, 320 + (index * 25));
                    });

                    // Animate highlight cards
                    highlightCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 340 + (index * 25));
                    });

                    olObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const olSection = document.getElementById('office-location');
        if (olSection) {
            olObserver.observe(olSection);
        }

        console.log('📍 Office Location & Global Presence initialized.');
    };

    // Initialize Office Location
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initOfficeLocation);
    } else {
        initOfficeLocation();
    }

