    // ============================================================
    // 77. SERVICES HERO — INTERACTIONS & ANIMATIONS
    // ============================================================
    const initServicesHero = () => {
        // ----- Button Interactions -----
        const startBtn = document.querySelector('.btn-services-start');
        const consultBtn = document.querySelector('.btn-services-consult');

        if (startBtn) {
            startBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('🚀 Start Your Project clicked from Services Hero');
            });
        }

        if (consultBtn) {
            consultBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📅 Book Free Consultation clicked from Services Hero');
            });
        }

        // ----- Trust Badge Click Tracking -----
        const trustBadges = document.querySelectorAll('.trust-badge');
        trustBadges.forEach((badge) => {
            badge.addEventListener('click', function() {
                const label = this.textContent.trim();
                console.log('🏷️ Trust badge clicked:', label);
                this.style.borderColor = 'var(--color-lime)';
                this.style.background = 'rgba(192, 227, 74, 0.06)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.background = '';
                }, 600);
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const shBadge = document.querySelector('.services-hero__badge');
        const shTitle = document.querySelector('.services-hero__title');
        const shSubtitle = document.querySelector('.services-hero__subtitle');
        const shActions = document.querySelector('.services-hero__actions');
        const shTrust = document.querySelector('.services-hero__trust');
        const shHighlights = document.querySelector('.services-hero__highlights');
        const shVisual = document.querySelector('.services-hero__visual');

        // Set initial state for header elements
        const headerElementsSH = [shBadge, shTitle, shSubtitle, shActions];
        headerElementsSH.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for trust badges
        trustBadges.forEach((badge, index) => {
            badge.style.opacity = '0';
            badge.style.transform = 'translateY(15px)';
            badge.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 40)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 40)}ms`;
        });

        // Set initial state for highlight cards
        const highlightCards = document.querySelectorAll('.highlight-card');
        highlightCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(15px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms`;
        });

        if (shVisual) {
            shVisual.style.opacity = '0';
            shVisual.style.transform = 'scale(0.96)';
            shVisual.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // ----- Observer -----
        const shObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElementsSH.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100 + (index * 60));
                        }
                    });

                    // Animate trust badges
                    trustBadges.forEach((badge, index) => {
                        setTimeout(() => {
                            badge.style.opacity = '1';
                            badge.style.transform = 'translateY(0)';
                        }, 200 + (index * 40));
                    });

                    // Animate highlight cards
                    highlightCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 30));
                    });

                    // Animate visual
                    if (shVisual) {
                        setTimeout(() => {
                            shVisual.style.opacity = '1';
                            shVisual.style.transform = 'scale(1)';
                        }, 400);
                    }

                    shObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const shSection = document.getElementById('services-hero');
        if (shSection) {
            shObserver.observe(shSection);
        }

        console.log('🚀 Services Hero initialized.');
    };

    // Initialize Services Hero
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initServicesHero);
    } else {
        initServicesHero();
    }

