    // ============================================================
    // 81. DELIVERY PROCESS — ACCORDION, INTERACTIONS & ANIMATIONS
    // ============================================================
    const initDeliveryProcess = () => {
        // ----- Phase Detail Accordion -----
        const detailTriggers = document.querySelectorAll('.phase-detail-card__trigger');

        detailTriggers.forEach((trigger) => {
            trigger.addEventListener('click', function() {
                const isExpanded = this.getAttribute('aria-expanded') === 'true';
                this.setAttribute('aria-expanded', !isExpanded);
            });
        });

        // ----- Timeline Phase Click (scroll to detail) -----
        const timelinePhases = document.querySelectorAll('.timeline-phase');

        timelinePhases.forEach((phase, index) => {
            phase.addEventListener('click', function() {
                const phaseNum = parseInt(this.dataset.phase, 10);
                const detailCards = document.querySelectorAll('.phase-detail-card');

                // Find the corresponding detail card (phase 1 = index 0)
                const targetCard = detailCards[phaseNum - 1];
                if (targetCard) {
                    const trigger = targetCard.querySelector('.phase-detail-card__trigger');
                    if (trigger && trigger.getAttribute('aria-expanded') === 'false') {
                        trigger.click();
                    }
                    targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    // Highlight effect
                    targetCard.style.borderColor = 'var(--color-lime)';
                    targetCard.style.boxShadow = '0 0 0 4px rgba(192,227,74,0.1)';
                    setTimeout(() => {
                        targetCard.style.borderColor = '';
                        targetCard.style.boxShadow = '';
                    }, 2000);
                }
                console.log('📌 Phase clicked:', phaseNum);
            });
        });

        // ----- CTA Buttons -----
        const processStartBtn = document.querySelector('.btn-cta-process-start');
        const processDiscoveryBtn = document.querySelector('.btn-cta-process-discovery');

        if (processStartBtn) {
            processStartBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('🚀 Start Your Project from Process CTA');
            });
        }

        if (processDiscoveryBtn) {
            processDiscoveryBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📅 Schedule a Discovery Call from Process CTA');
            });
        }

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const dpBadge = document.querySelector('.delivery-process__badge');
        const dpTitle = document.querySelector('.delivery-process__title');
        const dpSubtitle = document.querySelector('.delivery-process__subtitle');
        const dpTimeline = document.querySelector('.delivery-process__timeline');
        const dpDetails = document.querySelector('.delivery-process__details');
        const dpManagement = document.querySelector('.delivery-process__management');
        const dpQa = document.querySelector('.delivery-process__qa');
        const dpMetrics = document.querySelector('.delivery-process__metrics');
        const dpCta = document.querySelector('.delivery-process__cta');

        // Set initial state for header elements
        const headerElementsDP = [dpBadge, dpTitle, dpSubtitle];
        headerElementsDP.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        const sectionsDP = [dpTimeline, dpDetails, dpManagement, dpQa, dpMetrics, dpCta];
        sectionsDP.forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for timeline phases
        const timelinePhaseItems = document.querySelectorAll('.timeline-phase');
        timelinePhaseItems.forEach((phase, index) => {
            phase.style.opacity = '0';
            phase.style.transform = 'translateY(15px)';
            phase.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms`;
        });

        // Set initial state for phase detail cards
        const phaseDetailItems = document.querySelectorAll('.phase-detail-card');
        phaseDetailItems.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(15px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 25)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 25)}ms`;
        });

        // Set initial state for management cards
        const mgmtCards = document.querySelectorAll('.management-card');
        mgmtCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(12px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 20)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 20)}ms`;
        });

        // Set initial state for QA steps
        const qaSteps = document.querySelectorAll('.qa-step');
        qaSteps.forEach((step, index) => {
            step.style.opacity = '0';
            step.style.transform = 'translateY(12px)';
            step.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${260 + (index * 20)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${260 + (index * 20)}ms`;
        });

        // ----- Counter Animation -----
        const animateCount = (element, target, duration = 2000) => {
            const startTime = performance.now();
            const startValue = 0;

            const updateCount = (currentTime) => {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3);
                const currentValue = Math.floor(eased * target);
                element.textContent = currentValue;

                if (progress < 1) {
                    requestAnimationFrame(updateCount);
                } else {
                    element.textContent = target;
                }
            };

            requestAnimationFrame(updateCount);
        };

        let statsAnimatedDP = false;
        const statNumbersDP = document.querySelectorAll('.delivery-process__metrics .stat-number');

        // ----- Observer -----
        const dpObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElementsDP.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    // Animate sections
                    sectionsDP.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    // Animate timeline phases
                    timelinePhaseItems.forEach((phase, index) => {
                        setTimeout(() => {
                            phase.style.opacity = '1';
                            phase.style.transform = 'translateY(0)';
                        }, 300 + (index * 30));
                    });

                    // Animate phase detail cards
                    phaseDetailItems.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 320 + (index * 25));
                    });

                    // Animate management cards
                    mgmtCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 340 + (index * 20));
                    });

                    // Animate QA steps
                    qaSteps.forEach((step, index) => {
                        setTimeout(() => {
                            step.style.opacity = '1';
                            step.style.transform = 'translateY(0)';
                        }, 360 + (index * 20));
                    });

                    // Animate stat counters
                    if (!statsAnimatedDP) {
                        statsAnimatedDP = true;
                        statNumbersDP.forEach((statEl) => {
                            const target = parseInt(statEl.getAttribute('data-count'), 10);
                            if (isNaN(target)) return;
                            statEl.textContent = '0';
                            animateCount(statEl, target);
                        });
                    }

                    dpObserver.disconnect();
                }
            });
        }, {
            threshold: 0.05,
            rootMargin: '0px 0px -50px 0px'
        });

        const dpSection = document.getElementById('delivery-process');
        if (dpSection) {
            dpObserver.observe(dpSection);
        }

        console.log('📋 Development Process & Delivery Methodology initialized.');
    };

    // Initialize Delivery Process
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDeliveryProcess);
    } else {
        initDeliveryProcess();
    }

/* ==================================================
END: Our Development Process & Delivery Methodology JavaScript
================================================== */

