        // ============================================================
        const wcBadge = document.querySelector('.why-choose-xohub__badge');
        const wcTitle = document.querySelector('.why-choose-xohub__title');
        const wcSubtitle = document.querySelector('.why-choose-xohub__subtitle');
        const wcBanner = document.querySelector('.trust-banner-advantage');
        const wcAdvantages = document.querySelector('.why-choose-xohub__advantages');
        const wcComparison = document.querySelector('.why-choose-xohub__comparison');
