                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
