        const psSubtitle = document.querySelector('.privacy-sharing__subtitle');
        const psBanner = document.querySelector('.sharing-banner');
        const psCategories = document.querySelector('.privacy-sharing__categories');
        const psFlow = document.querySelector('.privacy-sharing__flow');
        const psTrust = document.querySelector('.privacy-sharing__trust');
        const psInfo = document.querySelector('.info-banner-sharing');

        // Set initial state for header elements
