        const tfTitle = document.querySelector('.terms-final__title');
        const tfSubtitle = document.querySelector('.terms-final__subtitle');
        const tfBanner = document.querySelector('.final-banner');
        const tfLegal = document.querySelector('.terms-final__legal');
        const tfLifecycle = document.querySelector('.terms-final__lifecycle');
        const tfContact = document.querySelector('.terms-final__contact');
        const tfNotice = document.querySelector('.notice-final');
