        const cpBadge = document.querySelector('.cookie-preferences__badge');
        const cpTitle = document.querySelector('.cookie-preferences__title');
        const cpSubtitle = document.querySelector('.cookie-preferences__subtitle');
        const cpBanner = document.querySelector('.pref-banner');
        const cpOptions = document.querySelector('.cookie-preferences__options');
        const cpFlow = document.querySelector('.cookie-preferences__flow');
        const cpBrowsers = document.querySelector('.cookie-preferences__browsers');
