    // ============================================================
    // 118. COOKIE CONSENT BANNER — GLOBAL COMPONENT
    // ============================================================
    const initCookieBanner = () => {
        // ----- DOM References -----
        const banner = document.getElementById('cookie-banner');
        const acceptBtn = document.getElementById('cookie-accept-btn');
        const rejectBtn = document.getElementById('cookie-reject-btn');
        const customizeBtn = document.getElementById('cookie-customize-btn');
        const overlay = document.querySelector('.cookie-banner__overlay');

        // ----- Storage Keys -----
        const CONSENT_KEY = 'cookieConsent';
        const PREFERENCES_KEY = 'cookiePreferences';

        // ----- Consent States -----
        const CONSENT_STATES = {
            ACCEPTED: 'accepted',
            REJECTED: 'rejected',
            CUSTOMIZED: 'customized'
        };

        // ----- Default Preferences -----
        const DEFAULT_PREFERENCES = {
            essential: true,
            functional: false,
            performance: false,
            analytics: false,
            marketing: false
        };

        // ----- Check Existing Consent -----
        const getStoredConsent = () => {
            try {
                const consent = localStorage.getItem(CONSENT_KEY);
                return consent || null;
            } catch (e) {
                return null;
            }
        };

        const getStoredPreferences = () => {
            try {
                const prefs = localStorage.getItem(PREFERENCES_KEY);
                return prefs ? JSON.parse(prefs) : null;
            } catch (e) {
                return null;
            }
        };

        // ----- Save Consent -----
        const saveConsent = (state, preferences = null) => {
            try {
                localStorage.setItem(CONSENT_KEY, state);
                if (preferences) {
                    localStorage.setItem(PREFERENCES_KEY, JSON.stringify(preferences));
                }
                console.log('🍪 Cookie consent saved:', state, preferences);
            } catch (e) {
                console.warn('Could not save consent to localStorage:', e);
            }
        };

        // ----- Apply Consent (placeholder for future implementation) -----
        const applyConsent = (state, preferences) => {
            console.log('🍪 Applying cookie consent:', state, preferences);
            // Future: Enable/disable analytics, marketing scripts here
            // For now, we just store the preference
        };

        // ----- Hide Banner -----
        const hideBanner = () => {
            banner.classList.add('cookie-banner--hidden');
            if (overlay) {
                overlay.classList.remove('cookie-banner__overlay--visible');
            }
            setTimeout(() => {
                banner.style.display = 'none';
            }, 400);
        };

        // ----- Handle Accept All -----
        const handleAccept = () => {
            const preferences = {
                essential: true,
                functional: true,
                performance: true,
                analytics: true,
                marketing: true
            };
            saveConsent(CONSENT_STATES.ACCEPTED, preferences);
            applyConsent(CONSENT_STATES.ACCEPTED, preferences);
            hideBanner();
            console.log('🍪 All cookies accepted');
        };

        // ----- Handle Reject Optional -----
        const handleReject = () => {
            const preferences = {
                essential: true,
                functional: false,
                performance: false,
                analytics: false,
                marketing: false
            };
            saveConsent(CONSENT_STATES.REJECTED, preferences);
            applyConsent(CONSENT_STATES.REJECTED, preferences);
            hideBanner();
            console.log('🍪 Optional cookies rejected');
        };

        // ----- Handle Customize (Open Modal Placeholder) -----
        const handleCustomize = () => {
            console.log('🍪 Customize preferences clicked');
            // Future: Open Cookie Preferences Modal
            // For now, we can show a simple alert or trigger the modal
            // This will be implemented in the next phase
            alert('Cookie Preferences modal will open here.\nManage your preferences for different cookie categories.');
            // Placeholder for modal integration:
            // const modal = document.getElementById('cookie-modal');
            // if (modal) modal.style.display = 'flex';
        };

        // ----- Show Banner -----
        const showBanner = () => {
            banner.style.display = 'flex';
            // Small delay to ensure display:flex is applied before animation
            requestAnimationFrame(() => {
                banner.classList.remove('cookie-banner--hidden');
                if (overlay) {
                    overlay.classList.add('cookie-banner__overlay--visible');
                }
            });
        };

        // ----- Check if Banner Should Show -----
        const checkAndShowBanner = () => {
            const consent = getStoredConsent();
            if (consent) {
                console.log('🍪 Consent already given:', consent);
                // Still apply any stored preferences
                const prefs = getStoredPreferences();
                if (prefs) {
                    applyConsent(consent, prefs);
                }
                return;
            }

            console.log('🍪 No consent found — showing banner');
            // Small delay to allow page to render
            setTimeout(() => {
                showBanner();
            }, 500);
        };

        // ----- Keyboard Support -----
        const handleKeydown = (e) => {
            if (e.key === 'Escape') {
                // Focus management: move focus to reject button
                rejectBtn.focus();
            }
        };

        // ----- Focus Management -----
        const focusFirstButton = () => {
            // Focus on the most prominent action (Accept All)
            setTimeout(() => {
                acceptBtn.focus();
            }, 100);
        };

        // ----- Event Listeners -----
        if (acceptBtn) {
            acceptBtn.addEventListener('click', handleAccept);
            // Ripple effect on click
            acceptBtn.addEventListener('click', function(e) {
                const rect = this.getBoundingClientRect();
                const ripple = this.querySelector('.btn-ripple') || document.createElement('span');
                if (!this.querySelector('.btn-ripple')) {
                    ripple.className = 'btn-ripple';
                    this.appendChild(ripple);
                }
                const size = Math.max(rect.width, rect.height);
                ripple.style.width = ripple.style.height = size + 'px';
                const x = e.clientX - rect.left - size / 2;
                const y = e.clientY - rect.top - size / 2;
                ripple.style.left = x + 'px';
                ripple.style.top = y + 'px';
                ripple.style.transform = 'scale(1)';
                setTimeout(() => {
                    ripple.style.transform = 'scale(4)';
                    ripple.style.opacity = '0';
                }, 10);
                setTimeout(() => {
                    ripple.style.transform = 'scale(0)';
                }, 600);
            });
        }

        if (rejectBtn) {
            rejectBtn.addEventListener('click', handleReject);
        }

        if (customizeBtn) {
            customizeBtn.addEventListener('click', handleCustomize);
        }

        // ----- Keyboard navigation for buttons -----
        banner.addEventListener('keydown', handleKeydown);

        // ----- Focus trap inside banner -----
        const focusableElements = () => {
            return banner.querySelectorAll('button, a[href]');
        };

        banner.addEventListener('keydown', (e) => {
            if (e.key !== 'Tab') return;
            const focusable = focusableElements();
            if (focusable.length === 0) return;

            const first = focusable[0];
            const last = focusable[focusable.length - 1];

            if (e.shiftKey && document.activeElement === first) {
                e.preventDefault();
                last.focus();
            } else if (!e.shiftKey && document.activeElement === last) {
                e.preventDefault();
                first.focus();
            }
        });

        // ----- ARIA Live Announcement -----
        const announce = (message) => {
            const announcer = document.getElementById('cookie-announcer') || (() => {
                const el = document.createElement('div');
                el.id = 'cookie-announcer';
                el.setAttribute('aria-live', 'polite');
                el.setAttribute('aria-atomic', 'true');
                el.style.position = 'absolute';
                el.style.width = '1px';
                el.style.height = '1px';
                el.style.padding = '0';
                el.style.margin = '-1px';
                el.style.overflow = 'hidden';
                el.style.clip = 'rect(0,0,0,0)';
                el.style.border = '0';
                document.body.appendChild(el);
                return el;
            })();
            announcer.textContent = message;
        };

        // ----- Init -----
        const init = () => {
            checkAndShowBanner();
            console.log('🍪 Cookie Consent Banner initialized.');
        };

        // ----- Expose for global use (Laravel integration) -----
        window.cookieBanner = {
            show: showBanner,
            hide: hideBanner,
            accept: handleAccept,
            reject: handleReject,
            customize: handleCustomize,
            getConsent: getStoredConsent,
            getPreferences: getStoredPreferences,
            reset: () => {
                localStorage.removeItem(CONSENT_KEY);
                localStorage.removeItem(PREFERENCES_KEY);
                showBanner();
                console.log('🍪 Cookie consent reset');
            }
        };

        // ----- Initialize -----
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    };

    // Initialize Cookie Consent Banner
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCookieBanner);
    } else {
        initCookieBanner();
    }

/* ==================================================
END: Global Cookie Consent Banner JavaScript
================================================== */

