    // ============================================================
    // 119. COOKIE PREFERENCES MODAL — GLOBAL COMPONENT
    // ============================================================
    const initCookieModal = () => {
        // ----- DOM References -----
        const modal = document.getElementById('cookie-modal');
        const backdrop = document.getElementById('cookie-modal-backdrop');
        const closeBtn = document.getElementById('cookie-modal-close');
        const acceptBtn = document.getElementById('cookie-modal-accept');
        const saveBtn = document.getElementById('cookie-save-btn');
        const rejectBtn = document.getElementById('cookie-modal-reject');
        const resetBtn = document.getElementById('cookie-reset-btn');

        const essentialToggle = document.getElementById('cookie-essential');
        const functionalToggle = document.getElementById('cookie-functional');
        const performanceToggle = document.getElementById('cookie-performance');
        const analyticsToggle = document.getElementById('cookie-analytics');
        const marketingToggle = document.getElementById('cookie-marketing');
        const futureToggle = document.getElementById('cookie-future');

        const allToggles = [functionalToggle, performanceToggle, analyticsToggle, marketingToggle, futureToggle];
        const allTogglesWithEssential = [essentialToggle, ...allToggles];

        // ----- Storage Keys -----
        const CONSENT_KEY = 'cookieConsent';
        const PREFERENCES_KEY = 'cookiePreferences';

        // ----- Consent States -----
        const CONSENT_STATES = {
            ACCEPTED: 'accepted',
            REJECTED: 'rejected',
            CUSTOMIZED: 'customized'
        };

        // ----- Default Preferences -----
        const DEFAULT_PREFERENCES = {
            essential: true,
            functional: false,
            performance: false,
            analytics: false,
            marketing: false,
            future: false
        };

        // ----- Modal State -----
        let isOpen = false;
        let currentPreferences = { ...DEFAULT_PREFERENCES };

        // ----- Load Saved Preferences -----
        const loadPreferences = () => {
            try {
                const stored = localStorage.getItem(PREFERENCES_KEY);
                if (stored) {
                    const prefs = JSON.parse(stored);
                    // Merge with defaults to handle missing keys
                    currentPreferences = { ...DEFAULT_PREFERENCES, ...prefs };
                    return currentPreferences;
                }
            } catch (e) {
                console.warn('Could not load preferences:', e);
            }
            currentPreferences = { ...DEFAULT_PREFERENCES };
            return currentPreferences;
        };

        // ----- Save Preferences -----
        const savePreferences = (prefs, consentState = CONSENT_STATES.CUSTOMIZED) => {
            try {
                localStorage.setItem(PREFERENCES_KEY, JSON.stringify(prefs));
                localStorage.setItem(CONSENT_KEY, consentState);
                console.log('🍪 Preferences saved:', prefs, consentState);
            } catch (e) {
                console.warn('Could not save preferences:', e);
            }
        };

        // ----- Apply Preferences to UI -----
        const applyPreferencesToUI = (prefs) => {
            functionalToggle.checked = prefs.functional || false;
            performanceToggle.checked = prefs.performance || false;
            analyticsToggle.checked = prefs.analytics || false;
            marketingToggle.checked = prefs.marketing || false;
            futureToggle.checked = prefs.future || false;
            // Essential is always checked and disabled
        };

        // ----- Get Current Preferences from UI -----
        const getPreferencesFromUI = () => ({
            essential: true,
            functional: functionalToggle.checked,
            performance: performanceToggle.checked,
            analytics: analyticsToggle.checked,
            marketing: marketingToggle.checked,
            future: futureToggle.checked
        });

        // ----- Apply Consent (future implementation) -----
        const applyConsent = (prefs) => {
            console.log('🍪 Applying cookie consent:', prefs);
            // Future: Enable/disable scripts based on preferences
            // For now, just log the action
            const consentState = localStorage.getItem(CONSENT_KEY) || CONSENT_STATES.CUSTOMIZED;
            console.log('🍪 Consent state:', consentState);
        };

        // ----- Open Modal -----
        const openModal = () => {
            if (isOpen) return;
            isOpen = true;

            // Load and apply preferences
            const prefs = loadPreferences();
            applyPreferencesToUI(prefs);

            // Show modal
            modal.style.display = 'flex';
            // Trigger animation
            requestAnimationFrame(() => {
                modal.classList.add('cookie-modal--open');
                modal.classList.remove('cookie-modal--closing');
            });

            // Prevent body scroll
            document.body.style.overflow = 'hidden';

            // Focus management - move focus to first toggle
            setTimeout(() => {
                const firstToggle = document.querySelector('.cookie-control:not(.cookie-control--essential) .toggle-input');
                if (firstToggle) {
                    firstToggle.focus();
                } else {
                    closeBtn.focus();
                }
            }, 150);

            console.log('🍪 Cookie Preferences Modal opened');
        };

        // ----- Close Modal -----
        const closeModal = () => {
            if (!isOpen) return;
            isOpen = false;

            modal.classList.remove('cookie-modal--open');
            modal.classList.add('cookie-modal--closing');

            setTimeout(() => {
                modal.style.display = 'none';
                modal.classList.remove('cookie-modal--closing');
                document.body.style.overflow = '';
                // Focus return to banner
                const banner = document.getElementById('cookie-banner');
                if (banner && banner.style.display !== 'none') {
                    const customizeBtn = document.getElementById('cookie-customize-btn');
                    if (customizeBtn) customizeBtn.focus();
                }
            }, 300);

            console.log('🍪 Cookie Preferences Modal closed');
        };

        // ----- Handle Accept All -----
        const handleAcceptAll = () => {
            const prefs = {
                essential: true,
                functional: true,
                performance: true,
                analytics: true,
                marketing: true,
                future: true
            };
            currentPreferences = prefs;
            applyPreferencesToUI(prefs);
            savePreferences(prefs, CONSENT_STATES.ACCEPTED);
            applyConsent(prefs);
            closeModal();

            // Hide banner if visible
            const banner = document.getElementById('cookie-banner');
            if (banner && banner.style.display !== 'none') {
                banner.classList.add('cookie-banner--hidden');
                setTimeout(() => {
                    banner.style.display = 'none';
                }, 400);
            }

            console.log('🍪 All cookies accepted via modal');
        };

        // ----- Handle Save Preferences -----
        const handleSave = () => {
            const prefs = getPreferencesFromUI();
            currentPreferences = prefs;
            savePreferences(prefs, CONSENT_STATES.CUSTOMIZED);
            applyConsent(prefs);
            closeModal();

            // Hide banner if visible
            const banner = document.getElementById('cookie-banner');
            if (banner && banner.style.display !== 'none') {
                banner.classList.add('cookie-banner--hidden');
                setTimeout(() => {
                    banner.style.display = 'none';
                }, 400);
            }

            console.log('🍪 Preferences saved via modal');
        };

        // ----- Handle Reject Optional -----
        const handleRejectOptional = () => {
            const prefs = {
                essential: true,
                functional: false,
                performance: false,
                analytics: false,
                marketing: false,
                future: false
            };
            currentPreferences = prefs;
            applyPreferencesToUI(prefs);
            savePreferences(prefs, CONSENT_STATES.REJECTED);
            applyConsent(prefs);
            closeModal();

            const banner = document.getElementById('cookie-banner');
            if (banner && banner.style.display !== 'none') {
                banner.classList.add('cookie-banner--hidden');
                setTimeout(() => {
                    banner.style.display = 'none';
                }, 400);
            }

            console.log('🍪 Optional cookies rejected via modal');
        };

        // ----- Handle Reset Choices -----
        const handleReset = () => {
            const prefs = { ...DEFAULT_PREFERENCES };
            currentPreferences = prefs;
            applyPreferencesToUI(prefs);
            savePreferences(prefs, CONSENT_STATES.CUSTOMIZED);
            applyConsent(prefs);

            console.log('🍪 Preferences reset to defaults');
            // Announce to screen readers
            announce('Cookie preferences have been reset to default settings.');
        };

        // ----- ARIA Announcement -----
        const announce = (message) => {
            const announcer = document.getElementById('cookie-modal-announcer') || (() => {
                const el = document.createElement('div');
                el.id = 'cookie-modal-announcer';
                el.setAttribute('aria-live', 'polite');
                el.setAttribute('aria-atomic', 'true');
                el.style.position = 'absolute';
                el.style.width = '1px';
                el.style.height = '1px';
                el.style.padding = '0';
                el.style.margin = '-1px';
                el.style.overflow = 'hidden';
                el.style.clip = 'rect(0,0,0,0)';
                el.style.border = '0';
                document.body.appendChild(el);
                return el;
            })();
            announcer.textContent = message;
        };

        // ----- Event Listeners -----
        // Close button
        if (closeBtn) {
            closeBtn.addEventListener('click', closeModal);
        }

        // Backdrop click
        if (backdrop) {
            backdrop.addEventListener('click', closeModal);
        }

        // Accept All
        if (acceptBtn) {
            acceptBtn.addEventListener('click', handleAcceptAll);
            // Ripple effect
            acceptBtn.addEventListener('click', function(e) {
                const rect = this.getBoundingClientRect();
                const ripple = this.querySelector('.btn-ripple') || document.createElement('span');
                if (!this.querySelector('.btn-ripple')) {
                    ripple.className = 'btn-ripple';
                    this.appendChild(ripple);
                }
                const size = Math.max(rect.width, rect.height);
                ripple.style.width = ripple.style.height = size + 'px';
                const x = e.clientX - rect.left - size / 2;
                const y = e.clientY - rect.top - size / 2;
                ripple.style.left = x + 'px';
                ripple.style.top = y + 'px';
                ripple.style.transform = 'scale(1)';
                setTimeout(() => {
                    ripple.style.transform = 'scale(4)';
                    ripple.style.opacity = '0';
                }, 10);
                setTimeout(() => {
                    ripple.style.transform = 'scale(0)';
                }, 600);
            });
        }

        // Save Preferences
        if (saveBtn) {
            saveBtn.addEventListener('click', handleSave);
        }

        // Reject Optional
        if (rejectBtn) {
            rejectBtn.addEventListener('click', handleRejectOptional);
        }

        // Reset Choices
        if (resetBtn) {
            resetBtn.addEventListener('click', handleReset);
        }

        // ----- Keyboard Support -----
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && isOpen) {
                closeModal();
            }
        });

        // ----- Focus Trap -----
        const getFocusableElements = () => {
            if (!modal) return [];
            return modal.querySelectorAll(
                'button, input, a[href], [tabindex]:not([tabindex="-1"])'
            );
        };

        modal.addEventListener('keydown', (e) => {
            if (e.key !== 'Tab') return;
            const focusable = getFocusableElements();
            if (focusable.length === 0) return;

            const first = focusable[0];
            const last = focusable[focusable.length - 1];

            if (e.shiftKey && document.activeElement === first) {
                e.preventDefault();
                last.focus();
            } else if (!e.shiftKey && document.activeElement === last) {
                e.preventDefault();
                first.focus();
            }
        });

        // ----- Expose for global use (Laravel integration) -----
        window.cookieModal = {
            open: openModal,
            close: closeModal,
            toggle: () => isOpen ? closeModal() : openModal(),
            acceptAll: handleAcceptAll,
            save: handleSave,
            reject: handleRejectOptional,
            reset: handleReset,
            isOpen: () => isOpen,
            getPreferences: loadPreferences,
            setPreferences: (prefs) => {
                currentPreferences = { ...DEFAULT_PREFERENCES, ...prefs };
                applyPreferencesToUI(currentPreferences);
                savePreferences(currentPreferences, CONSENT_STATES.CUSTOMIZED);
                applyConsent(currentPreferences);
            }
        };

        // ----- Connect to Cookie Banner -----
        // Expose the open function so the banner can call it
        const customizeBtn = document.getElementById('cookie-customize-btn');
        if (customizeBtn) {
            // The banner's customize button will call window.cookieModal.open()
            // But we also need to handle the existing click listener
            // Override or supplement: we'll add a new listener that calls our open
            customizeBtn.addEventListener('click', function(e) {
                // Prevent the default behavior from the banner if any
                e.preventDefault();
                e.stopPropagation();
                openModal();
            });
        }

        // ----- Load preferences on init -----
        loadPreferences();

        console.log('🍪 Cookie Preferences Modal initialized.');
    };

    // Initialize Cookie Modal
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCookieModal);
    } else {
        initCookieModal();
    }

