    // ============================================================
    // 120. FULL CONSENT MANAGER — GLOBAL COOKIE CONSENT SYSTEM
    // ============================================================
    const initFullConsentManager = () => {
        // ----- Constants -----
        const CONSENT_KEY = 'cookieConsent';
        const PREFERENCES_KEY = 'cookiePreferences';
        const VERSION_KEY = 'cookieConsentVersion';
        const TIMESTAMP_KEY = 'cookieConsentTimestamp';

        const CONSENT_VERSION = '1.0';

        const CONSENT_STATES = {
            ACCEPTED: 'accepted',
            REJECTED: 'rejected',
            CUSTOMIZED: 'customized',
            NONE: null
        };

        const DEFAULT_PREFERENCES = {
            essential: true,
            functional: false,
            performance: false,
            analytics: false,
            marketing: false,
            future: false
        };

        // ----- State -----
        let currentConsent = null;
        let currentPreferences = { ...DEFAULT_PREFERENCES };
        let isInitialized = false;

        // ----- DOM References (Lazy-loaded) -----
        const getBanner = () => document.getElementById('cookie-banner');
        const getModal = () => document.getElementById('cookie-modal');
        const getSettingsBtn = () => document.getElementById('cookie-settings-btn');
        const getSettingsDot = () => document.getElementById('cookie-settings-dot');

        // ----- Storage Helpers -----
        const storage = {
            get: (key, fallback = null) => {
                try {
                    const value = localStorage.getItem(key);
                    return value ? JSON.parse(value) : fallback;
                } catch {
                    return fallback;
                }
            },
            set: (key, value) => {
                try {
                    localStorage.setItem(key, JSON.stringify(value));
                    return true;
                } catch {
                    return false;
                }
            },
            remove: (key) => {
                try {
                    localStorage.removeItem(key);
                    return true;
                } catch {
                    return false;
                }
            }
        };

        // ----- Load Consent -----
        const loadConsent = () => {
            const consent = storage.get(CONSENT_KEY);
            const prefs = storage.get(PREFERENCES_KEY);
            const version = storage.get(VERSION_KEY);
            const timestamp = storage.get(TIMESTAMP_KEY);

            currentConsent = consent || CONSENT_STATES.NONE;
            currentPreferences = prefs ? { ...DEFAULT_PREFERENCES, ...prefs } : { ...DEFAULT_PREFERENCES };

            return {
                consent: currentConsent,
                preferences: currentPreferences,
                version: version || CONSENT_VERSION,
                timestamp: timestamp || null
            };
        };

        // ----- Save Consent -----
        const saveConsent = (state, preferences = null) => {
            const prefsToSave = preferences || currentPreferences;
            currentConsent = state;
            currentPreferences = { ...prefsToSave };

            storage.set(CONSENT_KEY, state);
            storage.set(PREFERENCES_KEY, prefsToSave);
            storage.set(VERSION_KEY, CONSENT_VERSION);
            storage.set(TIMESTAMP_KEY, new Date().toISOString());

            // Update UI components
            updateFloatingButton();
            syncBanner();
            syncModal();

            // Dispatch events
            dispatchConsentEvent(state, prefsToSave);

            console.log('🍪 Consent saved:', { state, preferences: prefsToSave });
            return true;
        };

        // ----- Dispatch Custom Events -----
        const dispatchConsentEvent = (state, preferences) => {
            const eventData = {
                consent: state,
                preferences: preferences,
                timestamp: new Date().toISOString(),
                version: CONSENT_VERSION
            };

            // Dispatch different events based on state
            let eventName;
            switch (state) {
                case CONSENT_STATES.ACCEPTED:
                    eventName = 'cookieConsentAccepted';
                    break;
                case CONSENT_STATES.REJECTED:
                    eventName = 'cookieConsentRejected';
                    break;
                case CONSENT_STATES.CUSTOMIZED:
                    eventName = 'cookiePreferencesUpdated';
                    break;
                default:
                    eventName = 'cookieConsentReset';
            }

            const event = new CustomEvent(eventName, { detail: eventData });
            document.dispatchEvent(event);

            // Also dispatch a generic consent update event
            document.dispatchEvent(new CustomEvent('cookieConsentUpdated', { detail: eventData }));

            console.log(`🍪 Event dispatched: ${eventName}`, eventData);
        };

        // ----- Update Floating Button -----
        const updateFloatingButton = () => {
            const dot = getSettingsDot();
            if (!dot) return;

            const hasConsent = currentConsent !== CONSENT_STATES.NONE;
            dot.classList.toggle('cookie-settings-btn__dot--hidden', hasConsent);
        };

        // ----- Sync Banner -----
        const syncBanner = () => {
            const banner = getBanner();
            if (!banner) return;

            const hasConsent = currentConsent !== CONSENT_STATES.NONE;
            if (hasConsent) {
                // Hide banner if consent is given
                banner.style.display = 'none';
                banner.classList.remove('cookie-banner--hidden');
            } else {
                // Show banner if no consent
                banner.style.display = 'flex';
                banner.classList.remove('cookie-banner--hidden');
            }
        };

        // ----- Sync Modal -----
        const syncModal = () => {
            const modal = getModal();
            if (!modal) return;

            // Only update modal if it's not currently open
            if (modal.style.display !== 'flex') {
                // Modal will load preferences when opened
                return;
            }

            // If modal is open, we need to update the toggles
            const prefs = currentPreferences;
            const toggles = {
                functional: document.getElementById('cookie-functional'),
                performance: document.getElementById('cookie-performance'),
                analytics: document.getElementById('cookie-analytics'),
                marketing: document.getElementById('cookie-marketing'),
                future: document.getElementById('cookie-future')
            };

            if (toggles.functional) toggles.functional.checked = prefs.functional || false;
            if (toggles.performance) toggles.performance.checked = prefs.performance || false;
            if (toggles.analytics) toggles.analytics.checked = prefs.analytics || false;
            if (toggles.marketing) toggles.marketing.checked = prefs.marketing || false;
            if (toggles.future) toggles.future.checked = prefs.future || false;
        };

        // ----- Reset Consent -----
        const resetConsent = () => {
            storage.remove(CONSENT_KEY);
            storage.remove(PREFERENCES_KEY);
            storage.remove(VERSION_KEY);
            storage.remove(TIMESTAMP_KEY);

            currentConsent = CONSENT_STATES.NONE;
            currentPreferences = { ...DEFAULT_PREFERENCES };

            updateFloatingButton();
            syncBanner();
            syncModal();

            dispatchConsentEvent('reset', currentPreferences);

            console.log('🍪 Consent reset to defaults');
            return true;
        };

        // ----- Accept All -----
        const acceptAll = () => {
            const allEnabled = {
                essential: true,
                functional: true,
                performance: true,
                analytics: true,
                marketing: true,
                future: true
            };
            return saveConsent(CONSENT_STATES.ACCEPTED, allEnabled);
        };

        // ----- Reject Optional -----
        const rejectOptional = () => {
            const essentialOnly = {
                essential: true,
                functional: false,
                performance: false,
                analytics: false,
                marketing: false,
                future: false
            };
            return saveConsent(CONSENT_STATES.REJECTED, essentialOnly);
        };

        // ----- Save Custom Preferences -----
        const saveCustomPreferences = (preferences) => {
            const prefs = { ...DEFAULT_PREFERENCES, ...preferences };
            return saveConsent(CONSENT_STATES.CUSTOMIZED, prefs);
        };

        // ----- Get Current Preferences -----
        const getPreferences = () => ({ ...currentPreferences });

        // ----- Get Current Consent -----
        const getConsent = () => currentConsent;

        // ----- Is Consent Given? -----
        const hasConsent = () => currentConsent !== CONSENT_STATES.NONE;

        // ----- Check if Category is Enabled -----
        const isCategoryEnabled = (category) => {
            return currentPreferences[category] || false;
        };

        // ----- Open Preferences Modal -----
        const openPreferences = () => {
            // Use the modal's open function if available
            if (window.cookieModal && typeof window.cookieModal.open === 'function') {
                window.cookieModal.open();
                return true;
            }
            // Fallback: try to open modal directly
            const modal = getModal();
            if (modal) {
                // We need to trigger the modal open
                // The modal's open function should be available
                console.warn('🍪 Cookie modal not found, trying fallback');
                return false;
            }
            return false;
        };

        // ----- Initialize Floating Button -----
        const initFloatingButton = () => {
            const btn = getSettingsBtn();
            if (!btn) return;

            // Click handler
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                openPreferences();
            });

            // Keyboard support
            btn.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    openPreferences();
                }
            });

            // ARIA attributes
            btn.setAttribute('role', 'button');
            btn.setAttribute('tabindex', '0');
            btn.setAttribute('aria-label', 'Cookie settings - manage your cookie preferences');

            // Tooltip handling for touch devices
            let tooltipTimer;
            btn.addEventListener('touchstart', () => {
                // Show tooltip briefly on touch
                const tooltip = btn.querySelector('.cookie-settings-btn__tooltip');
                if (tooltip) {
                    tooltip.style.opacity = '1';
                    tooltip.style.transform = 'translateX(-50%) scale(1) translateY(0)';
                    clearTimeout(tooltipTimer);
                    tooltipTimer = setTimeout(() => {
                        tooltip.style.opacity = '0';
                        tooltip.style.transform = 'translateX(-50%) scale(0.92) translateY(4px)';
                    }, 2000);
                }
            });

            // Update initial state
            updateFloatingButton();

            console.log('🍪 Floating settings button initialized');
        };

        // ----- Initialize Full Consent Manager -----
        const initConsentManager = () => {
            if (isInitialized) return;
            isInitialized = true;

            // Load consent
            loadConsent();

            // Initialize UI components
            initFloatingButton();
            syncBanner();
            syncModal();

            // Expose API globally
            window.consentManager = {
                // State
                getConsent,
                getPreferences,
                hasConsent,
                isCategoryEnabled,

                // Actions
                acceptAll,
                rejectOptional,
                saveCustomPreferences,
                resetConsent,
                openPreferences,
                loadConsent,
                saveConsent,

                // Storage
                storage,

                // Events
                on: (event, callback) => {
                    document.addEventListener(event, callback);
                },
                off: (event, callback) => {
                    document.removeEventListener(event, callback);
                },

                // Utility
                getVersion: () => CONSENT_VERSION,
                getTimestamp: () => storage.get(TIMESTAMP_KEY),
                isInitialized: () => isInitialized
            };

            // Dispatch initialized event
            document.dispatchEvent(new CustomEvent('cookieConsentManagerReady', {
                detail: {
                    consent: currentConsent,
                    preferences: currentPreferences,
                    version: CONSENT_VERSION
                }
            }));

            console.log('🍪 Full Consent Manager initialized', {
                consent: currentConsent,
                preferences: currentPreferences,
                version: CONSENT_VERSION
            });
        };

        // ----- Handle Clicks on Floating Button from Banner/Modal -----
        // Also connect the banner's customize button if it exists
        const connectBannerCustomize = () => {
            const customizeBtn = document.getElementById('cookie-customize-btn');
            if (customizeBtn) {
                // Override the banner's customize button to use our manager
                customizeBtn.addEventListener('click', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    openPreferences();
                });
            }
        };

        // ----- Handle Modal Open/Close events -----
        const listenToModalEvents = () => {
            // Listen for modal open to sync preferences
            document.addEventListener('cookieModalOpened', () => {
                syncModal();
            });

            // Listen for modal save to sync consent
            document.addEventListener('cookieModalSaved', (e) => {
                if (e.detail && e.detail.preferences) {
                    saveCustomPreferences(e.detail.preferences);
                }
            });
        };

        // ----- Initialize -----
        const init = () => {
            initConsentManager();
            connectBannerCustomize();
            listenToModalEvents();

            console.log('🍪 Full Consent System ready.');
        };

        // ----- Run initialization -----
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }

        // ----- Expose for Laravel integration -----
        window.XoHubConsent = {
            manager: window.consentManager,
            config: {
                version: CONSENT_VERSION,
                defaultPreferences: DEFAULT_PREFERENCES,
                consentStates: CONSENT_STATES
            },
            // Laravel API integration placeholders
            api: {
                // These will be implemented when Laravel backend is ready
                getConsent: () => Promise.resolve(window.consentManager.getConsent()),
                setConsent: (state, preferences) => {
                    return Promise.resolve(window.consentManager.saveConsent(state, preferences));
                },
                sync: () => {
                    // Future: Sync with server
                    return Promise.resolve({ success: true });
                },
                getUserConsent: () => {
                    // Future: Get consent for authenticated user
                    return Promise.resolve(null);
                },
                setUserConsent: (state, preferences) => {
                    // Future: Set consent for authenticated user
                    return Promise.resolve({ success: true });
                }
            }
        };

        console.log('🍪 XoHubConsent API ready for Laravel integration');
    };

    // Initialize Full Consent Manager
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initFullConsentManager);
    } else {
        initFullConsentManager();
    }

/* ==================================================
END: Global Full Consent Manager JavaScript
================================================== */

