    // ============================================================
    // 121. SITEMAP HERO — INTERACTIONS & ANIMATIONS
    // ============================================================
    const initSitemapHero = () => {
        // ----- Button Interactions -----
        const servicesBtn = document.querySelector('.btn-sitemap-services');
        const contactBtn = document.querySelector('.btn-sitemap-contact');

        if (servicesBtn) {
            servicesBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📋 Explore Services clicked from Sitemap Hero');
            });
        }

        if (contactBtn) {
            contactBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📞 Contact Us clicked from Sitemap Hero');
            });
        }

        // ----- Navigation Badge Click Tracking -----
        const navBadges = document.querySelectorAll('.sitemap-hero__badges .nav-badge');
        navBadges.forEach((badge) => {
            badge.addEventListener('click', function() {
                const label = this.textContent.trim();
                console.log('📍 Navigation badge clicked:', label);
                this.style.borderColor = 'var(--color-lime)';
                this.style.background = 'rgba(192, 227, 74, 0.06)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.background = '';
                }, 600);
            });
        });

        // ----- Structure Tree Node Click Tracking -----
        const treeNodes = document.querySelectorAll('.tree-node');
        treeNodes.forEach((node) => {
            node.addEventListener('click', function() {
                const label = this.querySelector('.node-label')?.textContent || 'Page';
                console.log('🌐 Sitemap node clicked:', label);
                this.style.borderColor = 'var(--color-lime)';
                this.style.background = 'rgba(192, 227, 74, 0.06)';
                this.style.transform = 'translateY(-4px) scale(1.05)';
                setTimeout(() => {
                    this.style.borderColor = '';
                    this.style.background = '';
                    this.style.transform = '';
                }, 600);
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const shBadge = document.querySelector('.sitemap-hero__badge');
        const shTitle = document.querySelector('.sitemap-hero__title');
        const shSubtitle = document.querySelector('.sitemap-hero__subtitle');
        const shMeta = document.querySelector('.sitemap-hero__meta');
        const shActions = document.querySelector('.sitemap-hero__actions');
        const shBadges = document.querySelector('.sitemap-hero__badges');
        const shVisual = document.querySelector('.sitemap-hero__visual');

        // Set initial state for header elements
        const headerElementsSH = [shBadge, shTitle, shSubtitle];
        headerElementsSH.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for meta cards
        const metaCards = document.querySelectorAll('.sitemap-hero__meta .meta-card');
        metaCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(15px)';
            card.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
        });

        // Set initial state for actions and badges
        [shActions, shBadges].forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(15px)';
                el.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${160 + (index * 50)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${160 + (index * 50)}ms`;
            }
        });

        if (shVisual) {
            shVisual.style.opacity = '0';
            shVisual.style.transform = 'scale(0.96)';
            shVisual.style.transition = 'opacity 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        }

        // ----- Observer -----
        const shObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate header elements
                    headerElementsSH.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100 + (index * 60));
                        }
                    });

                    // Animate meta cards
                    metaCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 200 + (index * 60));
                    });

                    // Animate actions and badges
                    [shActions, shBadges].forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 260 + (index * 50));
                        }
                    });

                    // Animate visual
                    if (shVisual) {
                        setTimeout(() => {
                            shVisual.style.opacity = '1';
                            shVisual.style.transform = 'scale(1)';
                        }, 350);
                    }

                    shObserver.disconnect();
                }
            });
        }, {
            threshold: 0.10,
            rootMargin: '0px 0px -50px 0px'
        });

        const shSection = document.getElementById('sitemap-hero');
        if (shSection) {
            shObserver.observe(shSection);
        }

        console.log('🗺️ Sitemap Hero initialized.');
    };

    // Initialize Sitemap Hero
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initSitemapHero);
    } else {
        initSitemapHero();
    }

