    // ============================================================
    // 132. SUPER ADMIN SIGN UP — INTERACTIONS & VALIDATION
    // ============================================================
    const initSuperAdminSignup = () => {
        const form = document.getElementById('superAdminSignupForm');
        if (!form) return;

        // ---- Toggle Password Visibility ----
        const toggleBtns = document.querySelectorAll('.admin-signup__toggle-password');

        toggleBtns.forEach((btn) => {
            btn.addEventListener('click', function(e) {
                e.stopPropagation();
                const targetId = this.getAttribute('data-target');
                const input = document.getElementById(targetId);
                if (!input) return;

                const type = input.getAttribute('type') === 'password' ? 'text' : 'password';
                input.setAttribute('type', type);

                const icon = this.querySelector('i');
                if (icon) {
                    icon.classList.toggle('fa-eye');
                    icon.classList.toggle('fa-eye-slash');
                }

                // Focus stays on the input
                input.focus();
            });
        });

        // ---- Password Strength Meter ----
        const passwordInput = document.getElementById('signup_password');
        const strengthBar = document.querySelector('.admin-signup__password-fill');
        const strengthText = document.getElementById('signupStrengthText');
        const requirements = document.querySelectorAll('#signupRequirements li');
        const reqToggle = document.querySelector('.admin-signup__password-requirements-toggle');

        // Toggle requirements visibility
        if (reqToggle) {
            reqToggle.addEventListener('click', function() {
                const reqList = document.getElementById('signupRequirements');
                if (reqList) {
                    reqList.classList.toggle('open');
                    this.classList.toggle('active');
                }
            });
        }

        const pwRules = {
            length: { regex: /.{12,}/, valid: false },
            uppercase: { regex: /[A-Z]/, valid: false },
            lowercase: { regex: /[a-z]/, valid: false },
            number: { regex: /[0-9]/, valid: false },
            special: { regex: /[^A-Za-z0-9]/, valid: false }
        };

        function checkPwStrength(password) {
            let score = 0;
            const total = Object.keys(pwRules).length;

            // Reset
            Object.keys(pwRules).forEach((key) => pwRules[key].valid = false);

            // Check each rule
            Object.keys(pwRules).forEach((key) => {
                if (pwRules[key].regex.test(password)) {
                    pwRules[key].valid = true;
                    score++;
                }
            });

            // Update requirements UI
            requirements.forEach((li) => {
                const rule = li.getAttribute('data-rule');
                if (pwRules[rule]) {
                    li.classList.remove('valid', 'invalid');
                    li.classList.add(pwRules[rule].valid ? 'valid' : 'invalid');
                    const icon = li.querySelector('i');
                    if (icon) {
                        icon.className = pwRules[rule].valid ? 'fas fa-check-circle' : 'fas fa-circle';
                    }
                }
            });

            // Update bar
            const percentage = (score / total) * 100;
            if (strengthBar) {
                strengthBar.style.width = percentage + '%';
            }

            // Update label
            let label = 'Weak';
            let color = '#EF4444';
            if (percentage >= 80) {
                label = 'Strong';
                color = '#22C55E';
            } else if (percentage >= 60) {
                label = 'Good';
                color = '#F59E0B';
            } else if (percentage >= 40) {
                label = 'Fair';
                color = '#F59E0B';
            }

            if (strengthBar) {
                strengthBar.style.background = color;
            }
            if (strengthText) {
                strengthText.textContent = label;
                strengthText.style.color = color;
            }

            return score === total;
        }

        if (passwordInput) {
            passwordInput.addEventListener('input', function() {
                checkPwStrength(this.value);
            });

            // Auto-expand requirements on focus
            passwordInput.addEventListener('focus', function() {
                const reqList = document.getElementById('signupRequirements');
                if (reqList && !reqList.classList.contains('open') && this.value.length > 0) {
                    reqList.classList.add('open');
                    if (reqToggle) reqToggle.classList.add('active');
                }
            });
        }

        // ---- Real-time Password Confirmation ----
        const confirmInput = document.getElementById('signup_password_confirmation');
        const confirmError = document.querySelector('[data-error="signup_password_confirmation"]');

        if (confirmInput && passwordInput) {
            const checkConfirm = () => {
                if (confirmInput.value && confirmInput.value !== passwordInput.value) {
                    confirmError.textContent = 'Passwords do not match.';
                    return false;
                } else {
                    confirmError.textContent = '';
                    return true;
                }
            };

            confirmInput.addEventListener('input', checkConfirm);
            passwordInput.addEventListener('input', checkConfirm);
        }

        // ---- Form Submission ----
        const submitBtn = document.getElementById('signupSubmitBtn');

        form.addEventListener('submit', function(e) {
            e.preventDefault();

            let isValid = true;

            // Reset errors
            document.querySelectorAll('.admin-signup__form-error').forEach((el) => el.textContent = '');

            // Validate required fields
            const requiredFields = form.querySelectorAll('[required]');
            requiredFields.forEach((field) => {
                if (!field.value.trim()) {
                    const errorEl = document.querySelector(`[data-error="${field.id}"]`);
                    if (errorEl) {
                        errorEl.textContent = 'This field is required.';
                    }
                    isValid = false;
                }
            });

            // Validate email
            const email = document.getElementById('signup_email');
            if (email && email.value && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) {
                const errorEl = document.querySelector('[data-error="signup_email"]');
                if (errorEl) errorEl.textContent = 'Please enter a valid email address.';
                isValid = false;
            }

            // Validate password strength
            if (passwordInput && !checkPwStrength(passwordInput.value)) {
                const errorEl = document.querySelector('[data-error="signup_password"]');
                if (errorEl) errorEl.textContent = 'Password must meet all requirements.';
                isValid = false;
            }

            // Validate password match
            if (confirmInput && confirmInput.value !== passwordInput.value) {
                const errorEl = document.querySelector('[data-error="signup_password_confirmation"]');
                if (errorEl) errorEl.textContent = 'Passwords do not match.';
                isValid = false;
            }

            // Validate terms
            const terms = document.getElementById('signup_terms');
            const termsError = document.querySelector('[data-error="signup_terms"]');
            if (terms && !terms.checked) {
                if (termsError) termsError.textContent = 'You must agree to the Terms & Conditions and Privacy Policy.';
                isValid = false;
            }

            if (!isValid) {
                // Focus first invalid field
                const firstError = form.querySelector('.admin-signup__form-error:not(:empty)');
                if (firstError) {
                    const field = firstError.closest('.admin-signup__form-group')?.querySelector('input');
                    if (field) field.focus();
                }
                return;
            }

            // Show loading state
            submitBtn.disabled = true;
            const originalHTML = submitBtn.innerHTML;
            submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin" aria-hidden="true"></i> Creating...';

            // Simulate API call (replace with actual Laravel integration)
            setTimeout(() => {
                // Success state (demo)
                submitBtn.innerHTML = '<i class="fas fa-check" aria-hidden="true"></i> Account Created!';
                submitBtn.style.background = 'linear-gradient(135deg, #22C55E, #16A34A)';
                submitBtn.style.color = '#fff';

                // Reset after demo
                setTimeout(() => {
                    submitBtn.disabled = false;
                    submitBtn.innerHTML = originalHTML;
                    submitBtn.style.background = '';
                    submitBtn.style.color = '';
                    console.log('✅ Super Admin account would be created here.');
                    // In production: form.submit();
                }, 1800);
            }, 1200);
        });

        // ---- Button Ripple Effect ----
        if (submitBtn) {
            submitBtn.addEventListener('click', function(e) {
                const rect = this.getBoundingClientRect();
                const ripple = document.createElement('span');
                const size = Math.max(rect.width, rect.height);
                const x = e.clientX - rect.left - size / 2;
                const y = e.clientY - rect.top - size / 2;
                ripple.style.width = ripple.style.height = size + 'px';
                ripple.style.left = x + 'px';
                ripple.style.top = y + 'px';
                ripple.classList.add('ripple');
                this.appendChild(ripple);
                setTimeout(() => ripple.remove(), 600);
            });
        }

        // ---- Floating label fix for autofill ----
        document.querySelectorAll('.admin-signup__form-input').forEach((input) => {
            // Handle browser autofill
            if (input.value) {
                input.dispatchEvent(new Event('input'));
            }
        });

        console.log('✅ Super Admin Sign Up page initialized.');
    };

    // Initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initSuperAdminSignup);
    } else {
        initSuperAdminSignup();
    }

/* ==================================================
END: Super Admin Sign Up Hero & Registration JavaScript
================================================== */

