    // ============================================================
    // 134. BRAND HERO & STORY — INTERACTIONS & ANIMATIONS
    // ============================================================
    const initBrandHero = () => {
        // ----- Hero Buttons -----
        const servicesBtn = document.querySelector('.btn-brand-services');
        const contactBtn = document.querySelector('.btn-brand-contact');

        if (servicesBtn) {
            servicesBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📋 Explore Services from Brand page');
                this.style.transform = 'scale(0.98)';
                setTimeout(() => {
                    this.style.transform = '';
                }, 200);
            });
        }

        if (contactBtn) {
            contactBtn.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📞 Contact Us from Brand page');
                this.style.transform = 'scale(0.98)';
                setTimeout(() => {
                    this.style.transform = '';
                }, 200);
            });
        }

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const bhBadge = document.querySelector('.brand-hero__badge');
        const bhTitle = document.querySelector('.brand-hero__title');
        const bhSubtitle = document.querySelector('.brand-hero__subtitle');
        const bhActions = document.querySelector('.brand-hero__actions');
        const bhVisual = document.querySelector('.brand-hero__visual');

        // Set initial state for hero elements
        const heroElementsBH = [bhBadge, bhTitle, bhSubtitle, bhActions, bhVisual];
        heroElementsBH.forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(24px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${(index * 80)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${(index * 80)}ms`;
            }
        });

        // Set initial state for story blocks
        const storyBlocks = document.querySelectorAll('.brand-story__block');
        storyBlocks.forEach((block, index) => {
            block.style.opacity = '0';
            block.style.transform = 'translateY(20px)';
            block.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 100)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 100)}ms`;
        });

        // Set initial state for quote card
        const quoteCard = document.querySelector('.brand-story__quote-card');
        if (quoteCard) {
            quoteCard.style.opacity = '0';
            quoteCard.style.transform = 'translateY(30px) scale(0.98)';
            quoteCard.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 300ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) 300ms';
        }

        // ----- Observer -----
        const brandObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    // Animate hero elements
                    heroElementsBH.forEach((el) => {
                        if (el) {
                            el.style.opacity = '1';
                            el.style.transform = 'translateY(0)';
                        }
                    });

                    // Animate story blocks
                    storyBlocks.forEach((block) => {
                        block.style.opacity = '1';
                        block.style.transform = 'translateY(0)';
                    });

                    // Animate quote card
                    if (quoteCard) {
                        quoteCard.style.opacity = '1';
                        quoteCard.style.transform = 'translateY(0) scale(1)';
                    }

                    brandObserver.disconnect();
                }
            });
        }, {
            threshold: 0.05,
            rootMargin: '0px 0px -30px 0px'
        });

        // Observe both sections
        const heroSection = document.getElementById('brand-hero');
        const storySection = document.getElementById('brand-story');

        if (heroSection && storySection) {
            // Use a single observer that triggers when either section is visible
            const observer = new IntersectionObserver((entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        // Animate hero elements
                        heroElementsBH.forEach((el) => {
                            if (el) {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }
                        });

                        // Animate story blocks
                        storyBlocks.forEach((block) => {
                            block.style.opacity = '1';
                            block.style.transform = 'translateY(0)';
                        });

                        if (quoteCard) {
                            quoteCard.style.opacity = '1';
                            quoteCard.style.transform = 'translateY(0) scale(1)';
                        }

                        observer.disconnect();
                    }
                });
            }, {
                threshold: 0.05,
                rootMargin: '0px 0px -30px 0px'
            });

            // Observe the first section that triggers
            observer.observe(heroSection);
        }

        console.log('✅ Brand Hero & Story page initialized.');
    };

    // Initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBrandHero);
    } else {
        initBrandHero();
    }

