    // ============================================================
    // 135. BRAND SYMBOLISM — HOTSPOTS, CARDS & TIMELINE
    // ============================================================
    const initBrandSymbolism = () => {
        // ---- Hotspot Interactions ----
        const hotspots = document.querySelectorAll('.brand-symbolism__hotspot');
        const cards = document.querySelectorAll('.brand-symbolism__card');
        const activeLabel = document.querySelector('.brand-symbolism__active-label');

        // Map for card display names
        const cardNames = {
            'card-xo': 'Xo',
            'card-hub': 'Hub',
            'card-circuit': 'Circuit Design',
            'card-green': 'Green Color',
            'card-purple': 'Purple Color',
            'card-typography': 'Typography',
            'card-tagline': 'Tagline'
        };

        // Function to highlight a card
        function highlightCard(targetId) {
            // Remove all active states
            cards.forEach(c => c.classList.remove('active'));
            hotspots.forEach(h => h.classList.remove('active'));

            // Highlight target card
            const targetCard = document.getElementById(targetId);
            if (targetCard) {
                targetCard.classList.add('active');
            }

            // Highlight corresponding hotspot
            hotspots.forEach(h => {
                if (h.getAttribute('data-target') === targetId) {
                    h.classList.add('active');
                }
            });

            // Update label
            if (activeLabel) {
                const name = cardNames[targetId] || targetId.replace('card-', '');
                activeLabel.textContent = `Exploring: ${name}`;
                activeLabel.classList.add('highlighted');
            }
        }

        // Hotspot hover/click events
        hotspots.forEach((hotspot) => {
            // Hover
            hotspot.addEventListener('mouseenter', function() {
                const targetId = this.getAttribute('data-target');
                highlightCard(targetId);
            });

            // Click for mobile support
            hotspot.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = this.getAttribute('data-target');
                highlightCard(targetId);
            });

            // Focus for keyboard
            hotspot.addEventListener('focus', function() {
                const targetId = this.getAttribute('data-target');
                highlightCard(targetId);
            });
        });

        // Reset highlight on mouse leave from showcase
        const showcase = document.querySelector('.brand-symbolism__showcase');
        if (showcase) {
            showcase.addEventListener('mouseleave', function() {
                // Don't reset if we're on mobile (click behavior)
                if (window.innerWidth <= 576) return;

                cards.forEach(c => c.classList.remove('active'));
                hotspots.forEach(h => h.classList.remove('active'));
                if (activeLabel) {
                    activeLabel.textContent = 'Hover a hotspot to learn more';
                    activeLabel.classList.remove('highlighted');
                }
            });
        }

        // ---- Card click to scroll to top of cards section (mobile friendly) ----
        cards.forEach((card) => {
            card.addEventListener('click', function() {
                // On mobile, clicking a card shows its content
                if (window.innerWidth <= 576) {
                    const targetId = this.id;
                    // Highlight this card
                    cards.forEach(c => c.classList.remove('active'));
                    this.classList.add('active');

                    if (activeLabel) {
                        const name = cardNames[targetId] || targetId.replace('card-', '');
                        activeLabel.textContent = `Exploring: ${name}`;
                        activeLabel.classList.add('highlighted');
                    }

                    // Scroll to cards section on mobile
                    const cardsSection = document.querySelector('.brand-symbolism__cards');
                    if (cardsSection) {
                        const offset = 80;
                        const targetPosition = cardsSection.getBoundingClientRect().top + window.pageYOffset - offset;
                        window.scrollTo({ top: targetPosition, behavior: 'smooth' });
                    }
                }
            });
        });

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const symBadge = document.querySelector('.brand-symbolism__badge');
        const symTitle = document.querySelector('.brand-symbolism__title');
        const symSubtitle = document.querySelector('.brand-symbolism__subtitle');
        const symShowcase = document.querySelector('.brand-symbolism__showcase');
        const symCards = document.querySelector('.brand-symbolism__cards');
        const symTimeline = document.querySelector('.brand-symbolism__timeline');
        const symQuote = document.querySelector('.brand-symbolism__quote-banner');

        // Set initial state for header elements
        const headerElementsSYM = [symBadge, symTitle, symSubtitle];
        headerElementsSYM.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        const sectionsSYM = [symShowcase, symCards, symTimeline, symQuote];
        sectionsSYM.forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for individual cards
        const allCards = document.querySelectorAll('.brand-symbolism__card');
        allCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(20px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 30)}ms`;
        });

        // Set initial state for timeline nodes
        const timelineNodes = document.querySelectorAll('.brand-symbolism__timeline-node');
        timelineNodes.forEach((node, index) => {
            node.style.opacity = '0';
            node.style.transform = 'translateY(15px)';
            node.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 30)}ms`;
        });

        // ----- Observer -----
        const symObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    headerElementsSYM.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    sectionsSYM.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    allCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 30));
                    });

                    timelineNodes.forEach((node, index) => {
                        setTimeout(() => {
                            node.style.opacity = '1';
                            node.style.transform = 'translateY(0)';
                        }, 320 + (index * 30));
                    });

                    symObserver.disconnect();
                }
            });
        }, {
            threshold: 0.05,
            rootMargin: '0px 0px -50px 0px'
        });

        const symSection = document.getElementById('brand-symbolism');
        if (symSection) {
            symObserver.observe(symSection);
        }

        console.log('✅ Brand Symbolism section initialized.');
    };

    // Initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBrandSymbolism);
    } else {
        initBrandSymbolism();
    }

