    // ============================================================
    // 137. BRAND PURPOSE — INTERACTIONS & ANIMATIONS
    // ============================================================
    const initBrandPurpose = () => {
        // ----- Mission & Vision Card Hover ----
        const purposeCards = document.querySelectorAll('.brand-purpose__card');

        purposeCards.forEach((card) => {
            card.addEventListener('mouseenter', function() {
                const glow = this.querySelector('.brand-purpose__card-glow');
                if (glow) {
                    glow.style.transform = 'scale(1.5)';
                    glow.style.transition = 'transform 0.6s ease';
                }
            });

            card.addEventListener('mouseleave', function() {
                const glow = this.querySelector('.brand-purpose__card-glow');
                if (glow) {
                    glow.style.transform = 'scale(1)';
                }
            });
        });

        // ----- Core Value Hover Effects ----
        const values = document.querySelectorAll('.brand-purpose__value');

        values.forEach((value) => {
            value.addEventListener('mouseenter', function() {
                const line = this.querySelector('.brand-purpose__value-line');
                if (line) {
                    line.style.width = '100%';
                }
            });

            value.addEventListener('mouseleave', function() {
                const line = this.querySelector('.brand-purpose__value-line');
                if (line) {
                    line.style.width = '0';
                }
            });
        });

        // ----- Commitment Buttons ----
        const commitServices = document.querySelector('.btn-commitment-services');
        const commitProject = document.querySelector('.btn-commitment-project');

        if (commitServices) {
            commitServices.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('📋 Explore Services from commitment banner');
                this.style.transform = 'scale(0.98)';
                setTimeout(() => {
                    this.style.transform = '';
                }, 200);
            });
        }

        if (commitProject) {
            commitProject.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('🚀 Start Your Project from commitment banner');
                this.style.transform = 'scale(0.98)';
                setTimeout(() => {
                    this.style.transform = '';
                }, 200);
            });
        }

        // ============================================================
        // SCROLL-TRIGGERED ANIMATIONS
        // ============================================================
        const puBadge = document.querySelector('.brand-purpose__badge');
        const puTitle = document.querySelector('.brand-purpose__title');
        const puSubtitle = document.querySelector('.brand-purpose__subtitle');
        const puShowcase = document.querySelector('.brand-purpose__showcase');
        const puValues = document.querySelector('.brand-purpose__values');
        const puTimeline = document.querySelector('.brand-purpose__timeline');
        const puCommitment = document.querySelector('.brand-purpose__commitment-banner');

        // Set initial state for header elements
        const headerElementsPU = [puBadge, puTitle, puSubtitle];
        headerElementsPU.forEach((el) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(20px)';
                el.style.transition = 'opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94), transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
            }
        });

        // Set initial state for sections
        const sectionsPU = [puShowcase, puValues, puTimeline, puCommitment];
        sectionsPU.forEach((el, index) => {
            if (el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = `opacity 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms, transform 0.7s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${100 + (index * 60)}ms`;
            }
        });

        // Set initial state for mission & vision cards
        const mvCards = document.querySelectorAll('.brand-purpose__card');
        mvCards.forEach((card, index) => {
            card.style.opacity = '0';
            card.style.transform = 'translateY(20px)';
            card.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 80)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${200 + (index * 80)}ms`;
        });

        // Set initial state for value cards
        const allValues = document.querySelectorAll('.brand-purpose__value');
        allValues.forEach((value, index) => {
            value.style.opacity = '0';
            value.style.transform = 'translateY(20px)';
            value.style.transition = `opacity 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 30)}ms, transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${220 + (index * 30)}ms`;
        });

        // Set initial state for timeline nodes
        const timelineNodes = document.querySelectorAll('.brand-purpose__timeline-node');
        timelineNodes.forEach((node, index) => {
            node.style.opacity = '0';
            node.style.transform = 'translateY(15px)';
            node.style.transition = `opacity 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 30)}ms, transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) ${240 + (index * 30)}ms`;
        });

        // ----- Observer -----
        const puObserver = new IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                if (entry.isIntersecting) {
                    headerElementsPU.forEach((el) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 100);
                        }
                    });

                    sectionsPU.forEach((el, index) => {
                        if (el) {
                            setTimeout(() => {
                                el.style.opacity = '1';
                                el.style.transform = 'translateY(0)';
                            }, 200 + (index * 60));
                        }
                    });

                    mvCards.forEach((card, index) => {
                        setTimeout(() => {
                            card.style.opacity = '1';
                            card.style.transform = 'translateY(0)';
                        }, 300 + (index * 80));
                    });

                    allValues.forEach((value, index) => {
                        setTimeout(() => {
                            value.style.opacity = '1';
                            value.style.transform = 'translateY(0)';
                        }, 320 + (index * 30));
                    });

                    timelineNodes.forEach((node, index) => {
                        setTimeout(() => {
                            node.style.opacity = '1';
                            node.style.transform = 'translateY(0)';
                        }, 340 + (index * 30));
                    });

                    puObserver.disconnect();
                }
            });
        }, {
            threshold: 0.05,
            rootMargin: '0px 0px -50px 0px'
        });

        const puSection = document.getElementById('brand-purpose');
        if (puSection) {
            puObserver.observe(puSection);
        }

        console.log('✅ Brand Purpose section initialized.');
    };

    // Initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBrandPurpose);
    } else {
        initBrandPurpose();
    }

/* ==================================================
END: Mission, Vision & Core Values JavaScript
================================================== */

